const isFailure = (record) => record.status >= 400;

const failures = (logs) => logs.filter(isFailure);

const pathsOf = (records) =>
  records.map((record) => record.path);

const unique = (values) => [...new Set(values)];

const sortAlphabetically = (values) =>
  [...values].sort((a, b) => a.localeCompare(b));

const analyze = (logs) =>
  sortAlphabetically(unique(pathsOf(failures(logs))));

const recordsForPath = (logs, path) =>
  logs.filter((record) => record.path === path);

const sum = (numbers) =>
  numbers.reduce((total, value) => total + value, 0);

const averageDuration = (records) => {
  if (records.length === 0) {
    return 0;
  }
  const durations = records.map((record) => record.duration);
  return sum(durations) / records.length;
};

const statusesForPath = (logs, path) => {
  const codes = recordsForPath(logs, path).map((record) => record.status);
  return sortAlphabetically(unique(codes).map(String));
};

const summarize = (logs) => {
  const failing = failures(logs);
  return analyze(logs).map((path) => ({
    path,
    hits: recordsForPath(failing, path).length,
    statuses: statusesForPath(failing, path),
    avgDuration: Math.round(averageDuration(recordsForPath(failing, path))),
  }));
};

const formatRow = (row) =>
  `${row.path} -> ${row.hits} failure(s), statuses [${row.statuses.join(", ")}], avg ${row.avgDuration}ms`;

const report = (logs) => summarize(logs).map(formatRow).join("\n");

const main = () => {
  const logs = [
    { status: 200, path: "/home", duration: 12 },
    { status: 404, path: "/missing", duration: 40 },
    { status: 500, path: "/api/users", duration: 310 },
    { status: 503, path: "/api/users", duration: 290 },
    { status: 301, path: "/old", duration: 8 },
    { status: 404, path: "/missing", duration: 35 },
  ];

  console.log("Failing paths:", analyze(logs));
  console.log(report(logs));
};

main();

module.exports = {
  isFailure,
  failures,
  pathsOf,
  unique,
  sortAlphabetically,
  analyze,
  summarize,
  report,
};

