const isValidItem = (item) =>
  typeof item.price === 'number' &&
  typeof item.quantity === 'number' &&
  item.price >= 0 &&
  item.quantity >= 0;

const validate = (cart) => {
  if (!Array.isArray(cart)) {
    throw new TypeError('cart must be an array of items');
  }
  const bad = cart.filter(item => !isValidItem(item));
  if (bad.length > 0) {
    throw new RangeError(`invalid item(s) in cart: ${bad.length}`);
  }
  return cart;
};

const excludeClearance = (cart) =>
  cart.filter(item => !item.clearance);

const subtotals = (items) =>
  items.map(item => item.price * item.quantity);

const applyDiscount = (subtotal) =>
  subtotal > 50 ? subtotal * 0.9 : subtotal;

const sumAll = (amounts) =>
  amounts.reduce((acc, n) => acc + n, 0);

const round2 = (n) => Math.round(n * 100) / 100;

const checkout = (cart) => {
  const billable = excludeClearance(validate(cart));
  const discounted = subtotals(billable).map(s => applyDiscount(s));
  return round2(sumAll(discounted));
};

const describeLine = (item) => {
  const raw = item.price * item.quantity;
  const charged = item.clearance ? 0 : applyDiscount(raw);
  const note = item.clearance
    ? 'clearance, not billed'
    : charged < raw
      ? 'discount 10% applied'
      : 'full price';
  return `${item.quantity} x ${item.price.toFixed(2)} = ${round2(charged).toFixed(2)} (${note})`;
};

const report = (cart) => {
  const lines = cart.map(item => describeLine(item));
  lines.push(`TOTAL: ${checkout(cart).toFixed(2)}`);
  return lines.join('\n');
};

const main = () => {
  const cart = [
    { price: 12.5, quantity: 2, clearance: false },
    { price: 80, quantity: 1, clearance: false },
    { price: 30, quantity: 3, clearance: true },
  ];
  console.log(report(cart));
};

main();

module.exports = {
  excludeClearance,
  subtotals,
  applyDiscount,
  sumAll,
  checkout,
  report,
};

