const isFiniteNumber = (value) =>
  typeof value === 'number' && Number.isFinite(value);

const toScore = (raw) => {
  const score = typeof raw === 'string' ? Number(raw.trim()) : raw;
  if (!isFiniteNumber(score)) {
    throw new TypeError(`invalid score: ${String(raw)}`);
  }
  return score;
};

const normalizeScores = (scores) => {
  if (!Array.isArray(scores)) {
    throw new TypeError('scores must be an array of numbers');
  }
  return scores.map(toScore);
};

const add = (total, n) => total + n;

const sum = (numbers) => numbers.reduce(add, 0);

const averageScore = (student) => {
  const scores = normalizeScores(student.scores);
  if (scores.length === 0) {
    return 0;
  }
  return sum(scores) / scores.length;
};

const PASS_MARK = 60;

const isFailing = (student) => averageScore(student) < PASS_MARK;

const failingStudents = (students) => students.filter(isFailing);

const identifierOf = (student) => {
  const id = student.id !== undefined ? student.id : student.name;
  if (typeof id !== 'string' || id.trim() === '') {
    throw new TypeError('each student needs a non-empty string identifier');
  }
  return id.trim();
};

const identifiersOf = (students) => students.map(identifierOf);

const byName = (a, b) => a.localeCompare(b);

const sortAlphabetically = (ids) => [...ids].sort(byName);

const evaluate = (students) => {
  if (!Array.isArray(students)) {
    throw new TypeError('students must be an array of records');
  }
  return sortAlphabetically(identifiersOf(failingStudents(students)));
};

const describe = (student) => {
  const average = averageScore(student);
  const verdict = isFailing(student) ? 'FAIL' : 'PASS';
  return `${identifierOf(student).padEnd(8)} avg=${average.toFixed(1).padStart(5)} ${verdict}`;
};

const formatReport = (students) => {
  const lines = students.map(describe);
  const failed = evaluate(students);
  lines.push(`failing (${failed.length}): ${failed.join(', ') || 'none'}`);
  return lines.join('\n');
};

const main = () => {
  const roster = [
    { id: 'alice', scores: [88, 92, 79] },
    { id: 'bob', scores: [55, 48, '61'] },
  ];
  console.log(formatReport(roster));
  console.log(evaluate(roster));
};

module.exports = { averageScore, failingStudents, identifiersOf, evaluate, formatReport };

if (require.main === module) {
  main();
}

