const isValidRecord = (record) =>
  record !== null &&
  typeof record === 'object' &&
  typeof record.name === 'string' &&
  Number.isFinite(record.stock) &&
  Number.isFinite(record.minimum);

const normalize = (record) => ({
  name: record.name.trim(),
  stock: record.stock,
  minimum: record.minimum,
});

const parseInventory = (inventory) => {
  if (!Array.isArray(inventory)) {
    throw new TypeError('restock expects an array of inventory records');
  }
  const invalid = inventory.filter(record => !isValidRecord(record));
  if (invalid.length > 0) {
    throw new TypeError(`malformed inventory records: ${invalid.length}`);
  }
  return inventory.map(normalize);
};

const isShort = (record) => record.stock < record.minimum;

const belowMinimum = (records) => records.filter(isShort);

const withDeficit = (records) =>
  records.map(record => ({
    name: record.name,
    deficit: record.minimum - record.stock,
  }));

const pluralizeUnits = (amount) => (amount === 1 ? 'unit' : 'units');

const formatAlert = (item) =>
  `Restock ${item.name}: order ${item.deficit} more ${pluralizeUnits(item.deficit)}.`;

const formatAlerts = (items) => items.map(formatAlert);

const byLargestDeficit = (a, b) => b.deficit - a.deficit || a.name.localeCompare(b.name);

const restock = (inventory) => {
  const records = parseInventory(inventory);
  const shortages = withDeficit(belowMinimum(records));
  return formatAlerts(shortages.sort(byLargestDeficit));
};

const summarize = (alerts) => {
  if (alerts.length === 0) {
    return 'All stock levels are healthy.';
  }
  const header = `${alerts.length} item(s) need ordering:`;
  const body = alerts.map(alert => `  - ${alert}`).join('\n');
  return `${header}\n${body}`;
};

const main = () => {
  const inventory = [
    { name: 'apples', stock: 4, minimum: 20 },
    { name: 'bananas', stock: 30, minimum: 12 },
    { name: 'cherries', stock: 9, minimum: 10 },
    { name: 'dates', stock: 0, minimum: 5 },
  ];
  console.log(summarize(restock(inventory)));
};

main();

module.exports = { restock, belowMinimum, withDeficit, formatAlerts, summarize };

