const isNumeric = (value) => typeof value === 'number' && Number.isFinite(value);

const requireNumeric = (readings) => {
  if (!Array.isArray(readings)) {
    throw new TypeError('smooth expects an array of numeric measurements');
  }
  const bad = readings.findIndex((value) => !isNumeric(value));
  if (bad !== -1) {
    throw new TypeError(`measurement at index ${bad} is not a finite number`);
  }
  return readings;
};

const inSensorRange = (value) => value >= 0 && value <= 100;

const keepValid = (readings) => readings.filter(inSensorRange);

const adjacentDeltas = (readings) =>
  readings.slice(1).map((value, index) => Math.abs(value - readings[index]));

const JUMP_THRESHOLD = 10;

const exceedsThreshold = (delta) => delta > JUMP_THRESHOLD;

const largeJumps = (deltas) => deltas.filter(exceedsThreshold);

const smooth = (readings) => {
  const valid = keepValid(requireNumeric(readings));
  return largeJumps(adjacentDeltas(valid)).length;
};

const analyse = (readings) => {
  const valid = keepValid(requireNumeric(readings));
  const deltas = adjacentDeltas(valid);
  return {
    kept: valid,
    discarded: readings.filter((value) => !inSensorRange(value)),
    deltas,
    jumps: largeJumps(deltas),
  };
};

const formatList = (values) => (values.length ? values.join(', ') : '(none)');

const describe = (label, readings) => {
  const { kept, discarded, deltas, jumps } = analyse(readings);
  const lines = [
    `${label}: ${formatList(readings)}`,
    `  valid      -> ${formatList(kept)}`,
    `  discarded  -> ${formatList(discarded)}`,
    `  deltas     -> ${formatList(deltas.map((delta) => delta.toFixed(1)))}`,
    `  jumps > ${JUMP_THRESHOLD} -> ${formatList(jumps)}`,
    `  smooth()   -> ${smooth(readings)}`,
  ];
  return lines.join('\n');
};

const main = () => {
  const samples = [
    ['anomaly and one large jump', [20, 22, 105, 24, 40, 41]],
    ['steady sensor', [50, 51, 52, 53]],
    ['all readings rejected', [-5, 120, 999]],
  ];
  samples.forEach(([label, readings]) => console.log(describe(label, readings)));
  const totals = samples.reduce((sum, [, readings]) => sum + smooth(readings), 0);
  console.log(`total large jumps across samples: ${totals}`);
};

module.exports = { smooth, keepValid, adjacentDeltas, largeJumps, analyse, describe };

if (require.main === module) {
  main();
}

