const isWater = (ingredient) => ingredient.name.trim().toLowerCase() === 'water';

const removeWater = (ingredients) => ingredients.filter(
  item => !isWater(item)
);

const validate = (ingredients) => {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be an array');
  }
  return ingredients.map((item, index) => {
    const { name, caloriesPerGram, grams } = item;
    if (typeof name !== 'string' || name.length === 0) {
      throw new TypeError(`ingredient ${index} is missing a name`);
    }
    if (!Number.isFinite(caloriesPerGram) || !Number.isFinite(grams)) {
      throw new TypeError(`ingredient "${name}" has non-numeric values`);
    }
    if (caloriesPerGram < 0 || grams < 0) {
      throw new RangeError(`ingredient "${name}" has negative values`);
    }
    return { name, caloriesPerGram, grams };
  });
};

const caloriesOf = (ingredient) => ingredient.caloriesPerGram * ingredient.grams;

const toEntry = (item) => ({ name: item.name, calories: caloriesOf(item) });

const withTotals = (ingredients) => ingredients.map(toEntry);

const addCalories = (total, entry) => total + entry.calories;

const sumCalories = (entries) => entries.reduce(addCalories, 0);

const calculate = (ingredients) => {
  const clean = removeWater(validate(ingredients));
  return sumCalories(withTotals(clean));
};

const formatEntry = (entry, width) => {
  const label = entry.name.padEnd(width, ' ');
  return `${label}  ${entry.calories.toFixed(1)} kcal`;
};

const widestName = (widest, entry) => Math.max(widest, entry.name.length);

const report = (ingredients) => {
  const entries = withTotals(removeWater(validate(ingredients)));
  const width = entries.reduce(widestName, 0);
  const lines = entries.map(
    entry => formatEntry(entry, width)
  );
  lines.push(formatEntry({ name: 'TOTAL', calories: sumCalories(entries) }, width));
  return lines.join('\n');
};

const recipe = [
  { name: 'water', caloriesPerGram: 0, grams: 250 },
  { name: 'sugar', caloriesPerGram: 3.87, grams: 100 },
  { name: 'flour', caloriesPerGram: 3.64, grams: 200 },
];

console.log(report(recipe));
console.log(`Total calories: ${calculate(recipe)}`);

module.exports = { calculate, removeWater, withTotals, sumCalories, report };

