const SEVERE_DELAY_MINUTES = 30;

const isValidRecord = (record) =>
  record !== null &&
  typeof record === 'object' &&
  typeof record.id === 'string' &&
  Number.isFinite(record.scheduled) &&
  Number.isFinite(record.actual);

const validateFlights = (flights) => {
  if (!Array.isArray(flights)) {
    throw new TypeError('track() expects an array of flight records');
  }
  const bad = flights.filter((record) => !isValidRecord(record));
  if (bad.length > 0) {
    throw new TypeError(`malformed flight record(s): ${JSON.stringify(bad)}`);
  }
  return flights;
};

const selectDelayed = (flights) =>
  flights.filter((f) => f.actual > f.scheduled);

const computeDelays = (delayedFlights) =>
  delayedFlights.map((f) => ({ id: f.id, delay: f.actual - f.scheduled }));

const extractSevereIds = (delays) =>
  delays
    .filter((entry) => entry.delay > SEVERE_DELAY_MINUTES)
    .map((entry) => entry.id);

const byIdentifier = (a, b) => a.localeCompare(b);

const track = (flights) =>
  extractSevereIds(computeDelays(selectDelayed(validateFlights(flights)))).sort(byIdentifier);

const pad2 = (n) => String(n).padStart(2, '0');

const formatClock = (minutes) =>
  `${pad2(Math.floor(minutes / 60) % 24)}:${pad2(minutes % 60)}`;

const describeFlight = (flight) => {
  const delay = flight.actual - flight.scheduled;
  const status = delay > 0 ? `+${delay} min` : 'on time';
  return `${flight.id}  sched ${formatClock(flight.scheduled)}  act ${formatClock(flight.actual)}  ${status}`;
};

const summarize = (severeIds) =>
  severeIds.length === 0
    ? `No flights delayed by more than ${SEVERE_DELAY_MINUTES} minutes.`
    : `Severely delayed (> ${SEVERE_DELAY_MINUTES} min): ${severeIds.join(', ')}`;

const buildReport = (flights) => {
  const lines = flights.map((f) => describeFlight(f));
  return lines.concat(['', summarize(track(flights))]).join('\n');
};

const main = () => {
  const flights = [
    { id: 'AA101', scheduled: 480, actual: 480 },
    { id: 'DL220', scheduled: 545, actual: 560 },
    { id: 'UA915', scheduled: 610, actual: 700 },
  ];
  console.log(buildReport(flights));
  console.log(track(flights));
};

if (require.main === module) {
  main();
}

module.exports = { track, selectDelayed, computeDelays, extractSevereIds, buildReport };

