const isRunnable = (task) => task.blocked !== true;

const dropBlocked = (tasks) => tasks.filter(isRunnable);

const validate = (task, index) => {
  if (typeof task.description !== 'string' || task.description.trim() === '') {
    throw new TypeError(`task ${index}: description must be a non-empty string`);
  }
  if (typeof task.priority !== 'number' || Number.isNaN(task.priority)) {
    throw new TypeError(`task ${index}: priority must be a number`);
  }
  return task;
};

const toItem = (task, index) => {
  const checked = validate(task, index);
  return { description: checked.description.trim(), priority: checked.priority };
};

const extract = (tasks) =>
  tasks.map(toItem);

const byPriorityDesc = (a, b) => b.priority - a.priority;

const sortByPriority = (items) => [...items].sort(byPriorityDesc);

const describe = (items) =>
  items.map(item => item.description);

const resolve = (tasks) => {
  if (!Array.isArray(tasks)) {
    throw new TypeError('resolve expects an array of task records');
  }
  return describe(sortByPriority(extract(dropBlocked(tasks))));
};

const formatReport = (tasks) => {
  const order = resolve(tasks);
  const blocked = tasks.filter(task => !isRunnable(task));
  const lines = order.map((description, index) => `${index + 1}. ${description}`);
  lines.push(`(${blocked.length} blocked task(s) skipped)`);
  return lines.join('\n');
};

const main = () => {
  const backlog = [
    { description: 'Write deployment scripts', priority: 2, blocked: false },
    { description: 'Migrate the database', priority: 9, blocked: true },
    { description: 'Review security audit', priority: 7, blocked: false },
  ];
  console.log(resolve(backlog));
  console.log(formatReport(backlog));
};

main();

module.exports = {
  dropBlocked,
  extract,
  sortByPriority,
  describe,
  resolve,
  formatReport,
};

