const DRIFT_THRESHOLD = 5;

const roundTo = (value, places = 2) => {
  const factor = 10 ** places;
  return Math.round(value * factor) / factor;
};

const normalizeAsset = (asset) => ({
  ticker: String(asset.ticker).toUpperCase().trim(),
  current: Number(asset.current),
  target: Number(asset.target),
});

const isValidAsset = (asset) =>
  asset.ticker.length > 0 &&
  Number.isFinite(asset.current) &&
  Number.isFinite(asset.target);

const computeDrift = (asset) => ({
  ...asset,
  drift: roundTo(Math.abs(asset.current - asset.target)),
});

const exceedsThreshold = (asset) => asset.drift > DRIFT_THRESHOLD;

const findDrifted = (assets) => assets.filter(exceedsThreshold);

const describeDirection = (asset) =>
  asset.current > asset.target ? 'overweight' : 'underweight';

const formatWarning = (asset) => {
  const direction = describeDirection(asset);
  return `${asset.ticker} is ${direction} by ${asset.drift}% ` +
    `(current ${roundTo(asset.current)}%, target ${roundTo(asset.target)}%): rebalance recommended.`;
};

const rebalance = (assets) => {
  if (!Array.isArray(assets)) {
    throw new TypeError('rebalance expects an array of asset records');
  }
  const cleaned = assets.map(normalizeAsset).filter(isValidAsset);
  if (cleaned.length !== assets.length) {
    throw new Error('one or more asset records are malformed');
  }
  const withDrift = cleaned.map(computeDrift);
  return findDrifted(withDrift).map(formatWarning);
};

const totalWeight = (assets) =>
  assets.reduce((sum, a) => sum + Number(a.current), 0);

const summarize = (assets) => {
  const warnings = rebalance(assets);
  const allocated = roundTo(totalWeight(assets));
  const header = warnings.length === 0
    ? `All ${assets.length} positions within ${DRIFT_THRESHOLD}% of target.`
    : `${warnings.length} of ${assets.length} positions require attention.`;
  return [`Allocated: ${allocated}%`, header, ...warnings];
};

const portfolio = [
  { ticker: 'vti', current: 62.4, target: 55 },
  { ticker: 'bnd', current: 22.1, target: 25 },
  { ticker: 'vxus', current: 13.0, target: 15 },
  { ticker: 'gld', current: 2.5, target: 5 },
];

summarize(portfolio).forEach(line => console.log(line));

module.exports = {
  rebalance,
  computeDrift,
  findDrifted,
  formatWarning,
  summarize,
};

