const MAX_DISTANCE = 20;
const MAX_PRICE_PER_SQFT = 200;

const isValidProperty = (property) => {
  const fields = ['distance', 'price', 'sqft'];
  return fields.every(field => typeof property[field] === 'number' && Number.isFinite(property[field]));
};

const validate = (properties) => {
  if (!Array.isArray(properties)) {
    throw new TypeError('match() expects an array of property records');
  }
  const bad = properties.findIndex(property => !isValidProperty(property));
  if (bad !== -1) {
    throw new TypeError(`property at index ${bad} is missing numeric distance/price/sqft`);
  }
  return properties;
};

const isNearby = (property) => property.distance <= MAX_DISTANCE;

const nearby = (properties) => properties.filter(isNearby);

const addPricePerSqft = (property) => ({
  ...property,
  pricePerSqft: property.price / property.sqft
});

const withPricePerSqft = (properties) => properties.map(addPricePerSqft);

const isAffordable = (property) => property.pricePerSqft < MAX_PRICE_PER_SQFT;

const affordable = (properties) => properties.filter(isAffordable);

const distancesAscending = (properties) => properties
  .map(property => property.distance)
  .sort((a, b) => a - b);

const match = (properties) => {
  const checked = validate(properties);
  return distancesAscending(affordable(withPricePerSqft(nearby(checked))));
};

const formatMoney = (amount) => `$${amount.toFixed(2)}`;

const describe = (property) => {
  const perSqft = property.price / property.sqft;
  return `${property.distance} mi · ${formatMoney(property.price)} · ${property.sqft} sqft · ${formatMoney(perSqft)}/sqft`;
};

const report = (properties) => {
  const matches = match(properties);
  const summary = matches.length
    ? `matching distances (nearest first): ${matches.join(', ')}`
    : 'no properties matched';
  return [
    'candidates:',
    ...properties.map(property => `  ${describe(property)}`),
    summary
  ].join('\n');
};

const main = () => {
  const listings = [
    { distance: 12, price: 250000, sqft: 1400 },
    { distance: 32, price: 180000, sqft: 1500 },
    { distance: 5, price: 400000, sqft: 1000 },
    { distance: 8, price: 210000, sqft: 1300 }
  ];
  console.log(report(listings));
};

main();

module.exports = { match, nearby, withPricePerSqft, affordable, distancesAscending, report };

