const VALID_BASES = /^[ACGT]+$/i;

const normalize = (seq) => seq.trim().toUpperCase();

const hasAmbiguous = (seq) => seq.includes('N');

const isUsable = (seq) => seq.length > 0 && !hasAmbiguous(seq);

const filterValid = (sequences) => sequences
  .map(normalize)
  .filter(isUsable);

const lengthOf = (seq) => seq.length;

const measureLengths = (sequences) => sequences.map(lengthOf);

const isCodonAligned = (len) => len % 3 === 0;

const keepCodonAligned = (lengths) => lengths.filter(isCodonAligned);

const add = (total, len) => total + len;

const sumLengths = (lengths) => lengths.reduce(add, 0);

const assertSequences = (sequences) => {
  if (!Array.isArray(sequences)) {
    throw new TypeError('analyze expects an array of DNA sequences');
  }
  const offender = sequences.find(seq => typeof seq !== 'string');
  if (offender !== undefined) {
    throw new TypeError(`sequence is not a string: ${String(offender)}`);
  }
};

const analyze = (sequences) => {
  assertSequences(sequences);
  const valid = filterValid(sequences);
  const aligned = keepCodonAligned(measureLengths(valid));
  return sumLengths(aligned);
};

const classify = (seq) => {
  const cleaned = normalize(seq);
  if (hasAmbiguous(cleaned)) return 'ambiguous';
  if (!VALID_BASES.test(cleaned)) return 'malformed';
  return isCodonAligned(cleaned.length) ? 'counted' : 'not-in-frame';
};

const formatEntry = (seq, index) => {
  const label = classify(seq);
  return `#${index + 1} len=${normalize(seq).length} ${label}`;
};

const describe = (sequences) => sequences.map(formatEntry);

const gcContent = (seq) => {
  const cleaned = normalize(seq);
  const gc = cleaned.split('').filter(base => base === 'G' || base === 'C');
  return cleaned.length === 0 ? 0 : gc.length / cleaned.length;
};

const gcPercent = (seq) => gcContent(seq) * 100;

const report = (sequences) => {
  const valid = filterValid(sequences);
  const averageGc = valid.length === 0
    ? 0
    : sumLengths(valid.map(gcPercent)) / valid.length;
  describe(sequences).forEach(line => console.log(line));
  console.log(`mean GC of valid sequences: ${averageGc.toFixed(1)}%`);
  console.log(`total codon-aligned length: ${analyze(sequences)}`);
};

const main = () => {
  const samples = ['ACGTACGTAC', 'ACGNTTGCAA', 'GGGCCCTTTAAA'];
  report(samples);
};

main();

module.exports = { analyze, filterValid, measureLengths, keepCodonAligned, sumLengths, report };

