const LARGE_PAYLOAD_BYTES = 1000;

const isCorrupted = (packet) => Boolean(packet.corrupted);

const validatePacket = (packet, index) => {
  if (packet === null || typeof packet !== 'object') {
    throw new TypeError(`packet ${index} is not a record`);
  }
  if (typeof packet.source !== 'string' || packet.source.length === 0) {
    throw new TypeError(`packet ${index} has no source address`);
  }
  if (typeof packet.size !== 'number' || !Number.isFinite(packet.size) || packet.size < 0) {
    throw new TypeError(`packet ${index} has an invalid payload size`);
  }
  return packet;
};

const validateAll = (packets) => {
  if (!Array.isArray(packets)) {
    throw new TypeError('packets must be an array');
  }
  return packets.map(validatePacket);
};

const isHealthy = (packet) => !isCorrupted(packet);

const dropCorrupted = (packets) => packets.filter(isHealthy);

const sizeOf = (packet) => packet.size;

const payloadSizes = (packets) => packets.map(sizeOf);

const isLarge = (size) => size > LARGE_PAYLOAD_BYTES;

const largePayloads = (sizes) => sizes.filter(isLarge);

const addSizes = (sum, size) => sum + size;

const totalBytes = (sizes) => sizes.reduce(addSizes, 0);

const inspect = (packets) => {
  const healthy = dropCorrupted(validateAll(packets));
  return totalBytes(largePayloads(payloadSizes(healthy)));
};

const accumulateBySource = (acc, packet) => {
  if (isLarge(packet.size)) {
    acc[packet.source] = (acc[packet.source] || 0) + packet.size;
  }
  return acc;
};

const bytesBySource = (packets) => {
  const healthy = dropCorrupted(validateAll(packets));
  return healthy.reduce(accumulateBySource, {});
};

const formatBytes = (size) => `${(size / 1024).toFixed(2)} KiB`;

const report = (packets) => {
  const perSource = bytesBySource(packets);
  const byTrafficDesc = (a, b) => perSource[b] - perSource[a];
  const describe = (source) => `  ${source.padEnd(16)} ${formatBytes(perSource[source])}`;
  return [
    `large payload traffic (> ${LARGE_PAYLOAD_BYTES} bytes)`,
    ...Object.keys(perSource).sort(byTrafficDesc).map(describe),
    `  total: ${inspect(packets)} bytes`,
  ].join('\n');
};

const main = () => {
  const traffic = [
    { source: '10.0.0.1', size: 1500, corrupted: false },
    { source: '10.0.0.2', size: 400, corrupted: false },
    { source: '10.0.0.1', size: 9000, corrupted: true },
    { source: '10.0.0.3', size: 2048, corrupted: false },
    { source: '10.0.0.2', size: 1001, corrupted: false },
  ];
  console.log(report(traffic));
};

module.exports = { inspect, dropCorrupted, payloadSizes, largePayloads, totalBytes, report };

if (require.main === module) {
  main();
}

