const isClean = track => !track.explicit;

const cleanTracks = tracks => tracks.filter(isClean);

const durationOf = track => track.duration;

const durations = tracks => tracks.map(durationOf);

const toMinutes = seconds => seconds / 60;

const add = (total, value) => total + value;

const sum = values => values.reduce(add, 0);

const validateTrack = (track, index) => {
  if (typeof track.title !== 'string' || track.title.trim() === '') {
    throw new Error(`Track ${index} is missing a title`);
  }
  if (!Number.isFinite(track.duration) || track.duration < 0) {
    throw new Error(`Track "${track.title}" has an invalid duration`);
  }
  if (typeof track.explicit !== 'boolean') {
    throw new Error(`Track "${track.title}" needs an explicit flag`);
  }
  return track;
};

const validateAlbum = tracks => {
  if (!Array.isArray(tracks)) {
    throw new Error('An album must be an array of tracks');
  }
  return tracks.map(validateTrack);
};

function estimate(tracks) {
  const album = validateAlbum(tracks);
  return sum(durations(cleanTracks(album)).map(toMinutes));
}

const formatMinutes = minutes => {
  const whole = Math.floor(minutes);
  const seconds = Math.round((minutes - whole) * 60);
  return `${whole}:${String(seconds).padStart(2, '0')}`;
};

const titleOf = track => track.title;

const titlesOf = tracks => tracks.map(titleOf);

const report = tracks => {
  const album = validateAlbum(tracks);
  const kept = cleanTracks(album);
  const skipped = album.filter(track => track.explicit);
  const lines = titlesOf(kept).map(title => `  + ${title}`);
  titlesOf(skipped).forEach(title => lines.push(`  - ${title} (explicit)`));
  lines.push(`Clean playing time: ${formatMinutes(estimate(album))}`);
  return lines.join('\n');
};

const album = [
  { title: 'Sunrise Drive', duration: 214, explicit: false },
  { title: 'Concrete Heat', duration: 187, explicit: true },
  { title: 'Paper Lanterns', duration: 245, explicit: false },
  { title: 'Slow Ferry', duration: 330, explicit: false }
];

console.log(report(album));
console.log(estimate(album));

module.exports = { estimate, cleanTracks, durations, toMinutes, report };

