const isDryDay = (forecast) => forecast.precipitation < 50;

const dryDays = (forecasts) => forecasts.filter(isDryDay);

const highTemps = (days) => days.map(
  day => day.high
);

const fahrenheitToCelsius = (f) => (f - 32) * 5 / 9;

const toCelsius = (temps) => temps.map(fahrenheitToCelsius);

const larger = (best, value) => (value > best ? value : best);

const maxOf = (values) => values.reduce(larger, -Infinity);

const validateForecast = (forecast, index) => {
  if (typeof forecast !== 'object' || forecast === null) {
    throw new TypeError(`forecast at index ${index} is not a record`);
  }
  if (typeof forecast.day !== 'string' || forecast.day.length === 0) {
    throw new TypeError(`forecast at index ${index} has no day name`);
  }
  if (!Number.isFinite(forecast.high)) {
    throw new TypeError(`forecast for ${forecast.day} has a non-numeric high`);
  }
  if (!Number.isFinite(forecast.precipitation)) {
    throw new TypeError(`forecast for ${forecast.day} has a non-numeric precipitation`);
  }
  return forecast;
};

const summarize = (forecasts) => {
  if (!Array.isArray(forecasts)) {
    throw new TypeError('forecasts must be an array');
  }
  const checked = forecasts.map(validateForecast);
  const dry = dryDays(checked);
  if (dry.length === 0) {
    return NaN;
  }
  return maxOf(toCelsius(highTemps(dry)));
};

const round1 = (value) => Math.round(value * 10) / 10;

const describeDay = (forecast) => {
  const celsius = round1(fahrenheitToCelsius(forecast.high));
  const label = isDryDay(forecast) ? 'dry' : 'wet';
  return `${forecast.day.padEnd(10)} ${String(forecast.high).padStart(3)}F / ${celsius}C  ${label}`;
};

const report = (forecasts) => {
  const lines = forecasts.map(describeDay);
  const peak = summarize(forecasts);
  const summaryLine = Number.isNaN(peak)
    ? 'No dry days this week.'
    : `Hottest dry day: ${round1(peak)}C`;
  return lines.concat(summaryLine).join('\n');
};

const week = [
  { day: 'Monday', high: 72, precipitation: 10 },
  { day: 'Tuesday', high: 80, precipitation: 20 },
  { day: 'Wednesday', high: 95, precipitation: 75 },
  { day: 'Thursday', high: 68, precipitation: 55 },
  { day: 'Friday', high: 84, precipitation: 5 },
  { day: 'Saturday', high: 90, precipitation: 50 },
  { day: 'Sunday', high: 77, precipitation: 30 }
];

console.log(report(week));

module.exports = { summarize, dryDays, highTemps, toCelsius, maxOf, report };

