const MIN_HOURS = 20;

const isValidRecord = (record) => {
  if (!record || typeof record.name !== 'string' || typeof record.department !== 'string') {
    return false;
  }
  return Array.isArray(record.hours);
};

const normalizeDepartment = (department) => department.trim().toLowerCase();

const validate = (employees) => {
  if (!Array.isArray(employees)) {
    throw new TypeError('schedule expects an array of employee records');
  }
  const broken = employees.filter(record => !isValidRecord(record));
  if (broken.length > 0) {
    throw new TypeError(`malformed employee records: ${broken.length}`);
  }
  return employees;
};

const salesOnly = (employees) => employees.filter(
  employee => normalizeDepartment(employee.department) === 'sales'
);

const countHours = (salesEmployees) => salesEmployees.map(
  employee => ({ name: employee.name, hours: employee.hours.length })
);

const dropBelowMinimum = (counted) => counted.filter(
  entry => entry.hours >= MIN_HOURS
);

const schedule = (employees) => {
  const counted = countHours(salesOnly(validate(employees)));
  return dropBelowMinimum(counted).length;
};

const formatReport = (employees) => {
  const counted = countHours(salesOnly(validate(employees)));
  const qualifying = dropBelowMinimum(counted);
  const names = qualifying.map(entry => `${entry.name} (${entry.hours}h)`);
  const totalHours = qualifying.reduce((sum, entry) => sum + entry.hours, 0);
  const lines = [
    `sales employees examined: ${counted.length}`,
    `meeting the ${MIN_HOURS}-hour minimum: ${qualifying.length}`,
    `combined available hours: ${totalHours}`
  ];
  if (names.length > 0) {
    lines.push(`qualifying staff: ${names.join(', ')}`);
  }
  return lines.join('\n');
};

const makeHours = (count, start) => Array.from(
  { length: count },
  (_, offset) => start + offset
);

