  { name: 'Fay', department: 'sales', hours: makeHours(20, 12) }
];

console.log(formatReport(staff));
console.log(`schedule(staff) = ${schedule(staff)}`);

module.exports = { schedule, salesOnly, countHours, dropBelowMinimum, formatReport };

