const isBooked = (room) => room.booked === true;

const isPremium = (room) => room.category === 'premium';

const bookedRooms = (rooms) => rooms.filter(isBooked);

const premiumOnly = (rooms) => rooms.filter(isPremium);

const rateOf = (room) => room.rate;

const nightlyRates = (rooms) => rooms.map(rateOf);

const addRate = (total, rate) => total + rate;

const sumRates = (rates) => rates.reduce(addRate, 0);

const normalizeRoom = (room) => ({
  category: String(room.category || '').trim().toLowerCase(),
  rate: Number(room.rate),
  booked: Boolean(room.booked),
});

const isValidRoom = (room) => room.category.length > 0 && Number.isFinite(room.rate) && room.rate >= 0;

const prepare = (rooms) => {
  if (!Array.isArray(rooms)) {
    throw new TypeError('project(rooms): expected an array of room records');
  }
  const cleaned = rooms.map(normalizeRoom);
  const invalid = cleaned.filter(room => !isValidRoom(room));
  if (invalid.length > 0) {
    throw new RangeError(`project(rooms): ${invalid.length} malformed room record(s)`);
  }
  return cleaned;
};

const project = (rooms) => {
  const prepared = prepare(rooms);
  const earning = premiumOnly(bookedRooms(prepared));
  return sumRates(nightlyRates(earning));
};

const formatMoney = (amount) => `$${amount.toFixed(2)}`;

const tallyCategory = (tally, room) => {
  tally[room.category] = (tally[room.category] || 0) + 1;
  return tally;
};

const countByCategory = (rooms) => rooms.reduce(tallyCategory, {});

const describeCategories = (tally) => Object.keys(tally)
  .sort()
  .map(category => `${category}: ${tally[category]}`)
  .join(', ');

const report = (rooms) => {
  const prepared = prepare(rooms);
  const booked = bookedRooms(prepared);
  const lines = [
    `rooms: ${prepared.length} (${describeCategories(countByCategory(prepared))})`,
    `booked: ${booked.length}`,
    `projected revenue: ${formatMoney(project(rooms))}`,
  ];
  return lines.join('\n');
};

const inventory = [
  { category: 'standard', rate: 90, booked: false },
  { category: 'standard', rate: 95, booked: true },
  { category: 'Premium', rate: 220, booked: true },
  { category: 'premium', rate: 310.5, booked: true },
  { category: 'premium', rate: 275, booked: false },
  { category: 'suite', rate: 480, booked: true },
];

console.log(report(inventory));

module.exports = { project, report, bookedRooms, premiumOnly, nightlyRates, formatMoney };

