const isAdult = (response) => response.age >= 18;

const keepAdults = (responses) => responses.filter(isAdult);

const addRating = (total, rating) => total + rating;

const ratingSum = (response) => response.ratings.reduce(addRating, 0);

const toSummary = (response) => ({
  user: response.user,
  total: ratingSum(response)
});

const summarize = (responses) => responses.map(toSummary);

const HIGH_SATISFACTION = 20;

const isHighlySatisfied = (summary) => summary.total >= HIGH_SATISFACTION;

const keepHighlySatisfied = (summaries) => summaries.filter(isHighlySatisfied);

const isValidRating = (rating) => Number.isInteger(rating) && rating >= 1 && rating <= 5;

const validateResponse = (response) => {
  if (typeof response.user !== 'string' || response.user.length === 0) {
    throw new TypeError('each response needs a non-empty user identifier');
  }
  if (!Number.isFinite(response.age) || response.age < 0) {
    throw new RangeError(`invalid age for ${response.user}`);
  }
  if (!Array.isArray(response.ratings)) {
    throw new TypeError(`ratings for ${response.user} must be an array`);
  }
  if (!response.ratings.every(isValidRating)) {
    throw new RangeError(`ratings for ${response.user} must be integers from 1 to 5`);
  }
  return response;
};

const score = (responses) => {
  const validated = responses.map(validateResponse);
  const adults = keepAdults(validated);
  const totals = summarize(adults);
  return keepHighlySatisfied(totals).length;
};

const describeSummary = (summary) => {
  const label = isHighlySatisfied(summary) ? 'highly satisfied' : 'satisfied enough';
  return `${summary.user}: ${summary.total} points (${label})`;
};

const formatReport = (responses) => {
  const adults = keepAdults(responses);
  const lines = summarize(adults).map(describeSummary);
  const skipped = responses.length - adults.length;
  lines.push(`${skipped} minor response(s) discarded`);
  lines.push(`highly satisfied adults: ${score(responses)}`);
  return lines.join('\n');
};

const main = () => {
  const feedback = [
    { user: 'ada', age: 34, ratings: [5, 5, 5, 4, 4] },
    { user: 'bo', age: 15, ratings: [5, 5, 5, 5, 5] },
    { user: 'cyd', age: 41, ratings: [2, 3, 1, 2] }
  ];
  console.log(formatReport(feedback));
};

main();

module.exports = { score, keepAdults, summarize, keepHighlySatisfied, formatReport };

