const NORTHBOUND = 'north';

const normalizeDirection = (direction) => String(direction).trim().toLowerCase();

const normalizeType = (type) => String(type).trim().toLowerCase();

const isValidRecord = (vehicle) => {
  if (!vehicle || typeof vehicle !== 'object') return false;
  if (typeof vehicle.type !== 'string' || typeof vehicle.direction !== 'string') return false;
  return Number.isFinite(vehicle.waitSeconds);
};

const selectNorthbound = (vehicles) =>
  vehicles.filter(v => normalizeDirection(v.direction) === NORTHBOUND);

const rejectBicycles = (vehicles) =>
  vehicles.filter(v => normalizeType(v.type) !== 'bicycle');

const extractWaitTimes = (vehicles) =>
  vehicles.map(v => v.waitSeconds);

const sum = (numbers) =>
  numbers.reduce((total, n) => total + n, 0);

const average = (numbers) => {
  if (numbers.length === 0) return 0;
  return sum(numbers) / numbers.length;
};

const analyze = (vehicles) => {
  if (!Array.isArray(vehicles)) {
    throw new TypeError('analyze expects an array of vehicle records');
  }
  const clean = vehicles.filter(isValidRecord);
  const northbound = selectNorthbound(clean);
  const motorized = rejectBicycles(northbound);
  const waits = extractWaitTimes(motorized);
  return average(waits);
};

const countByType = (vehicles) =>
  vehicles.reduce((tally, v) => {
    const key = normalizeType(v.type);
    tally[key] = (tally[key] || 0) + 1;
    return tally;
  }, {});

const formatReport = (vehicles) => {
  const avg = analyze(vehicles);
  const tally = countByType(selectNorthbound(vehicles.filter(isValidRecord)));
  const breakdown = Object.keys(tally)
    .sort()
    .map(key => `${key}: ${tally[key]}`)
    .join(', ');
  return [
    `Northbound vehicles by type -> ${breakdown}`,
    `Average northbound wait (bicycles excluded): ${avg.toFixed(2)}s`
  ].join('\n');
};

const main = () => {
  const traffic = [
    { type: 'car', waitSeconds: 30, direction: 'north' },
    { type: 'car', waitSeconds: 42, direction: 'North' },
    { type: 'truck', waitSeconds: 60, direction: 'north' },
    { type: 'bicycle', waitSeconds: 12, direction: 'north' },
    { type: 'car', waitSeconds: 90, direction: 'south' },
    { type: 'car', waitSeconds: 75, direction: 'south' }
  ];
  console.log(formatReport(traffic));
};

main();

module.exports = { analyze, selectNorthbound, rejectBicycles, extractWaitTimes, formatReport };

