const ADMIN_PATTERN = /^(admin|administrator)[-_.]?/i;

const isAdministrator = (author) => ADMIN_PATTERN.test(String(author).trim());

const isRegularUser = (post) => !isAdministrator(post.author);

const toNumber = (value) => {
  const n = typeof value === "number" ? value : parseInt(value, 10);
  return Number.isFinite(n) && n >= 0 ? n : 0;
};

const normalizePost = (post) => ({
  author: String(post.author ?? "unknown").trim(),
  likes: toNumber(post.likes),
  shares: toNumber(post.shares),
});

const discardAdminPosts = (posts) => posts.filter(isRegularUser);

const engagementScore = (post) => post.likes + 2 * post.shares;

const scoreAll = (posts) => posts.map(engagementScore);

const isHighEngagement = (score) => score > 100;

