const ADMIN_PATTERN = /^(admin|administrator)[-_.]?/i;

const isAdministrator = function (author) { return ADMIN_PATTERN.test(String(author).trim()); };

const isRegularUser = function (post) { return !isAdministrator(post.author); };

const toNumber = function (value) {
  const n = typeof value === "number" ? value : parseInt(value, 10);
  return Number.isFinite(n) && n >= 0 ? n : 0;
};

const normalizePost = function (post) {
  return {
    author: String(post.author ?? "unknown").trim(),
    likes: toNumber(post.likes),
    shares: toNumber(post.shares),
  };
};

const discardAdminPosts = function (posts) { return posts.filter(isRegularUser); };

const engagementScore = function (post) { return post.likes + 2 * post.shares; };

const scoreAll = function (posts) { return posts.map(engagementScore); };

const isHighEngagement = function (score) { return score > 100; };

const isolateHighScores = function (scores) { return scores.filter(isHighEngagement); };

