const MIN_VOLUME = 20;

const isChest = (exercise) => exercise.muscleGroup.trim().toLowerCase() === 'chest';

const selectChest = (exercises) => exercises.filter(isChest);

const toVolume = (exercise) => exercise.sets * exercise.reps;

const computeVolumes = (exercises) => exercises.map(toVolume);

const qualifies = (volume) => volume >= MIN_VOLUME;

const keepQualifying = (volumes) => volumes.filter(qualifies);

const add = (total, volume) => total + volume;

const sum = (volumes) => volumes.reduce(add, 0);

const validate = (exercise, index) => {
  if (typeof exercise.muscleGroup !== 'string') {
    throw new TypeError(`Exercise ${index}: muscleGroup must be a string`);
  }
  const invalid = [exercise.sets, exercise.reps].some(n => !Number.isFinite(n) || n < 0);
  if (invalid) {
    throw new RangeError(`Exercise ${index}: sets and reps must be non-negative numbers`);
  }
  return exercise;
};

const track = (exercises) => {
  if (!Array.isArray(exercises)) {
    throw new TypeError('track expects an array of exercise records');
  }
  const checked = exercises.map(validate);
  return sum(keepQualifying(computeVolumes(selectChest(checked))));
};

const describe = (exercise) => {
  const volume = toVolume(exercise);
  const flag = qualifies(volume) ? 'counted' : 'below threshold';
  return `${exercise.muscleGroup.padEnd(6)} ${exercise.sets}x${exercise.reps} = ${String(volume).padStart(3)} (${flag})`;
};

const report = (exercises) => {
  const lines = selectChest(exercises).map(describe);
  const header = `Chest exercises: ${lines.length}`;
  return [header, ...lines, `Effective weekly volume: ${track(exercises)}`].join('\n');
};

const main = () => {
  const week = [
    { muscleGroup: 'back', sets: 4, reps: 10 },
    { muscleGroup: 'chest', sets: 4, reps: 8 },
    { muscleGroup: 'legs', sets: 5, reps: 12 },
    { muscleGroup: 'Chest', sets: 3, reps: 5 },
    { muscleGroup: 'chest', sets: 5, reps: 10 },
    { muscleGroup: 'chest', sets: 2, reps: 15 }
  ];
  console.log(report(week));
  const heavy = week.filter(e => toVolume(e) > 40);
  const heavyGroups = heavy.map(e => e.muscleGroup);
  console.log(`High-volume slots: ${heavyGroups.join(', ')}`);
  console.log(`track() => ${track(week)}`);
};

main();

module.exports = { track, selectChest, computeVolumes, keepQualifying, report };

