const normalizeGenre = (genre) => String(genre).trim().toLowerCase();

const isFiction = (book) => normalizeGenre(book.genre) === 'fiction';

const selectFiction = (books) => books.filter(isFiction);

const isModern = (book) => Number(book.year) >= 2000;

const dropOldBooks = (books) => books.filter(isModern);

const titleOf = (book) => book.title.trim();

const pluckTitles = (books) => books.map(titleOf);

const compareTitles = (a, b) => a.localeCompare(b, 'en', { sensitivity: 'base' });

const sortTitles = (titles) => [...titles].sort(compareTitles);

const isValidBook = (book) => {
  if (!book || typeof book !== 'object') return false;
  if (typeof book.title !== 'string' || book.title.trim() === '') return false;
  if (typeof book.genre !== 'string') return false;
  return Number.isFinite(Number(book.year));
};

const validateLibrary = (books) => {
  if (!Array.isArray(books)) {
    throw new TypeError('extract expects an array of book records');
  }
  const broken = books.findIndex(book => !isValidBook(book));
  if (broken !== -1) {
    throw new TypeError(`malformed book record at index ${broken}`);
  }
  return books;
};

function extract(books) {
  const library = validateLibrary(books);
  const fiction = selectFiction(library);
  const modernFiction = dropOldBooks(fiction);
  return sortTitles(pluckTitles(modernFiction));
}

const numberEntry = (title, index) => `${index + 1}. ${title}`;

const formatList = (titles) => titles.map(numberEntry).join('\n');

const main = () => {
  const shelf = [
    { title: 'Moby-Dick', genre: 'Fiction', year: 1851 },
    { title: 'Sapiens', genre: 'Non-Fiction', year: 2011 },
    { title: 'The Road', genre: 'fiction', year: 2006 },
    { title: 'Never Let Me Go', genre: 'Fiction', year: 2005 },
    { title: 'Educated', genre: 'non-fiction', year: 2018 },
    { title: 'Atonement', genre: 'FICTION', year: 2001 }
  ];
  const reading = extract(shelf);
  console.log(`Modern fiction reading list (${reading.length} of ${shelf.length} records):`);
  console.log(formatList(reading));
};

main();

module.exports = { extract, selectFiction, dropOldBooks, pluckTitles, sortTitles };

