const EMISSION_THRESHOLD = 5000;
const PENALTY_RATE = 0.1;

const isValidShipment = (record) => {
  if (!record || typeof record.destination !== 'string') return false;
  return Number.isFinite(record.distance) && Number.isFinite(record.weight);
};

const parseShipment = (record) => ({
  destination: record.destination.trim(),
  distance: Number(record.distance),
  weight: Number(record.weight),
});

const emissionsOf = (shipment) => shipment.distance * shipment.weight;

const computeEmissions = (shipments) => shipments.map(emissionsOf);

const isHighEmission = (value) => value > EMISSION_THRESHOLD;

const filterHighEmissions = (values) => values.filter(isHighEmission);

const applyPenalty = (value) => value * (1 + PENALTY_RATE);

const penalizeEmissions = (values) => values.map(applyPenalty);

const addValues = (total, value) => total + value;

const sumValues = (values) => values.reduce(addValues, 0);

const monitor = (shipments) => {
  if (!Array.isArray(shipments)) {
    throw new TypeError('monitor expects an array of shipment records');
  }
  const invalid = shipments.filter(record => !isValidShipment(record));
  if (invalid.length > 0) {
    throw new TypeError(`monitor received ${invalid.length} malformed shipment record(s)`);
  }
  const parsed = shipments.map(parseShipment);
  const emissions = computeEmissions(parsed);
  const high = filterHighEmissions(emissions);
  return sumValues(penalizeEmissions(high));
};

const formatUnits = (value) => `${value.toFixed(2)} units`;

const describeShipment = (shipment) => {
  const raw = emissionsOf(shipment);
  const status = isHighEmission(raw) ? `penalized -> ${formatUnits(applyPenalty(raw))}` : 'within limit';
  return `${shipment.destination}: ${formatUnits(raw)} (${status})`;
};

const report = (shipments) => {
  const lines = shipments.map(parseShipment).map(describeShipment);
  lines.push(`Total penalized emissions: ${formatUnits(monitor(shipments))}`);
  return lines.join('\n');
};

const main = () => {
  const shipments = [
    { destination: 'Lisbon', distance: 120, weight: 8 },
    { destination: 'Nairobi', distance: 4200, weight: 3 },
    { destination: 'Osaka', distance: 900, weight: 12 },
  ];
  console.log(report(shipments));
};

main();

module.exports = {
  monitor,
  computeEmissions,
  filterHighEmissions,
  penalizeEmissions,
  report,
};

