const PARTICIPATION_BONUS = 50;
const QUALIFYING_SCORE = 500;

const isValidPlayer = (player) =>
  player !== null &&
  typeof player === 'object' &&
  typeof player.username === 'string' &&
  Number.isFinite(player.score) &&
  typeof player.cheated === 'boolean';

const validate = (players) => {
  if (!Array.isArray(players)) {
    throw new TypeError('update() expects an array of player records');
  }
  const bad = players.findIndex(p => !isValidPlayer(p));
  if (bad !== -1) {
    throw new TypeError(`Malformed player record at index ${bad}`);
  }
  return players;
};

const removeCheaters = (players) =>
  players.filter(p => !p.cheated);

const awardBonus = (players) =>
  players.map(p => ({ ...p, score: p.score + PARTICIPATION_BONUS }));

const qualifyingNames = (players) =>
  players
    .filter(p => p.score > QUALIFYING_SCORE)
    .map(p => p.username);

const byName = (a, b) => a.localeCompare(b);

const sortNames = (names) =>
  [...names].sort(byName);

const update = (players) => {
  const honest = removeCheaters(validate(players));
  const boosted = awardBonus(honest);
  return sortNames(qualifyingNames(boosted));
};

const cheaterNames = (players) =>
  players
    .filter(p => p.cheated)
    .map(p => p.username);

const formatReport = (players) => {
  const winners = update(players);
  const cheaters = sortNames(cheaterNames(players));
  const lines = [
    `Entrants: ${players.length}`,
    `Disqualified: ${cheaters.length ? cheaters.join(', ') : 'none'}`,
    `Qualified (> ${QUALIFYING_SCORE} after bonus): ${winners.length}`,
  ];
  winners.forEach((name, i) => lines.push(`  ${i + 1}. ${name}`));
  return lines.join('\n');
};

