  typeof widget === 'object' &&
  widget !== null &&
  typeof widget.batch === 'string' &&
  typeof widget.weight === 'number' &&
  typeof widget.defect === 'boolean';

const validate = (widgets) => {
  if (!Array.isArray(widgets)) {
    throw new TypeError('analyze expects an array of widget records');
  }
  const bad = widgets.findIndex(
    w => !isValidRecord(w)
  );
  if (bad !== -1) {
    throw new TypeError(`malformed widget record at index ${bad}`);
  }
  return widgets;
};

const withoutVisualDefects = (widgets) =>
  widgets.filter(w => !w.defect);

const atTargetWeight = (widgets) =>
  widgets.filter(w => w.weight === TARGET_WEIGHT);

const batchIds = (widgets) =>
  widgets.map(w => w.batch);

const unique = (ids) => {
  const seen = new Set();
  return ids.filter(id => {
    if (seen.has(id)) {
      return false;
    }
    seen.add(id);
    return true;
  });
};

const analyze = (widgets) => {
  const clean = withoutVisualDefects(validate(widgets));
  return unique(batchIds(atTargetWeight(clean)));
};

const countByBatch = (widgets) =>
  widgets.reduce((tally, w) => {
    tally[w.batch] = (tally[w.batch] || 0) + 1;
