const sumExpenses = (expenses) =>
  expenses.reduce((total, amount) => total + amount, 0);

const largestExpense = (expenses) =>
  expenses.reduce((biggest, amount) => Math.max(biggest, amount), 0);

const isActive = (project) => project.active === true;

const summarize = (project) => {
  const spent = sumExpenses(project.expenses);
  return {
    name: project.name,
    spent,
    remaining: project.budget - spent,
    peak: largestExpense(project.expenses)
  };
};

const byRemaining = (a, b) => a.remaining - b.remaining;

const hasSpending = (summary) => summary.spent > 0;

const withinBudget = (summaries) =>
  summaries.every((summary) => summary.remaining >= 0);

const topSpender = (summaries) => {
  const leader = summaries.reduce((best, summary) => {
    if (best === null || summary.peak > best.peak) {
      return summary;
    }
    return best;
  }, null);
  return leader === null ? null : leader.name;
};

const describe = (summary) => `${summary.name} has remaining budget ${summary.remaining}`;

const audit = (projects) => {
  const active = projects.filter(isActive).map(summarize);
  const ranked = active.slice().sort(byRemaining).filter(hasSpending);
  return [withinBudget(active), topSpender(active), ranked.map(describe)];
};

const parseProject = (record) => ({
  name: record.name,
  budget: Number(record.budget),
  expenses: record.expenses.map((value) => Number(value)),
  active: record.active
});

const report = (projects) => {
  const [ok, leader, lines] = audit(projects.map(parseProject));
  const header = ok ? 'All active projects are within budget.' : 'Budget overrun detected.';
  const spender = leader === null ? 'No active projects.' : `Highest single expense: ${leader}.`;
  return [header, spender].concat(lines).join('\n');
};

const portfolio = [
  { name: 'Alpha', budget: 100, expenses: [20, 30], active: true },
  { name: 'Beta', budget: 250, expenses: [120, 200], active: true },
  { name: 'Gamma', budget: 80, expenses: [], active: true },
  { name: 'Delta', budget: 400, expenses: [75, 90, 15], active: true },
  { name: 'Epsilon', budget: 600, expenses: [500], active: false }
];

console.log(report(portfolio));

module.exports = { audit, report };

