const EFFICIENCY_THRESHOLD = 30;

const add = (acc, n) => acc + n;

const sum = (numbers) => numbers.reduce(add, 0);

const hasEnoughTrips = (vehicle) => vehicle.distances.length >= 3;

const summarize = (vehicle) => {
  const totalDistance = sum(vehicle.distances);
  const totalFuel = sum(vehicle.fuel);
  return {
    model: vehicle.model,
    totalDistance,
    totalFuel,
    mpg: totalFuel === 0 ? 0 : totalDistance / totalFuel
  };
};

const byEfficiencyDesc = (a, b) => b.mpg - a.mpg;

const average = (values) => (values.length === 0 ? 0 : sum(values) / values.length);

function evaluate(vehicles) {
  const summaries = vehicles.filter(hasEnoughTrips).map(summarize);
  const efficient = summaries.filter((s) => s.mpg >= EFFICIENCY_THRESHOLD);
  const inefficient = summaries.filter((s) => s.mpg < EFFICIENCY_THRESHOLD);

  efficient.sort(byEfficiencyDesc);
  inefficient.sort(byEfficiencyDesc);

  const averageInefficient = average(inefficient.map((s) => s.mpg));
  const efficientModels = efficient.map((s) => s.model);

  return [averageInefficient, efficientModels];
}

const formatMpg = (mpg) => `${mpg.toFixed(2)} mpg`;

const buildReport = (vehicles) => {
  const [averageInefficient, efficientModels] = evaluate(vehicles);
  const lines = [`Efficient fleet (>= ${EFFICIENCY_THRESHOLD} mpg): ${efficientModels.length} vehicle(s)`];
  efficientModels.forEach((model, index) => {
    lines.push(`  ${index + 1}. ${model}`);
  });
  lines.push(`Average efficiency of the rest: ${formatMpg(averageInefficient)}`);
  return lines.join('\n');
};

const fleet = [
  { model: 'Hauler', distances: [50, 50], fuel: [2, 3] },
  { model: 'Compact', distances: [120, 90, 140, 50], fuel: [3, 2.5, 4, 1.5] },
  { model: 'Van', distances: [200, 180, 220], fuel: [10, 9, 11] },
  { model: 'Hybrid', distances: [100, 150, 130], fuel: [2, 3, 2.8] },
  { model: 'Pickup', distances: [90, 80, 100], fuel: [5, 4.5, 6] }
];

const invalid = fleet.filter((v) => v.distances.length !== v.fuel.length);
if (invalid.length > 0) {
  const names = invalid.map((v) => v.model).join(', ');
  throw new Error(`Mismatched trip data for: ${names}`);
}

console.log(buildReport(fleet));

module.exports = { evaluate, buildReport };

