const MIN_TENURE = 6;
const RECENT_WINDOW = 30;
const MIN_LOGINS = 4;

const isEligible = (customer) => customer.tenure >= MIN_TENURE;

const countRecentLogins = (loginDaysAgo) =>
  loginDaysAgo.filter(days => days <= RECENT_WINDOW).length;

const hasUnresolvedTicket = (tickets) =>
  tickets.some(status => String(status).trim().toLowerCase() === 'unresolved');

const describeRisk = (customer) => {
  const recentLogins = countRecentLogins(customer.loginDaysAgo);
  const unresolved = hasUnresolvedTicket(customer.tickets);
  return {
    id: customer.id,
    tenure: customer.tenure,
    recentLogins,
    unresolved,
    highRisk: recentLogins < MIN_LOGINS || unresolved
  };
};

const average = (values) => {
  if (values.length === 0) return 0;
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const predict = (customers) => {
  const assessed = customers.filter(isEligible).map(describeRisk);
  const atRisk = assessed.filter(entry => entry.highRisk);
  const identifiers = atRisk
    .map(entry => entry.id)
    .sort((a, b) => a.localeCompare(b));
  return {
    averageTenure: average(atRisk.map(entry => entry.tenure)),
    atRiskIds: identifiers
  };
};

const formatReport = (result) => {
  const header = `High risk accounts: ${result.atRiskIds.length}`;
  const tenureLine = `Average tenure: ${result.averageTenure.toFixed(1)} months`;
  const listed = result.atRiskIds.map(id => `  - ${id}`).join('\n');
  return [header, tenureLine, listed].filter(line => line.length > 0).join('\n');
};

const main = () => {
  const customers = [
    { id: 'zeta-corp', tenure: 10, loginDaysAgo: [2, 40], tickets: ['unresolved'] },
    { id: 'acme-ltd', tenure: 24, loginDaysAgo: [1, 3, 8, 12, 20], tickets: ['resolved'] },
    { id: 'brightco', tenure: 3, loginDaysAgo: [], tickets: ['unresolved'] },
    { id: 'meridian', tenure: 18, loginDaysAgo: [5, 60, 90], tickets: ['resolved', 'closed'] },
    { id: 'novatech', tenure: 7, loginDaysAgo: [1, 2, 4, 9, 29], tickets: ['Resolved', 'UNRESOLVED'] }
  ];
  console.log(formatReport(predict(customers)));
};

main();

module.exports = { predict, countRecentLogins, hasUnresolvedTicket, formatReport };

