const POPULARITY_THRESHOLD = 50;

const isPopular = dish => dish.popularity > POPULARITY_THRESHOLD;

const splitByDiet = dishes => ({
  vegetarian: dishes.filter(dish => dish.vegetarian),
  nonVegetarian: dishes.filter(dish => !dish.vegetarian)
});

const collectIngredients = dishes =>
  dishes.reduce((all, dish) => all.concat(dish.ingredients), []);

const normalizeName = name => String(name).trim().toLowerCase();

const validateIngredient = ingredient => {
  const name = normalizeName(ingredient.name);
  const quantity = Number(ingredient.quantity);
  if (name === '') {
    throw new Error('ingredient is missing a name');
  }
  if (!Number.isFinite(quantity)) {
    throw new Error(`ingredient "${name}" has a non numeric quantity`);
  }
  return { name, quantity };
};

const totalsByName = ingredients => {
  const totals = new Map();
  ingredients.map(validateIngredient).forEach(({ name, quantity }) => {
    totals.set(name, (totals.get(name) || 0) + quantity);
  });
  return totals;
};

const byQuantityDescending = (a, b) => {
  if (b.total !== a.total) {
    return b.total - a.total;
  }
  return a.name.localeCompare(b.name);
};

const formatLine = entry => `${entry.name} ${entry.total}`;

const order = menu => {
  if (!Array.isArray(menu)) {
    throw new TypeError('menu must be an array of dishes');
  }
  const popular = menu.filter(isPopular);
  const { vegetarian } = splitByDiet(popular);
  const totals = totalsByName(collectIngredients(vegetarian));
  const entries = Array.from(totals, ([name, total]) => ({ name, total }));
  return entries.sort(byQuantityDescending).map(formatLine);
};

const dishName = dish => dish.name;

const titles = list => list.map(dishName).join(', ');

const describeMenu = menu => {
  const { vegetarian, nonVegetarian } = splitByDiet(menu.filter(isPopular));
  return `popular vegetarian: ${titles(vegetarian)} | popular other: ${titles(nonVegetarian)}`;
};

const main = () => {
  const menu = [
    { name: 'flatbread', popularity: 91, vegetarian: true, ingredients: [{ name: 'Flour', quantity: 2 }, { name: 'water', quantity: 1 }] },
    { name: 'dumplings', popularity: 74, vegetarian: true, ingredients: [{ name: 'flour', quantity: 3 }, { name: 'cabbage', quantity: 4 }] },
    { name: 'brisket', popularity: 88, vegetarian: false, ingredients: [{ name: 'beef', quantity: 6 }] },
    { name: 'plain rice', popularity: 12, vegetarian: true, ingredients: [{ name: 'rice', quantity: 9 }] }
  ];
  console.log(describeMenu(menu));
  order(menu).forEach(line => console.log(line));
};

main();

module.exports = { order, isPopular, splitByDiet, collectIngredients, describeMenu };

