const DAYS_IN_WEEK = 7;

const hasFullWeek = (participant) =>
  Array.isArray(participant.steps) && participant.steps.length === DAYS_IN_WEEK;

const totalSteps = (steps) =>
  steps.reduce(
    (sum, day) => sum + day,
    0
  );

const bestDay = (steps) =>
  steps.reduce(
    (best, day) => (day > best ? day : best),
    0
  );

const summarize = (participant) => ({
  name: participant.name,
  total: totalSteps(participant.steps),
  best: bestDay(participant.steps),
});

const overallAverage = (summaries) => {
  if (summaries.length === 0) {
    return 0;
  }
  const grandTotal = summaries.reduce(
    (sum, entry) => sum + entry.total,
    0
  );
  return grandTotal / summaries.length;
};

const byTotalDescending = (a, b) => b.total - a.total;

const describe = (entry) => `${entry.name} scored best with ${entry.best}`;

function rank(participants) {
  const summaries = participants.filter(hasFullWeek).map(summarize);
  const average = overallAverage(summaries);
  const aboveAverage = summaries.filter(
    (entry) => entry.total >= average
  );
  return aboveAverage.sort(byTotalDescending).map(describe);
}

const flatWeek = (value) => new Array(DAYS_IN_WEEK).fill(value);

const rampWeek = (start, step) =>
  flatWeek(0).map(
    (_, index) => start + index * step
  );

const report = (participants) => {
  const lines = rank(participants);
  const header = `${lines.length} of ${participants.length} participants made the cut`;
  const indented = lines.map(
    (line) => `  - ${line}`
  );
  return [header].concat(indented).join('\n');
};

