  { name: 'John', steps: flatWeek(1000) },
  { name: 'Mia', steps: rampWeek(6000, 500) },
  { name: 'Omar', steps: [12000, 9000, 11000, 15000, 8000, 10000, 13000] },
  { name: 'Lena', steps: rampWeek(2000, 250) },
  { name: 'Bram', steps: [7000, 7500, 8000] },
  { name: 'Tess', steps: flatWeek(9500) },
];

console.log(report(challenge));

