const isRecent = (movie) => movie.year > 2010;

const validRatings = (ratings) =>
  ratings.filter(r => r >= 0);

const average = (values) =>
  values.reduce((sum, v) => sum + v, 0) / values.length;

const scoreMovie = (movie) => {
  const usable = validRatings(movie.ratings);
  if (usable.length === 0) {
    return null;
  }
  return { title: movie.title, genre: movie.genre, average: average(usable) };
};

const groupByGenre = (scored) => {
  const groups = new Map();
  scored.forEach(entry => {
    const bucket = groups.get(entry.genre);
    if (bucket) {
      bucket.push(entry);
    } else {
      groups.set(entry.genre, [entry]);
    }
  });
  return groups;
};

const bestOfGenre = (entries) => {
  const ranked = [...entries].sort((a, b) => b.average - a.average);
  return ranked[0];
};

function recommend(movies) {
  const scored = movies
    .filter(isRecent)
    .map(scoreMovie)
    .filter(entry => entry !== null && entry.average >= 4);

  const winners = [];
  groupByGenre(scored).forEach(entries => winners.push(bestOfGenre(entries)));

  return winners
    .map(entry => entry.title)
    .sort((a, b) => a.localeCompare(b));
}

const describe = (movie) => {
  const entry = scoreMovie(movie);
  const shown = entry ? entry.average.toFixed(1) : 'n/a';
  return `${movie.title} (${movie.genre}, ${movie.year}): ${shown}`;
};

