const volumeOf = (shipment) => shipment.dimensions.reduce(
  (acc, side) => acc * side,
  1
);

const describe = (shipment) => ({
  id: shipment.id,
  fragile: Boolean(shipment.fragile),
  volume: volumeOf(shipment)
});

const validate = (shipment) => {
  if (!Array.isArray(shipment.dimensions) || shipment.dimensions.length !== 3) {
    throw new Error(`shipment ${shipment.id} must have exactly three dimensions`);
  }
  const bad = shipment.dimensions.find(side => typeof side !== 'number' || side < 0);
  if (bad !== undefined) {
    throw new Error(`shipment ${shipment.id} has an invalid dimension: ${bad}`);
  }
};

const byVolumeAscending = (a, b) => a.volume - b.volume;

const sumVolume = (entries) => entries.reduce(
  (total, entry) => total + entry.volume,
  0
);

const largestVolume = (entries) => entries.reduce(
  (best, entry) => (best === null || entry.volume > best.volume ? entry : best),
  null
);

function optimize(shipments) {
  shipments.forEach(shipment => validate(shipment));

  const packed = shipments.map(describe).filter(entry => entry.volume !== 0);
  const fragile = packed.filter(entry => entry.fragile).sort(byVolumeAscending);
  const sturdy = packed.filter(entry => !entry.fragile).sort(byVolumeAscending);

  const biggestFragile = largestVolume(fragile);
  const sturdyIds = sturdy.map(entry => entry.id);

  return [sumVolume(sturdy), biggestFragile === null ? null : biggestFragile.id, sturdyIds];
}

const formatReport = (result) => {
  const [totalSturdyVolume, largestFragileId, sturdyIds] = result;
  const lines = [
    `Total sturdy volume: ${totalSturdyVolume}`,
    `Largest fragile shipment: ${largestFragileId === null ? 'none' : largestFragileId}`
  ];
  const listing = sturdyIds.length === 0 ? 'none' : sturdyIds.join(', ');
  lines.push(`Sturdy shipments in loading order: ${listing}`);
  return lines.join('\n');
};

const main = () => {
  const inventory = [
    { id: 'A-100', dimensions: [10, 10, 2], fragile: false },
    { id: 'A-101', dimensions: [3, 3, 3], fragile: true },
    { id: 'A-102', dimensions: [5, 0, 7], fragile: false },
    { id: 'A-103', dimensions: [4, 6, 2], fragile: false },
    { id: 'A-104', dimensions: [12, 4, 4], fragile: true },
    { id: 'A-105', dimensions: [1, 1, 1], fragile: true }
  ];
  console.log(formatReport(optimize(inventory)));
};

main();

module.exports = { optimize, volumeOf, formatReport };

