const normalize = (value) => String(value ?? '').trim().toLowerCase();

const isSenior = (patient) => Number(patient.age) >= 65;

const medicationNames = (medications) =>
  medications.map(
    (med) => normalize(med.name)
  );

const contraindicationsOf = (medication) => (medication.contraindications || []).map(normalize);

const pairKey = (pair) => [...pair].sort().join('|');

const dedupePairs = (pairs) => {
  const seen = new Map();
  pairs.forEach((pair) => {
    const key = pairKey(pair);
    if (!seen.has(key)) seen.set(key, pair);
  });
  return [...seen.values()];
};

const findConflicts = (medications) => {
  const names = medicationNames(medications);
  const conflicts = [];
  medications.forEach((medication, index) => {
    const banned = contraindicationsOf(medication);
    names.forEach((otherName, otherIndex) => {
      if (otherIndex !== index && otherName && banned.includes(otherName)) {
        conflicts.push([names[index], otherName]);
      }
    });
  });
  return dedupePairs(conflicts);
};

const describePair = ([a, b]) => `${a} with ${b}`;

const describeConflicts = (pairs) => pairs.map(describePair).join(', ');

const formatWarning = (patient, pairs) =>
  `Warning: ${patient.name} has a medication conflict (${describeConflicts(pairs)})`;

const byPatientName = (a, b) => a.patient.name.localeCompare(b.patient.name);

function screen(patients) {
  const seniors = (patients || []).filter(isSenior);
  const reviewed = seniors.map((patient) => ({
    patient,
    pairs: findConflicts(patient.medications || []),
  }));
  const flagged = reviewed.filter((entry) => entry.pairs.length > 0).sort(byPatientName);
  const warnings = flagged.map((entry) => formatWarning(entry.patient, entry.pairs));
  return [flagged.length, warnings];
}

const roster = [
  {
    name: 'Nora Whitfield',
    age: 71,
    medications: [
      { name: 'Aspirin', contraindications: ['Warfarin', 'Ibuprofen'] },
      { name: 'Warfarin', contraindications: [] },
    ],
  },
  {
    name: 'Adam Cole',
    age: 68,
    medications: [
      { name: 'Metformin', contraindications: ['Contrast Dye'] },
      { name: 'Lisinopril', contraindications: ['Spironolactone'] },
      { name: 'Spironolactone', contraindications: [] },
    ],
  },
  {
    name: 'Tomas Reyes',
    age: 44,
    medications: [
      { name: 'Aspirin', contraindications: ['Warfarin'] },
      { name: 'Warfarin', contraindications: [] },
    ],
  },
];

const [conflictCount, conflictWarnings] = screen(roster);
console.log(`Patients with conflicts: ${conflictCount}`);
conflictWarnings.forEach((warning) => console.log(warning));

module.exports = { screen, findConflicts, formatWarning };

