const sum = (numbers) =>
  numbers.reduce((total, n) => total + n, 0);

const averageYield = (farm) => sum(farm.yields) / farm.yields.length;

const withAverages = (farms) =>
  farms
    .filter(isActive)
    .filter(hasHistory)
    .map(farm => ({ region: farm.region, crop: farm.crop, average: averageYield(farm) }));

const isLow = (record) => record.average < 50;

const hasLowYield = (records) => records.some(isLow);

const groupByCrop = (records) => {
  const groups = new Map();
  records.forEach(record => {
    const bucket = groups.get(record.crop);
    if (bucket) {
      bucket.push(record);
    } else {
      groups.set(record.crop, [record]);
    }
  });
  return groups;
};

const bestOfGroup = (records) =>
  records.reduce((best, record) => (record.average > best.average ? record : best));

