  const groups = groupByCrop(records);
  const crops = Array.from(groups.keys()).sort((a, b) => a.localeCompare(b));
  const leaders = crops.map(crop => bestOfGroup(groups.get(crop)).region);
  return [hasLowYield(records), leaders];
};

