const isActive = (device) => device.hours > 0;

const wattHours = (device) => device.hours * device.watts;

const toKilowattHours = (wh) => wh / 1000;

const validate = (device) => {
  const { type, hours, watts } = device;
  if (typeof type !== 'string' || type.trim() === '') {
    throw new TypeError('device type must be a non-empty string');
  }
  if (!Number.isFinite(hours) || hours < 0 || hours > 24) {
    throw new RangeError(`invalid active hours for ${type}: ${hours}`);
  }
  if (!Number.isFinite(watts) || watts < 0) {
    throw new RangeError(`invalid wattage for ${type}: ${watts}`);
  }
  return device;
};

const profile = (device) => ({
  type: device.type.trim(),
  kwh: toKilowattHours(wattHours(device)),
});

const round3 = (value) => Math.round(value * 1000) / 1000;

const HIGH_CONSUMER_KWH = 5;

function monitor(devices) {
  const profiles = devices
    .map(validate)
    .filter(isActive)
    .map(profile);

  const total = profiles.reduce((sum, item) => sum + item.kwh, 0);

  const pickLarger = (best, item) => (item.kwh > best.kwh ? item : best);
  const top = profiles.length ? profiles.reduce(pickLarger).type : null;

  const highConsumers = profiles
    .filter((item) => item.kwh > HIGH_CONSUMER_KWH)
    .map((item) => item.type)
    .sort((a, b) => a.localeCompare(b));

  return [round3(total), top, highConsumers];
}

const formatReport = ([total, top, highConsumers]) => {
  const lines = [`Total consumption: ${total.toFixed(3)} kWh`];
  lines.push(`Top consumer: ${top === null ? 'none' : top}`);
  const listed = highConsumers.length ? highConsumers.join(', ') : 'none';
  lines.push(`Above ${HIGH_CONSUMER_KWH} kWh: ${listed}`);
  return lines.join('\n');
};

const household = [
  { type: 'fridge', hours: 24, watts: 150 },
  { type: 'led lamp', hours: 5, watts: 9 },
  { type: 'space heater', hours: 4, watts: 2000 },
  { type: 'dishwasher', hours: 1.5, watts: 1800 },
  { type: 'printer', hours: 0, watts: 500 },
  { type: 'laptop', hours: 10, watts: 100 },
];

console.log(formatReport(monitor(household)));

module.exports = { monitor, formatReport };

