const CORE_MODULES = ['safety', 'security', 'ethics'];

const normalize = (module) => String(module).trim().toLowerCase();

const completedSet = (employee) => {
  const modules = Array.isArray(employee.completed) ? employee.completed : [];
  return new Set(modules.map(normalize));
};

const missingModules = (employee) => {
  const done = completedSet(employee);
  return CORE_MODULES.filter(core => !done.has(core));
};

const isCompliant = (employee) => missingModules(employee).length === 0;

const byMissingThenName = (a, b) => {
  if (a.missing !== b.missing) {
    return b.missing - a.missing;
  }
  return a.name.localeCompare(b.name);
};

const formatNotice = (record) => `${record.name} needs training`;

const audit = (employees) => {
  if (!Array.isArray(employees)) {
    throw new TypeError('audit expects an array of employees');
  }
  const records = employees
    .filter(employee => !isCompliant(employee))
    .map(employee => ({
      name: String(employee.name),
      department: String(employee.department),
      missing: missingModules(employee).length,
    }));
  records.sort(byMissingThenName);
  return records.map(formatNotice);
};

const departmentGaps = (employees) => {
  const gaps = new Map();
  employees.forEach(employee => {
    const count = missingModules(employee).length;
    const current = gaps.get(employee.department) || 0;
    gaps.set(employee.department, current + count);
  });
  return [...gaps.entries()].sort((a, b) => b[1] - a[1]);
};

const main = () => {
  const staff = [
    { name: 'Dana', department: 'Ops', completed: ['safety'] },
    { name: 'Alex', department: 'Legal', completed: ['safety', 'Security', 'ethics'] },
    { name: 'Chris', department: 'Ops', completed: [] },
    { name: 'Blake', department: 'Finance', completed: ['ethics', 'safety'] },
    { name: 'Erin', department: 'Legal', completed: ['security'] },
  ];

  audit(staff).forEach(line => console.log(line));

  console.log('--- department gaps ---');
  departmentGaps(staff).forEach(([department, missing]) => {
    console.log(`${department}: ${missing} outstanding module(s)`);
  });
};

main();

module.exports = { audit, departmentGaps, CORE_MODULES };

