const ELIGIBLE_TIERS = new Set(['gold', 'platinum']);

const ROOM_UPGRADES = {
  standard: 'deluxe',
  deluxe: 'suite'
};

const isPremium = (reservation) => ELIGIBLE_TIERS.has(String(reservation.tier).toLowerCase());

const isLongEnough = (reservation) => reservation.nights >= 3;

const upgradeRoom = (roomType) => {
  const key = String(roomType).toLowerCase();
  return ROOM_UPGRADES[key] || roomType;
};

const applyUpgrade = (reservation) => ({
  ...reservation,
  roomType: upgradeRoom(reservation.roomType)
});

const byNightsDescending = (a, b) => b.nights - a.nights;

const upgrade = (reservations) => {
  const premium = reservations
    .filter(isPremium)
    .filter(isLongEnough)
    .map(applyUpgrade);

  const hasLongStay = premium.some(r => r.nights > 10);
  const totalNights = premium.reduce((sum, r) => sum + r.nights, 0);

  const names = [...premium]
    .sort(byNightsDescending)
    .map(r => r.guest);

  return [hasLongStay, totalNights, names];
};

