const isAvailable = band => band.available;

const byPopularityDesc = (a, b) => b.popularity - a.popularity;

const byName = (a, b) => a.localeCompare(b);

const groupByGenre = (bands) => {
  const groups = new Map();
  bands.forEach(band => {
    const bucket = groups.get(band.genre);
    if (bucket) bucket.push(band);
    else groups.set(band.genre, [band]);
  });
  return groups;
};

const topTwo = (group) => [...group].sort(byPopularityDesc).slice(0, 2);

const selectPerGenre = (groups) => {
  const selections = new Map();
  groups.forEach((group, genre) => {
    selections.set(genre, topTwo(group));
  });
  return selections;
};

const flatten = (selections) => {
  const master = [];
  selections.forEach(group => master.push(...group));
  return master;
};

const isHighlyPopular = band => band.popularity > 70;

const allHighlyPopular = (bands) => bands.every(isHighlyPopular);

const nameOf = band => band.name;

const sortedNames = (bands) => bands.map(nameOf).sort(byName);

const schedule = (bands) => {
  const available = bands.filter(isAvailable);
  const master = flatten(selectPerGenre(groupByGenre(available)));
  return [allHighlyPopular(master), sortedNames(master)];
};

const numberLine = (name, index) => `${index + 1}. ${name}`;

const formatLineup = (highPopularity, names) => {
  const header = highPopularity
    ? 'All selected bands are highly popular.'
    : 'Some selected bands are below the popularity threshold.';
  return [header, ...names.map(numberLine)].join('\n');
};

