  { name: 'Night Ledger', genre: 'jazz', popularity: 77, available: true },
  { name: 'Salt Harbour', genre: 'folk', popularity: 68, available: true }
];

const [highPopularity, names] = schedule(lineup);
console.log(formatLineup(highPopularity, names));

