const average = (times) => {
  const total = times.reduce((sum, t) => sum + t, 0);
  return total / times.length;
};

const maxTransit = (times) => {
  return times.reduce((best, t) => (t > best ? t : best), -Infinity);
};

const reliabilityRatio = (times) => {
  const mean = average(times);
  return maxTransit(times) / mean;
};

const validateRoute = (route, index) => {
  if (!route || typeof route.start !== 'string' || typeof route.end !== 'string') {
    throw new TypeError(`route ${index} must have string start and end points`);
  }
  if (!Array.isArray(route.times) || route.times.length === 0) {
    throw new TypeError(`route ${index} must have a non-empty list of transit times`);
  }
  const bad = route.times.find((t) => typeof t !== 'number' || !Number.isFinite(t) || t < 0);
  if (bad !== undefined) {
    throw new RangeError(`route ${index} has an invalid transit time: ${bad}`);
  }
  return route;
};

function detect(routes) {
  if (!Array.isArray(routes)) {
    throw new TypeError('routes must be an array');
  }

  const checked = routes.map(validateRoute);

  const slow = checked.filter((route) => average(route.times) >= 5);

  const scored = slow.map((route) => ({
    end: route.end,
    ratio: reliabilityRatio(route.times),
  }));

  const delayed = scored.some((entry) => entry.ratio > 2);

  const ranked = [...scored].sort((a, b) => b.ratio - a.ratio);

  return [delayed, ranked.map((entry) => entry.end)];
}

const describe = (route) => {
  const mean = average(route.times);
  return `${route.start} -> ${route.end}: avg ${mean.toFixed(1)}d, max ${maxTransit(route.times)}d`;
};

const report = (routes) => {
  const [delayed, endPoints] = detect(routes);
  const lines = routes.map(describe);
  lines.push(delayed ? 'Bottleneck detected' : 'No bottleneck detected');
  lines.push(`Worst-first end points: ${endPoints.join(', ') || '(none)'}`);
  return lines.join('\n');
};

const network = [
  { start: 'Depot', end: 'Harbor', times: [4, 5, 9] },
  { start: 'Depot', end: 'Airfield', times: [1, 2, 3] },
  { start: 'Harbor', end: 'Inland', times: [6, 6, 18] },
  { start: 'Inland', end: 'Border', times: [7, 8, 9] },
];

console.log(report(network));

module.exports = { detect, average, maxTransit, reliabilityRatio, report };

