const isValidName = (name) => typeof name === 'string' && name.trim().length > 0;

const normalize = (ballot) => ({
  voter: String(ballot.voter ?? '').trim(),
  district: String(ballot.district ?? '').trim(),
  candidate: String(ballot.candidate ?? '').trim(),
});

const isUsableBallot = (ballot) =>
  isValidName(ballot.voter) && isValidName(ballot.district) && isValidName(ballot.candidate);

const countVoterOccurrences = (ballots) => {
  const seen = new Map();
  ballots.forEach(b => seen.set(b.voter, (seen.get(b.voter) || 0) + 1));
  return seen;
};

const dropDuplicateVoters = (ballots) => {
  const occurrences = countVoterOccurrences(ballots);
  return ballots.filter(b => occurrences.get(b.voter) === 1);
};

const groupByDistrict = (ballots) => {
  const districts = new Map();
  ballots.forEach(b => {
    if (!districts.has(b.district)) districts.set(b.district, []);
    districts.get(b.district).push(b);
  });
  return districts;
};

const countCandidates = (ballots) => {
  const counts = new Map();
  ballots.forEach(b => counts.set(b.candidate, (counts.get(b.candidate) || 0) + 1));
  return counts;
};

const pickWinner = (counts) => {
  const entries = [...counts.entries()];
  const ranked = entries.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  return ranked[0][0];
};

const tally = (ballots) => {
  const cleaned = ballots.map(normalize).filter(isUsableBallot);
  const unique = dropDuplicateVoters(cleaned);
  const grouped = groupByDistrict(unique);
  const names = [...grouped.keys()].sort((a, b) => a.localeCompare(b));
  return names.map(district => {
    const winner = pickWinner(countCandidates(grouped.get(district)));
    return `${district}: ${winner}`;
  });
};

