const TOP_COUNT = 5;

const hasValidDuration = (episode) => {
  const minutes = Number(episode.duration);
  return Number.isFinite(minutes) && minutes > MIN_DURATION && minutes < MAX_DURATION;
};

const hasGuest = (episode) => {
  const guest = episode.guest;
  return typeof guest === "string" && guest.trim().length > 0;
};

const withRate = (episode) => ({
  title: episode.title,
  duration: Number(episode.duration),
  guest: episode.guest.trim(),
  listens: Number(episode.listens) || 0,
  rate: (Number(episode.listens) || 0) / Number(episode.duration)
});

const curate = (episodes) => {
  const source = Array.isArray(episodes) ? episodes : [];
  const valid = source
    .filter(hasValidDuration)
    .filter(hasGuest)
    .map(withRate);

  const totalListens = valid.reduce((sum, episode) => sum + episode.listens, 0);
  const highRate = valid.every(episode => episode.rate > RATE_THRESHOLD);

  const ranked = [...valid].sort((a, b) => b.rate - a.rate);
  const topTitles = ranked.slice(0, TOP_COUNT).map(episode => episode.title);

  return [totalListens, highRate, topTitles];
