const MIN_YEARS = 3;
const REQUIRED_SKILLS = ['javascript', 'python'];

const normalizeLanguages = (languages) => {
  if (!Array.isArray(languages)) {
    return [];
  }
  const cleaned = languages
    .filter(lang => typeof lang === 'string')
    .map(lang => lang.trim().toLowerCase())
    .filter(lang => lang.length > 0);
  return Array.from(new Set(cleaned));
};

const prepare = (applicant) => ({
  name: applicant.name,
  years: applicant.years,
  languages: normalizeLanguages(applicant.languages),
});

const hasRequiredSkills = (languages) =>
  REQUIRED_SKILLS.every(skill => languages.includes(skill));

const isExperienced = (applicant) => applicant.years >= MIN_YEARS;

const byLanguagesThenYears = (a, b) => {
  const languageGap = b.languages.length - a.languages.length;
  return languageGap !== 0 ? languageGap : b.years - a.years;
};

function screen(applicants) {
  return applicants
    .map(prepare)
    .filter(isExperienced)
    .filter(candidate => hasRequiredSkills(candidate.languages))
    .sort(byLanguagesThenYears)
    .map(candidate => candidate.name);
}

const describe = (applicant) => {
  const prepared = prepare(applicant);
  const skills = prepared.languages.join(', ') || 'none listed';
  return `${prepared.name} (${prepared.years}y): ${skills}`;
};

const rejectionReason = (applicant) => {
  const prepared = prepare(applicant);
  if (!isExperienced(prepared)) {
    return `only ${prepared.years} year(s) of experience`;
  }
  const missing = REQUIRED_SKILLS.filter(skill => !prepared.languages.includes(skill));
  return `missing ${missing.join(' and ')}`;
};

const report = (applicants) => {
  const shortlist = screen(applicants);
  const lines = [`Shortlist (${shortlist.length}):`];
  shortlist.forEach((name, index) => lines.push(`  ${index + 1}. ${name}`));
  const rejected = applicants.filter(applicant => !shortlist.includes(applicant.name));
  rejected.forEach(applicant => lines.push(`  - ${applicant.name}: ${rejectionReason(applicant)}`));
  return lines.join('\n');
};

const pool = [
  { name: 'Ada', years: 4, languages: ['JavaScript', 'Python', 'Ruby'] },
  { name: 'Grace', years: 9, languages: ['Python', 'JAVASCRIPT'] },
  { name: 'Linus', years: 12, languages: ['C', 'Assembly'] },
  { name: 'Mei', years: 2, languages: ['JavaScript', 'Python', 'Go', 'Rust'] },
  { name: 'Omar', years: 6, languages: ['python', 'javascript', 'go', 'rust'] },
];

pool.map(describe).forEach(line => console.log(line));
console.log(report(pool));

