const isActive = (camera) => Array.isArray(camera.speeds) && camera.speeds.length > 0;

const isSevere = (limit) => {
  return speed => speed > limit + 10;
};

const countSevere = (speeds, limit) => {
  return speeds.filter(isSevere(limit)).length;
};

const speedingPercentage = (camera) => {
  const severe = countSevere(camera.speeds, camera.limit);
  return (severe / camera.speeds.length) * 100;
};

const toReport = (camera) => ({
  location: camera.location,
  percentage: speedingPercentage(camera),
  vehicles: camera.speeds.length
});

const average = (values) => {
  if (values.length === 0) {
    return 0;
  }
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const byPercentageDesc = (a, b) => b.percentage - a.percentage;

function monitor(cameras) {
  const reports = cameras
    .filter(isActive)
    .map(toReport)
    .filter(report => report.percentage >= 5)
    .sort(byPercentageDesc);

  const avg = average(reports.map(report => report.percentage));
  const locations = reports.map(report => report.location);
  return [avg, locations];
}

const formatLine = (report) => {
  const pct = report.percentage.toFixed(1).padStart(5);
  return `${report.location.padEnd(16)} ${pct}%  (${report.vehicles} vehicles)`;
};

const describe = (cameras) => {
  const [avg, locations] = monitor(cameras);
  const lookup = new Map(cameras.map(camera => [camera.location, camera]));
  const lines = locations.map(location => formatLine(toReport(lookup.get(location))));
  lines.push(`average severe speeding: ${avg.toFixed(2)}%`);
  return lines.join('\n');
};

