const MAX_TALK_MINUTES = 60;
const LONG_TRACK_MINUTES = 300;

const isEligible = (talk) => talk.approved && talk.duration <= MAX_TALK_MINUTES;

const groupByTrack = (talks) => {
  const groups = new Map();
  talks.forEach(talk => {
    const bucket = groups.get(talk.track) || [];
    bucket.push(talk);
    groups.set(talk.track, bucket);
  });
  return groups;
};

const addMinutes = (sum, talk) => sum + talk.duration;

const totalDuration = (talks) => talks.reduce(addMinutes, 0);

const summarize = (groups) => {
  const totals = [];
  groups.forEach((talks, track) => totals.push({ track, minutes: totalDuration(talks) }));
  return totals.filter(entry => entry.minutes > 0);
};

const byMinutesDescending = (a, b) => b.minutes - a.minutes;

const byName = (a, b) => a.localeCompare(b);

function arrange(talks) {
  const eligible = talks.filter(isEligible);
  const totals = summarize(groupByTrack(eligible));
  const hasLongTrack = totals.some(entry => entry.minutes > LONG_TRACK_MINUTES);
  const ranked = [...totals].sort(byMinutesDescending);
  const names = ranked.map(entry => entry.track);
  names.sort(byName);
  return [hasLongTrack, names];
}

const parseTalk = (line) => {
  const [speaker, track, duration, approved] = line.split(',').map(field => field.trim());
  return {
    speaker,
    track,
    duration: Number(duration),
    approved: approved === 'yes',
  };
};

const formatReport = ([hasLongTrack, names]) => {
  const listed = names.length ? names.join(', ') : '(none)';
  const warning = hasLongTrack ? 'at least one track exceeds 300 minutes' : 'all tracks within limits';
  return `Tracks: ${listed}\nStatus: ${warning}`;
};

const main = () => {
  const lines = [
    'Ada Lovelace, Algorithms, 30, yes',
    'Grace Hopper, Algorithms, 40, yes',
    'Alan Turing, Algorithms, 90, yes',
    'Edsger Dijkstra, Graphs, 45, no',
    'Barbara Liskov, Types, 60, yes',
    'Robin Milner, Types, 55, yes',
    'John McCarthy, Types, 50, yes',
    'Niklaus Wirth, Types, 60, yes',
    'Donald Knuth, Types, 60, yes',
    'Ken Thompson, Types, 60, yes',
  ];
  const talks = lines.map(parseTalk);
  console.log(formatReport(arrange(talks)));
};

main();

module.exports = { arrange, parseTalk, formatReport };

