const LOAN_PERIOD_DAYS = 14;
const BASE_RATE_CENTS = 10;
const HIGH_DEMAND_SURCHARGE_CENTS = 50;

const overdueDays = (daysKept) => {
  const excess = daysKept - LOAN_PERIOD_DAYS;
  return excess > 0 ? excess : 0;
};

const feeCents = (daysKept, highDemand) => {
  const days = overdueDays(daysKept);
  const rate = highDemand ? BASE_RATE_CENTS + HIGH_DEMAND_SURCHARGE_CENTS : BASE_RATE_CENTS;
  return days * rate;
};

const formatMoney = (cents) => `$${(cents / 100).toFixed(2)}`;

const formatBill = (record) => `${record.patron} owes ${formatMoney(record.fee)}`;

const normalizeRecord = (record) => ({
  patron: String(record.patron ?? 'Unknown patron').trim(),
  daysKept: Number(record.daysKept),
  highDemand: Boolean(record.highDemand),
});

const isValidRecord = (record) => Number.isFinite(record.daysKept) && record.daysKept >= 0;

const assess = (records) => {
  const cleaned = records.map(normalizeRecord).filter(isValidRecord);
  return cleaned
    .filter(r => overdueDays(r.daysKept) > 0)
    .map(r => ({ ...r, fee: feeCents(r.daysKept, r.highDemand) }))
    .sort((a, b) => b.fee - a.fee)
    .map(formatBill);
};

const summarize = (records) => {
  const cleaned = records.map(normalizeRecord).filter(isValidRecord);
  const total = cleaned.reduce((sum, r) => sum + feeCents(r.daysKept, r.highDemand), 0);
  const lateCount = cleaned.filter(r => overdueDays(r.daysKept) > 0).length;
  return `${lateCount} of ${cleaned.length} loans overdue, total ${formatMoney(total)}`;
};

const main = () => {
  const records = [
    { patron: 'Ada Lovelace', daysKept: 20, highDemand: false },
    { patron: 'Grace Hopper', daysKept: 21, highDemand: true },
    { patron: 'Alan Turing', daysKept: 14, highDemand: false },
    { patron: 'Edsger Dijkstra', daysKept: 30, highDemand: false },
    { patron: 'Barbara Liskov', daysKept: 9, highDemand: true },
    { patron: 'Ken Thompson', daysKept: -3, highDemand: false },
  ];

  assess(records).forEach(bill => console.log(bill));
  console.log(summarize(records));
};

main();

module.exports = { assess, overdueDays, feeCents, formatBill, summarize };

