const SENIOR_AGE = 50;

const addSplit = (sum, split) => sum + split;

const totalTime = (runner) => runner.splits.reduce(addSplit, 0);

const quicker = (best, split) => (split < best ? split : best);

const fastestSplit = (runner) => runner.splits.reduce(quicker);

const isSenior = (runner) => runner.age >= SENIOR_AGE;

const isBadSplit = (split) => !Number.isFinite(split) || split <= 0;

const validate = (runner) => {
  if (typeof runner.name !== 'string' || runner.name.length === 0) {
    throw new TypeError('runner is missing a name');
  }
  if (!Number.isFinite(runner.age)) {
    throw new TypeError(`runner ${runner.name} has a non-numeric age`);
  }
  if (!Array.isArray(runner.splits) || runner.splits.length === 0) {
    throw new TypeError(`runner ${runner.name} has no split times`);
  }
  const bad = runner.splits.find(isBadSplit);
  if (bad !== undefined) {
    throw new RangeError(`runner ${runner.name} has an invalid split: ${bad}`);
  }
  return runner;
};

const summarize = (runner) => ({
  name: runner.name,
  total: totalTime(runner),
  fastest: fastestSplit(runner),
});

const byTotalTime = (a, b) => a.total - b.total;

const entryName = (entry) => entry.name;

const analyze = (runners) => {
  if (!Array.isArray(runners)) {
    throw new TypeError('analyze expects an array of runner records');
  }
  return runners
    .map(validate)
    .filter(isSenior)
    .map(summarize)
    .sort(byTotalTime)
    .map(entryName);
};

const formatMinutes = (minutes) => {
  const whole = Math.floor(minutes);
  const seconds = Math.round((minutes - whole) * 60);
  return `${whole}:${String(seconds).padStart(2, '0')}`;
};

const indexByName = (runner) => [runner.name, runner];

const report = (runners) => {
  const podium = analyze(runners);
  const lookup = new Map(runners.map(indexByName));
  return podium.map((name, index) => {
    const runner = lookup.get(name);
    const place = String(index + 1).padStart(2, ' ');
    const total = formatMinutes(totalTime(runner));
    const best = formatMinutes(fastestSplit(runner));
    return `${place}. ${name} (age ${runner.age}) total ${total}, best split ${best}`;
  });
};

const field = [
  { name: 'Ada', age: 50, splits: [20, 21, 20] },
