const LOW_ORBIT_CEILING_KM = 2000;
const RISK_ALERT_THRESHOLD = 50;

const isLowOrbit = (sighting) => sighting.altitudeKm <= LOW_ORBIT_CEILING_KM;

const scaleRisk = (sighting) => ({
  id: sighting.id,
  altitudeKm: sighting.altitudeKm,
  scaledRisk: sighting.altitudeKm / 100 + sighting.baseRisk,
});

const formatAlert = (scaled) =>
  `ALERT ${scaled.id}: scaled risk ${scaled.scaledRisk.toFixed(1)}`;

const isValidSighting = (sighting) => {
  if (sighting === null || typeof sighting !== 'object') return false;
  if (typeof sighting.id !== 'string' || sighting.id.length === 0) return false;
  return Number.isFinite(sighting.altitudeKm) && Number.isFinite(sighting.baseRisk);
};

const parseSighting = (raw) => {
  const parts = String(raw).split(',').map(field => field.trim());
  return {
    id: parts[0],
    altitudeKm: Number(parts[1]),
    baseRisk: Number(parts[2]),
  };
};

const byScaledRiskDescending = (a, b) => b.scaledRisk - a.scaledRisk;

function track(debris) {
  if (!Array.isArray(debris)) {
    throw new TypeError('track expects an array of sightings');
  }
  const sightings = debris.map(entry => (typeof entry === 'string' ? parseSighting(entry) : entry));
  const invalid = sightings.filter(sighting => !isValidSighting(sighting));
  if (invalid.length > 0) {
    throw new TypeError(`track received ${invalid.length} malformed sighting(s)`);
  }
  return sightings
    .filter(isLowOrbit)
    .map(scaleRisk)
    .filter(scaled => scaled.scaledRisk > RISK_ALERT_THRESHOLD)
    .sort(byScaledRiskDescending)
    .map(formatAlert);
}

const summarize = (alerts, total) => {
  const header = `Scanned ${total} sighting(s), ${alerts.length} above threshold.`;
  return [header, ...alerts.map(line => `  ${line}`)].join('\n');
};

const main = () => {
  const debris = [
    { id: 'COSMOS-1408-A', altitudeKm: 480, baseRisk: 52 },
    { id: 'FENGYUN-1C-B', altitudeKm: 860, baseRisk: 44 },
    { id: 'ARIANE-UPPER', altitudeKm: 1900, baseRisk: 40 },
    { id: 'GEO-SAT-7', altitudeKm: 35786, baseRisk: 90 },
    'IRIDIUM-33-D, 780, 10',
    { id: 'ENVISAT-PANEL', altitudeKm: 400, baseRisk: 10 },
  ];
  console.log(summarize(track(debris), debris.length));
};

main();

module.exports = { track, isLowOrbit, scaleRisk, formatAlert };

