const isFailure = (log) => log.success === false;

const onlyFailures = (logs) => logs.filter(isFailure);

const getAddress = (log) => log.ip;

const markSuspicious = (ip) => `SUSPICIOUS: ${ip}`;

const isInternalAddress = (ip) => ip.startsWith('10.');

const compareAddresses = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

const isValidLog = (log) =>
  log !== null &&
  typeof log === 'object' &&
  typeof log.ip === 'string' &&
  typeof log.timestamp === 'string' &&
  typeof log.success === 'boolean';

const validate = (logs) => {
  if (!Array.isArray(logs)) {
    throw new TypeError('detect expects an array of log entries');
  }
  const bad = logs.findIndex((log) => !isValidLog(log));
  if (bad !== -1) {
    throw new TypeError(`malformed log entry at index ${bad}`);
  }
  return logs;
};

const detect = (logs) =>
  onlyFailures(validate(logs))
    .map(getAddress)
    .filter(isInternalAddress)
    .sort(compareAddresses)
    .map(markSuspicious);

const parseLine = (line) => {
  const [ip, timestamp, status] = line.split(/\s*,\s*/);
  return { ip, timestamp, success: status === 'ok' };
};

const parseLogFile = (text) => {
  const lines = text
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && !line.startsWith('#'));
  return lines.map(parseLine);
};

const countPerAddress = (logs) =>
  onlyFailures(logs).reduce((tally, log) => {
    const ip = getAddress(log);
    tally[ip] = (tally[ip] || 0) + 1;
    return tally;
  }, {});

const report = (logs) => {
  const attempts = countPerAddress(logs);
  const describe = (marker) => {
    const ip = marker.slice('SUSPICIOUS: '.length);
    return `${marker} (${attempts[ip]} failed attempt(s))`;
  };
  return detect(logs).map(describe).join('\n');
};

const rawLog = `
# ip, timestamp, status
10.0.0.1, 2026-09-18T08:14:02Z, fail
192.168.1.7, 2026-09-18T08:14:20Z, fail
10.0.0.1, 2026-09-18T08:15:11Z, fail
10.2.4.9, 2026-09-18T08:16:00Z, ok
10.2.4.9, 2026-09-18T08:16:44Z, fail
`;

console.log(report(parseLogFile(rawLog)));

module.exports = { detect, onlyFailures, getAddress, markSuspicious, parseLogFile, report };

