const HORIZON = 30;

const nextWateringDay = (plant) => plant.lastWatered + plant.frequency;

const needsWaterByHorizon = (plant) => plant.nextDay <= HORIZON;

const formatEntry = (plant) => `${plant.species} needs water on day ${plant.nextDay}`;

const isValidPlant = (plant) => {
  if (!plant || typeof plant.species !== 'string' || plant.species.trim() === '') {
    return false;
  }
  return Number.isInteger(plant.lastWatered) && Number.isInteger(plant.frequency) && plant.frequency > 0;
};

const normalize = (plant) => ({
  species: plant.species.trim(),
  lastWatered: plant.lastWatered,
  frequency: plant.frequency,
});

const byNextDay = (a, b) => a.nextDay - b.nextDay;

const schedule = (plants) => {
  if (!Array.isArray(plants)) {
    throw new TypeError('schedule expects an array of houseplant profiles');
  }
  const invalid = plants.filter(plant => !isValidPlant(plant));
  if (invalid.length > 0) {
    throw new Error(`schedule received ${invalid.length} malformed profile(s)`);
  }
  return plants
    .map(normalize)
    .map(plant => ({ ...plant, nextDay: nextWateringDay(plant) }))
    .filter(needsWaterByHorizon)
    .sort(byNextDay)
    .map(formatEntry);
};

const report = (plants) => {
  const lines = schedule(plants);
  if (lines.length === 0) {
    return `No plants need water on or before day ${HORIZON}.`;
  }
  const header = `Watering schedule through day ${HORIZON}:`;
  const body = lines.map(line => `  - ${line}`).join('\n');
  return `${header}\n${body}`;
};

const countUrgent = (plants, cutoff) => {
  const urgent = schedule(plants).filter(line => {
    const day = Number(line.match(/day (\d+)$/)[1]);
    return day <= cutoff;
  });
  return urgent.length;
};

const main = () => {
  const collection = [
    { species: 'Fern', lastWatered: 10, frequency: 7 },
    { species: 'Cactus', lastWatered: 5, frequency: 40 },
    { species: 'Basil', lastWatered: 12, frequency: 3 },
    { species: '  Monstera  ', lastWatered: 20, frequency: 9 },
    { species: 'Pothos', lastWatered: 2, frequency: 14 },
  ];
  console.log(report(collection));
  console.log(`Urgent within two weeks: ${countUrgent(collection, 14)}`);
};

main();

module.exports = { schedule, nextWateringDay, needsWaterByHorizon, formatEntry, report, countUrgent };

