const TAX_RATE = 0.2;

const profitOf = (trade) => (trade.sellPrice - trade.buyPrice) * trade.quantity;

const isProfitable = (trade) => profitOf(trade) > 0;

const keepProfitable = (trades) => trades.filter(isProfitable);

const taxOn = (profit) => profit * TAX_RATE;

const validateTrade = (trade, index) => {
  const numericFields = ["buyPrice", "sellPrice", "quantity"];
  const bad = numericFields.filter((field) => typeof trade[field] !== "number" || Number.isNaN(trade[field]));
  if (typeof trade.asset !== "string" || trade.asset.length === 0) {
    throw new TypeError(`Trade at index ${index} is missing an asset name`);
  }
  if (bad.length > 0) {
    throw new TypeError(`Trade "${trade.asset}" has invalid ${bad.join(", ")}`);
  }
  return trade;
};

const parseTrades = (trades) => {
  if (!Array.isArray(trades)) {
    throw new TypeError("assess expects an array of trades");
  }
  return trades.map(validateTrade);
};

const withTax = (trade) => ({
  asset: trade.asset,
  tax: taxOn(profitOf(trade)),
});

const byTaxDescending = (a, b) => b.tax - a.tax;

const assessTaxes = (trades) => keepProfitable(parseTrades(trades)).map(withTax).sort(byTaxDescending);

const assetOf = (entry) => entry.asset;

const assess = (trades) => assessTaxes(trades).map(assetOf);

const formatAmount = (amount) => amount.toFixed(2);

const formatRow = (asset, amount) => `${asset.padEnd(10)} ${formatAmount(amount).padStart(10)}`;

const taxReport = (trades) => {
  const assessed = assessTaxes(trades);
  const total = assessed.reduce((sum, entry) => sum + entry.tax, 0);
  return [
    "Asset            Tax owed",
    ...assessed.map((entry) => formatRow(entry.asset, entry.tax)),
    formatRow("TOTAL", total),
  ].join("\n");
};

const main = () => {
  const trades = [
    { asset: "BTC", buyPrice: 10, sellPrice: 15, quantity: 2 },
    { asset: "ETH", buyPrice: 200, sellPrice: 350, quantity: 3 },
    { asset: "DOGE", buyPrice: 0.5, sellPrice: 0.2, quantity: 1000 },
    { asset: "SOL", buyPrice: 25, sellPrice: 25, quantity: 40 },
    { asset: "XRP", buyPrice: 1.2, sellPrice: 2.4, quantity: 500 },
  ];
  console.log(assess(trades).join(", "));
  console.log(taxReport(trades));
};

main();

module.exports = { assess, profitOf, keepProfitable, taxOn, taxReport };

