const sumDonations = (campaign) => {
  return campaign.donations.reduce((total, amount) => total + amount, 0);
};

const percentFunded = (campaign) => {
  const raised = sumDonations(campaign);
  return (raised / campaign.goal) * 100;
};

const isFullyFunded = (percent) => percent >= 100;

const validateCampaign = (campaign) => {
  if (typeof campaign.cause !== 'string' || campaign.cause.trim() === '') {
    throw new TypeError('each campaign needs a non-empty cause');
  }
  if (typeof campaign.goal !== 'number' || campaign.goal <= 0) {
    throw new RangeError(`campaign "${campaign.cause}" needs a positive goal`);
  }
  const donationsValid = Array.isArray(campaign.donations)
    && campaign.donations.every(amount => typeof amount === 'number');
  if (!donationsValid) {
    throw new TypeError(`campaign "${campaign.cause}" needs an array of numeric donations`);
  }
  return campaign;
};

