  if (!Array.isArray(campaigns)) {
    throw new TypeError('track expects an array of campaigns');
  }
  return campaigns
    .map(validateCampaign)
    .map(campaign => ({ cause: campaign.cause, percent: percentFunded(campaign) }))
    .filter(entry => isFullyFunded(entry.percent))
    .sort((a, b) => b.percent - a.percent)
    .map(entry => entry.cause);
};

const formatPercent = (percent) => `${percent.toFixed(1)}%`;

const report = (campaigns) => {
  const funded = track(campaigns);
  const lines = campaigns.map(campaign => {
    const percent = percentFunded(campaign);
    const status = isFullyFunded(percent) ? 'FUNDED' : 'open';
    const raised = sumDonations(campaign);
    return `${campaign.cause.padEnd(12)} ${String(raised).padStart(6)} / ${String(campaign.goal).padEnd(6)} ${formatPercent(percent).padStart(8)}  ${status}`;
  });
  lines.push(`fully funded, best first: ${funded.join(', ') || '(none)'}`);
  return lines.join('\n');
};

