const HOURLY_STANDARD = 2;
const HOURLY_PREMIUM = 5;
const FREE_MINUTES = 15;

const rateFor = (session) => (session.premium ? HOURLY_PREMIUM : HOURLY_STANDARD);

const chargeFor = (session) => {
  const hours = session.minutes / 60;
  return rateFor(session) * hours;
};

const isBillable = (session) => session.minutes > FREE_MINUTES;

const formatMoney = (amount) => `$${amount.toFixed(2)}`;

const formatLine = (entry) => `${entry.plate} ${formatMoney(entry.charge)}`;

const normalize = (session) => {
  const plate = String(session.plate ?? '').trim().toUpperCase();
  const minutes = Number(session.minutes);
  if (!plate) {
    throw new Error('session is missing a license plate');
  }
  if (!Number.isFinite(minutes) || minutes < 0) {
    throw new Error(`invalid minutes for plate ${plate}`);
  }
  return { plate, premium: Boolean(session.premium), minutes };
};

const bill = (sessions) => {
  if (!Array.isArray(sessions)) {
    throw new TypeError('bill expects an array of sessions');
  }
  return sessions
    .map(normalize)
    .filter(isBillable)
    .map(session => ({ plate: session.plate, charge: chargeFor(session) }))
    .sort((a, b) => b.charge - a.charge)
    .map(formatLine);
};

const mergeByPlate = (sessions) => {
  const totals = new Map();
  sessions.map(normalize).forEach(session => {
    const key = `${session.plate}|${session.premium}`;
    const seen = totals.get(key);
    const minutes = (seen ? seen.minutes : 0) + session.minutes;
    totals.set(key, { ...session, minutes });
  });
  return [...totals.values()];
};

const revenue = (lines) => {
  const amounts = lines.map(line => Number(line.split(' ').pop().slice(1)));
  return amounts.reduce((sum, amount) => sum + amount, 0);
};

const main = () => {
  const sessions = [
    { plate: 'ab-123-cd', premium: false, minutes: 60 },
    { plate: 'zz-999-zz', premium: true, minutes: 90 },
    { plate: 'qq-000-qq', premium: false, minutes: 12 },
    { plate: 'ab-123-cd', premium: false, minutes: 45 },
    { plate: 'lm-555-no', premium: true, minutes: 20 }
  ];

  const lines = bill(mergeByPlate(sessions));
  lines.forEach(line => console.log(line));
  console.log(`TOTAL ${formatMoney(revenue(lines))}`);
};

main();

module.exports = { bill, rateFor, chargeFor, isBillable, mergeByPlate, revenue };

