const CALORIES_PER_GRAM = { protein: 4, carbs: 4, fat: 9 };

const mealCalories = (meal) => {
  const { protein, carbs, fat } = meal;
  return protein * CALORIES_PER_GRAM.protein
    + carbs * CALORIES_PER_GRAM.carbs
    + fat * CALORIES_PER_GRAM.fat;
};

const isLowCalorie = (meal) => mealCalories(meal) < 500;

const isHighProtein = (meal) => {
  const total = mealCalories(meal);
  if (total === 0) return false;
  return (meal.protein * CALORIES_PER_GRAM.protein) / total > 0.3;
};

const normalizeMeal = (meal) => {
  const toGrams = (value) => {
    const grams = Number(value);
    if (!Number.isFinite(grams) || grams < 0) {
      throw new TypeError(`invalid macro value for "${meal.food}": ${value}`);
    }
    return grams;
  };
  return {
    food: String(meal.food),
    protein: toGrams(meal.protein),
    carbs: toGrams(meal.carbs),
    fat: toGrams(meal.fat),
  };
};

const analyze = (meals) => {
  const scored = meals
    .map(normalizeMeal)
    .map((meal) => ({ ...meal, calories: mealCalories(meal) }));

  return scored
    .filter(isLowCalorie)
    .filter(isHighProtein)
    .sort((a, b) => a.calories - b.calories)
    .map((meal) => meal.food);
};

const describe = (meal) => {
  const flags = [];
  if (isLowCalorie(meal)) flags.push('low-calorie');
  if (isHighProtein(meal)) flags.push('high-protein');
  const tags = flags.length ? ` (${flags.join(', ')})` : '';
  return `${meal.food}: ${mealCalories(meal)} kcal${tags}`;
};

const main = () => {
  const log = [
    { food: 'grilled chicken salad', protein: 30, carbs: 20, fat: 5 },
    { food: 'buttered pasta', protein: 12, carbs: 80, fat: 22 },
    { food: 'greek yogurt', protein: 18, carbs: 12, fat: 4 },
    { food: 'protein shake', protein: 25, carbs: 8, fat: 2 },
    { food: 'steak dinner', protein: 55, carbs: 30, fat: 40 },
  ];

  log.map(normalizeMeal).forEach((meal) => console.log(describe(meal)));
  console.log('Low-calorie high-protein meals, lightest first:');
  analyze(log).forEach((food, index) => console.log(`${index + 1}. ${food}`));
};

main();

module.exports = { analyze, mealCalories, isLowCalorie, isHighProtein, describe };

