const isAvailableSaturday = (volunteer) =>
  volunteer.days.some(day => day.toLowerCase() === 'saturday');

const prefersGuide = (volunteer) =>
  volunteer.role.trim().toLowerCase() === 'guide';

const countDays = (volunteer) => volunteer.days.length;

const normalizeDays = (days) => {
  const seen = new Set();
  return days
    .map(day => String(day).trim())
    .filter(day => day.length > 0)
    .filter(day => {
      const key = day.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
};

const normalizeVolunteer = (volunteer) => ({
  name: String(volunteer.name).trim(),
  role: String(volunteer.role),
  days: normalizeDays(volunteer.days || [])
});

const schedule = (volunteers) => volunteers
  .map(normalizeVolunteer)
  .filter(isAvailableSaturday)
  .filter(prefersGuide)
  .map(volunteer => ({ name: volunteer.name, totalDays: countDays(volunteer) }))
  .sort((a, b) => b.totalDays - a.totalDays || a.name.localeCompare(b.name))
  .map(entry => entry.name);

const describeRoster = (volunteers) => {
  const chosen = schedule(volunteers);
  const lookup = new Map(volunteers.map(v => [String(v.name).trim(), v]));
  const header = `Saturday guides selected: ${chosen.length}`;
  return chosen
    .map((name, index) => {
      const days = normalizeDays(lookup.get(name).days || []);
      return `${index + 1}. ${name} — ${days.length} day(s): ${days.join(', ')}`;
    })
    .reduce((report, line) => `${report}\n${line}`, header);
};

const roster = [
  { name: 'Ada', role: 'Guide', days: ['Monday', 'Wednesday', 'Saturday'] },
  { name: 'Ben', role: 'guide', days: ['Saturday', 'Sunday'] },
  { name: 'Cleo', role: 'Greeter', days: ['Saturday', 'Tuesday', 'Thursday'] },
  { name: 'Dev', role: 'guide', days: ['Tuesday', 'Friday'] },
  { name: 'Eve', role: ' GUIDE ', days: ['Saturday', 'saturday', 'Monday', 'Friday', 'Sunday'] },
  { name: 'Fay', role: 'guide', days: ['Saturday', 'Monday', 'Tuesday'] }
];

console.log(describeRoster(roster));

