const averageWave = (readings) => {
  if (readings.length === 0) return 0;
  const total = readings.reduce((sum, height) => sum + height, 0);
  return total / readings.length;
};

const peakTide = (station) => station.baseTide + averageWave(station.waves);

const isHighTide = (level) => level > 5;

const validateStation = (station) => {
  if (typeof station.location !== 'string' || station.location.trim() === '') {
    throw new Error('station is missing a location name');
  }
  if (!Number.isFinite(station.baseTide)) {
    throw new Error(`station ${station.location} has a non-numeric base tide`);
  }
  if (!Array.isArray(station.waves) || station.waves.some(h => !Number.isFinite(h))) {
    throw new Error(`station ${station.location} has invalid wave readings`);
  }
  return station;
};

const predict = (stations) => {
  const measured = stations
    .map(validateStation)
    .map(station => ({ location: station.location, tide: peakTide(station) }));
  const risky = measured.filter(entry => isHighTide(entry.tide));
  risky.sort((a, b) => b.tide - a.tide);
  return risky.map(entry => entry.location);
};

const formatReport = (stations) => {
  const rows = stations.map(station => {
    const tide = peakTide(station);
    const flag = isHighTide(tide) ? 'WARNING' : 'ok';
    return `${station.location.padEnd(12)} base=${station.baseTide.toFixed(1)}m ` +
      `avgWave=${averageWave(station.waves).toFixed(2)}m peak=${tide.toFixed(2)}m [${flag}]`;
  });
  return rows.join('\n');
};

const main = () => {
  const stations = [
    { location: 'Harbour', baseTide: 2, waves: [3, 4, 5, 4] },
    { location: 'Cliff Bay', baseTide: 4.2, waves: [1.5, 2.1, 2.4, 1.8] },
    { location: 'Sandpit', baseTide: 1.1, waves: [0.4, 0.6, 0.5, 0.5] },
    { location: 'North Reef', baseTide: 3.5, waves: [2.2, 2.8, 3.0, 2.4] },
    { location: 'Dry Dock', baseTide: 0.8, waves: [] }
  ];

  console.log(formatReport(stations));

  const alerts = predict(stations);
  if (alerts.length === 0) {
    console.log('\nNo stations above 5 metres.');
  } else {
    console.log('\nEvacuation order (highest tide first):');
    alerts.forEach((name, index) => console.log(`${index + 1}. ${name}`));
  }
};

main();

module.exports = { predict, averageWave, peakTide, isHighTide, formatReport };

