const PER_MILE_RATE = 2;
const MIN_PER_RIDER = 5;

const tripCost = (ride) => ride.baseFare + PER_MILE_RATE * ride.miles;

const costPerRider = (ride) => tripCost(ride) / ride.riders;

const isShared = (ride) => ride.riders > 1;

const formatMoney = (amount) => `$${amount.toFixed(2)}`;

const describe = (entry) =>
  `${entry.miles} mi - ${formatMoney(entry.perRider)} per rider`;

const validateRide = (ride, index) => {
  if (typeof ride !== 'object' || ride === null) {
    throw new TypeError(`ride at index ${index} is not an object`);
  }
  const numericFields = ['miles', 'baseFare', 'riders'];
  numericFields.forEach((field) => {
    const value = ride[field];
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`ride at index ${index} has invalid ${field}`);
    }
  });
  if (ride.riders < 1 || !Number.isInteger(ride.riders)) {
    throw new RangeError(`ride at index ${index} needs a whole rider count`);
  }
  return ride;
};

const split = (rides) => {
  if (!Array.isArray(rides)) {
    throw new TypeError('split expects an array of rides');
  }
  return rides
    .map(validateRide)
    .filter(isShared)
    .map((ride) => ({ miles: ride.miles, perRider: costPerRider(ride) }))
    .filter((entry) => entry.perRider >= MIN_PER_RIDER)
    .sort((a, b) => b.perRider - a.perRider)
    .map(describe);
};

const summarize = (rides) => {
  const shared = rides.filter(isShared);
  const revenue = shared.reduce((sum, ride) => sum + tripCost(ride), 0);
  const riders = shared.reduce((sum, ride) => sum + ride.riders, 0);
  return `${shared.length} shared rides, ${riders} riders, ${formatMoney(revenue)} collected`;
};

