    { miles: 10, baseFare: 5, riders: 2 },
    { miles: 4, baseFare: 3, riders: 4 },
    { miles: 25, baseFare: 8, riders: 3 },
    { miles: 6, baseFare: 2, riders: 1 },
    { miles: 12, baseFare: 6, riders: 2 },
  ];

  split(rides).forEach((line) => console.log(line));
  console.log(summarize(rides));
};

main();

