const MIN_WEIGHT_KG = 50;
const MIN_DAYS_SINCE_DONATION = 56;
const MIN_IRON_LEVEL = 12.5;

const hasSufficientWeight = (donor) => donor.weight >= MIN_WEIGHT_KG;

const hasWaitedLongEnough = (donor) => donor.lastDonationDay > MIN_DAYS_SINCE_DONATION;

const hasHealthyIron = (donor) => donor.ironLevel > MIN_IRON_LEVEL;

const byName = (a, b) => a.name.localeCompare(b.name);

const screen = (donors) => donors
  .filter(hasSufficientWeight)
  .filter(hasWaitedLongEnough)
  .filter(hasHealthyIron)
  .slice()
  .sort(byName)
  .map(donor => donor.name);

const parseDonor = (line) => {
  const fields = line.split(',');
  const [name, weight, lastDonationDay, ironLevel] = fields.map(field => field.trim());
  return {
    name,
    weight: Number(weight),
    lastDonationDay: Number(lastDonationDay),
    ironLevel: Number(ironLevel)
  };
};

const isValidDonor = (donor) => donor.name.length > 0
  && [donor.weight, donor.lastDonationDay, donor.ironLevel].every(value => Number.isFinite(value));

const loadDonors = (text) => {
  const trimmed = text.split('\n').map(line => line.trim());
  const rows = trimmed.filter(line => line.length > 0);
  const parsed = rows.map(parseDonor);
  const invalid = parsed.filter(donor => !isValidDonor(donor));
  if (invalid.length > 0) {
    const labels = invalid.map((donor, index) => donor.name || `row ${index + 1}`);
    throw new Error(`Malformed donor records: ${labels.join('; ')}`);
  }
  return parsed;
};

const explainRejection = (donor) => {
  const reasons = [];
  if (!hasSufficientWeight(donor)) reasons.push(`weight ${donor.weight}kg below ${MIN_WEIGHT_KG}kg`);
  if (!hasWaitedLongEnough(donor)) reasons.push(`donated only ${donor.lastDonationDay} days ago`);
  if (!hasHealthyIron(donor)) reasons.push(`iron ${donor.ironLevel} not above ${MIN_IRON_LEVEL}`);
  return `${donor.name}: ${reasons.join(', ')}`;
};

const report = (donors) => {
  const eligible = screen(donors);
  const rejected = donors
    .filter(donor => !eligible.includes(donor.name))
    .map(explainRejection);
  const lines = [`Eligible (${eligible.length}): ${eligible.join(', ')}`];
  rejected.forEach(reason => lines.push(`  rejected -> ${reason}`));
  return lines.join('\n');
};

