  Ana Silva, 72, 30, 15.2
  Chen Wei, 81, 120, 11.9
  Mira Patel, 55, 200, 12.6
`;

console.log(report(loadDonors(roster)));

module.exports = { screen, hasSufficientWeight, hasWaitedLongEnough, hasHealthyIron, loadDonors, report };

