const BATTERY_LIMIT = 80;

const drainPerKm = (weight) => 1 + 0.5 * weight;

const roundTripBattery = (distance, weight) => 2 * distance * drainPerKm(weight);

const exceedsLimit = (battery) => battery > BATTERY_LIMIT;

const validateDelivery = (delivery) => {
  if (!delivery || typeof delivery.id !== "string" || delivery.id.length === 0) {
    throw new TypeError("each delivery needs a non-empty string id");
  }
  const numeric = ["distanceKm", "weightKg"].filter((key) => typeof delivery[key] !== "number" || !Number.isFinite(delivery[key]));
  if (numeric.length > 0) {
    throw new TypeError(`delivery ${delivery.id}: ${numeric.join(", ")} must be finite numbers`);
  }
  if (delivery.distanceKm < 0 || delivery.weightKg < 0) {
    throw new RangeError(`delivery ${delivery.id}: distance and weight must not be negative`);
  }
  return delivery;
};

const route = (deliveries) => {
  if (!Array.isArray(deliveries)) {
    throw new TypeError("deliveries must be an array");
  }
  return deliveries
    .map(validateDelivery)
    .map((delivery) => ({
      id: delivery.id,
      distanceKm: delivery.distanceKm,
      battery: roundTripBattery(delivery.distanceKm, delivery.weightKg),
    }))
    .filter((plan) => !exceedsLimit(plan.battery))
    .sort((a, b) => a.distanceKm - b.distanceKm)
    .map((plan) => plan.id);
};

const planAll = (deliveries) =>
  deliveries.map(validateDelivery).map((delivery) => ({
    id: delivery.id,
    distanceKm: delivery.distanceKm,
    battery: roundTripBattery(delivery.distanceKm, delivery.weightKg),
  }));

const formatPlan = (plan) => {
  const verdict = exceedsLimit(plan.battery) ? "SKIP" : "OK";
  return `${plan.id.padEnd(6)} ${plan.distanceKm.toFixed(1)} km  ${plan.battery.toFixed(1)}%  ${verdict}`;
};

const report = (deliveries) => {
  const lines = planAll(deliveries).map(formatPlan);
  const order = route(deliveries);
  lines.push(`route: ${order.length > 0 ? order.join(" -> ") : "(none)"}`);
  return lines.join("\n");
};

const main = () => {
  const deliveries = [
    { id: "PKG-A", distanceKm: 10, weightKg: 2 },
    { id: "PKG-B", distanceKm: 4, weightKg: 1.5 },
    { id: "PKG-C", distanceKm: 25, weightKg: 3 },
    { id: "PKG-D", distanceKm: 7, weightKg: 0 },
    { id: "PKG-E", distanceKm: 12, weightKg: 5 },
  ];
  console.log(report(deliveries));
  const heaviest = deliveries.reduce((worst, item) => (item.weightKg > worst.weightKg ? item : worst));
  console.log(`heaviest package ${heaviest.id} drains ${drainPerKm(heaviest.weightKg).toFixed(2)}% per km`);
};

main();

module.exports = { route, drainPerKm, roundTripBattery, exceedsLimit, report };

