const minDepth = (trail) => {
  return trail.measurements.reduce(
    (lo, d) => Math.min(lo, d),
    Infinity
  );
};

const averageDepth = (trail) => {
  const total = trail.measurements.reduce(
    (sum, d) => sum + d,
    0
  );
  return total / trail.measurements.length;
};

const isOpen = (trail) => minDepth(trail) >= 20;

const validate = (trail) => {
  if (typeof trail.name !== 'string' || trail.name.length === 0) {
    throw new Error('trail is missing a name');
  }
  if (!Array.isArray(trail.measurements) || trail.measurements.length === 0) {
    throw new Error(`trail ${trail.name} has no measurements`);
  }
  const bad = trail.measurements.find(
    (d) => typeof d !== 'number' || Number.isNaN(d)
  );
  if (bad !== undefined) {
    throw new Error(`trail ${trail.name} has an invalid measurement: ${bad}`);
  }
  return trail;
};

const summarize = (trail) => ({
  name: trail.name,
  difficulty: trail.difficulty,
  average: averageDepth(trail)
});

const report = (trails) => trails
  .map(validate)
  .filter(isOpen)
  .map(summarize)
  .filter((entry) => entry.average >= 25)
  .sort((a, b) => b.average - a.average)
  .map((entry) => entry.name);

const describe = (trail) => {
  const status = isOpen(trail) ? 'open' : 'closed';
  const avg = averageDepth(trail).toFixed(1);
  return `${trail.name} (${trail.difficulty}): min ${minDepth(trail)}", avg ${avg}" - ${status}`;
};

const main = () => {
  const trails = [
    { name: 'Summit Ridge', difficulty: 'expert', measurements: [30, 32, 34] },
    { name: 'Larch Loop', difficulty: 'easy', measurements: [22, 24, 23, 21, 20, 22, 25] },
    { name: 'Powder Bowl', difficulty: 'intermediate', measurements: [48, 52, 50, 47, 55, 53, 51] },
    { name: 'Creekside', difficulty: 'easy', measurements: [12, 14, 19, 18, 16, 15, 17] },
    { name: 'Bear Chute', difficulty: 'expert', measurements: [40, 38, 44, 41, 39, 42, 45] }
  ];

  trails.forEach(
    (trail) => console.log(describe(trail))
  );

  const ranked = report(trails);
  console.log('\nDeepest open trails (avg >= 25"):');
  if (ranked.length === 0) {
    console.log('none');
  }
  ranked.forEach(
    (name, index) => console.log(`${index + 1}. ${name}`)
  );
};

main();

module.exports = { report, minDepth, averageDepth, isOpen, describe };

