const TARGET_SERVINGS = 12;

const scalingFactor = (baseServings) => TARGET_SERVINGS / baseServings;

const needsScalingUp = (recipe) => recipe.factor > 1;

const isWithinCapacity = (recipe) => recipe.factor <= 4;

const formatScaled = (recipe) => {
  const rounded = Math.round(recipe.factor * 100) / 100;
  return `${recipe.title} (x${rounded})`;
};

const withFactor = (recipe) => ({
  ...recipe,
  factor: scalingFactor(recipe.baseServings),
});

const byTitle = (a, b) => a.title.localeCompare(b.title);

const scale = (recipes) => recipes
  .map(withFactor)
  .filter(needsScalingUp)
  .filter(isWithinCapacity)
  .sort(byTitle)
  .map(formatScaled);

const validate = (recipe) => {
  if (typeof recipe.title !== 'string' || recipe.title.trim() === '') {
    throw new TypeError('recipe title must be a non-empty string');
  }
  if (!Number.isFinite(recipe.baseServings) || recipe.baseServings <= 0) {
    throw new RangeError(`invalid base serving size for "${recipe.title}"`);
  }
  if (!Array.isArray(recipe.ingredients) || recipe.ingredients.length === 0) {
    throw new TypeError(`"${recipe.title}" needs at least one ingredient`);
  }
};

const shoppingList = (recipes) => {
  const counts = new Map();
  recipes.map(withFactor).forEach((recipe) => {
    recipe.ingredients.forEach((name) => {
      const key = name.toLowerCase();
      counts.set(key, (counts.get(key) || 0) + recipe.factor);
    });
  });
  return [...counts.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([name, portions]) => `${name}: ${Math.round(portions * 10) / 10} portions`);
};

const main = () => {
  const recipes = [
    { title: 'Tomato Soup', baseServings: 6, ingredients: ['tomato', 'cream', 'basil'] },
    { title: 'Apple Crumble', baseServings: 4, ingredients: ['apple', 'flour', 'butter'] },
    { title: 'Banquet Paella', baseServings: 2, ingredients: ['rice', 'saffron', 'prawn'] },
    { title: 'Family Lasagne', baseServings: 12, ingredients: ['pasta', 'beef', 'cheese'] },
    { title: 'Chickpea Curry', baseServings: 8, ingredients: ['chickpea', 'onion', 'cream'] },
  ];

  recipes.forEach(validate);

  console.log('Recipes to scale up:');
