  console.log(`Shopping list for ${TARGET_SERVINGS} servings each:`);
  shoppingList(recipes).forEach((line) => console.log(`  ${line}`));
};

main();

module.exports = { scale, scalingFactor, needsScalingUp, formatScaled, shoppingList };

