const addWait = (sum, value) => sum + value;

const totalOf = (values) => values.reduce(addWait, 0);

const average = (values) => totalOf(values) / values.length;

const isOperating = (ride) => ride.operating === true;

const hasSamples = (ride) => Array.isArray(ride.waitTimes) && ride.waitTimes.length > 0;

const validate = (rides) => {
  if (!Array.isArray(rides)) {
    throw new TypeError('rides must be an array');
  }
  rides.forEach((ride, index) => {
    if (typeof ride.name !== 'string' || ride.name.length === 0) {
      throw new TypeError(`ride at index ${index} needs a name`);
    }
    if (!Array.isArray(ride.waitTimes)) {
      throw new TypeError(`ride ${ride.name} needs a waitTimes array`);
    }
  });
  return rides;
};

const summarize = (rides) => rides
  .filter(isOperating)
  .filter(hasSamples)
  .map((ride) => ({ name: ride.name, mean: average(ride.waitTimes) }));

const quickest = (summaries) => summaries
  .reduce((best, entry) => (best === null || entry.mean < best.mean ? entry : best), null);

const evaluate = (rides) => {
  const summaries = summarize(validate(rides));
  const best = quickest(summaries);
  const quickExists = summaries.some((entry) => entry.mean < 15);
  const longWaits = summaries
    .filter((entry) => entry.mean > 45)
    .map((entry) => entry.name);
  const combined = totalOf(summaries.map((entry) => entry.mean));
  return [best === null ? null : best.name, quickExists, longWaits, combined];
};

const formatReport = (result) => {
  const [shortest, quick, longWaits, combined] = result;
  const lines = [
    `shortest average wait: ${shortest === null ? 'n/a' : shortest}`,
    `ride under 15 minutes: ${quick ? 'yes' : 'no'}`,
    `over 45 minutes: ${longWaits.length === 0 ? 'none' : longWaits.join(', ')}`,
    `combined average wait: ${combined.toFixed(1)} minutes`,
  ];
  return lines.map((line) => `  ${line}`).join('\n');
};

const park = [
  { name: 'coaster', waitTimes: [10, 20], operating: true },
  { name: 'ferris wheel', waitTimes: [50, 60, 40], operating: true },
  { name: 'log flume', waitTimes: [70, 80], operating: false },
  { name: 'tea cups', waitTimes: [5, 8, 11], operating: true },
];

console.log(formatReport(evaluate(park)));

module.exports = { evaluate, summarize, average, formatReport };

