const MIN_GRAMS = 50;

const normalizeName = (name) => String(name).trim().toLowerCase();

const validateOrder = (order, index) => {
  if (!order || !Array.isArray(order.ingredients)) {
    throw new TypeError(`Order #${index} must carry an ingredients list`);
  }
  if (!Number.isFinite(order.quantity) || order.quantity < 0) {
    throw new RangeError(`Order #${index} (${order.pastry}) has an invalid quantity`);
  }
  return order;
};

const scaleOrder = (order) => order.ingredients.map(
  (ingredient) => ({ name: normalizeName(ingredient.name), grams: ingredient.amount * order.quantity })
);

const addEntry = (totals, entry) => {
  totals.set(entry.name, (totals.get(entry.name) || 0) + entry.grams);
  return totals;
};

const consolidate = (entries) => entries.reduce(addEntry, new Map());

const keepHeavyEnough = (totals) => [...totals.entries()].filter(
  ([, grams]) => grams >= MIN_GRAMS
);

const sortByName = (pairs) => pairs.slice().sort(
  ([leftName], [rightName]) => leftName.localeCompare(rightName)
);

const usesFlour = (order) => order.ingredients.some(
  (ingredient) => normalizeName(ingredient.name).includes('flour')
);

const forecast = (orders) => {
  orders.forEach(validateOrder);
  const scaled = orders.flatMap(scaleOrder);
  const kept = sortByName(keepHeavyEnough(consolidate(scaled)));
  const names = kept.map(([name]) => name);
  const totalWeight = kept.reduce((sum, [, grams]) => sum + grams, 0);
  const allNeedFlour = orders.every(usesFlour);
  return [names, totalWeight, allNeedFlour];
};

const formatReport = ([names, totalWeight, allNeedFlour]) => {
  const lines = names.map((name) => `  - ${name}`);
  lines.push(`  total: ${totalWeight} g`);
  lines.push(`  every order needs flour: ${allNeedFlour ? 'yes' : 'no'}`);
  return ['Shopping list', ...lines].join('\n');
};

const exampleOrders = [
  {
    pastry: 'cake',
    quantity: 2,
    ingredients: [{ name: 'Flour', amount: 100 }, { name: 'yeast', amount: 20 }]
  },
  {
    pastry: 'brioche',
    quantity: 3,
    ingredients: [
      { name: 'flour', amount: 80 },
      { name: 'butter', amount: 40 },
      { name: 'salt', amount: 5 }
    ]
  }
];

console.log(formatReport(forecast(exampleOrders)));

module.exports = { forecast, formatReport };

