const MIN_AVERAGE_DELAY = 5;

const validateRoute = (route) => {
  if (!route || typeof route.id !== 'string' || route.id.length === 0) {
    throw new TypeError('each route needs a non-empty string id');
  }
  if (route.scheduled.length !== route.actual.length) {
    throw new RangeError(`route ${route.id}: scheduled/actual length mismatch`);
  }
};

const computeDelays = (scheduled, actual) => {
  return actual.map(
    (arrival, index) => arrival - scheduled[index]
  );
};

const average = (values) => {
  if (values.length === 0) {
    return 0;
  }
  const total = values.reduce(
    (sum, value) => sum + value,
    0
  );
  return total / values.length;
};

const summarize = (route) => {
  validateRoute(route);
  const delays = computeDelays(route.scheduled, route.actual);
  return { id: route.id, delays, averageDelay: average(delays) };
};

const isOnTime = (delay) => delay === 0;

const countOnTimeTrips = (summaries) => {
  const perRoute = summaries.map(
    (summary) => summary.delays.filter(isOnTime).length
  );
  return perRoute.reduce((sum, count) => sum + count, 0);
};

const mostDelayed = (summaries) => {
  const worst = summaries.reduce(
    (best, summary) => (summary.averageDelay > best.averageDelay ? summary : best)
  );
  return worst.id;
};

const analyze = (routes) => {
  const summaries = routes.map(summarize);
  const delayed = summaries.filter(
    (summary) => summary.averageDelay >= MIN_AVERAGE_DELAY
  );
  if (delayed.length === 0) {
    return [null, 0, []];
  }
  const sortedIds = delayed
    .map(summary => summary.id)
    .sort((a, b) => a.localeCompare(b));
  return [mostDelayed(delayed), countOnTimeTrips(delayed), sortedIds];
};

const formatReport = ([worstId, onTime, ids]) => {
  const list = ids.length > 0 ? ids.join(', ') : '(none)';
  return `worst: ${worstId}\non-time trips: ${onTime}\ndelayed routes: ${list}`;
};

const main = () => {
  const routes = [
    { id: 'express', scheduled: [10, 20], actual: [15, 30] },
    { id: 'crosstown', scheduled: [8, 12, 19], actual: [8, 24, 26] },
    { id: 'airport', scheduled: [30, 45], actual: [31, 46] }
  ];
  console.log(formatReport(analyze(routes)));
};

main();

module.exports = { analyze, summarize, computeDelays, average, formatReport };

