const PLOTS = [
  { id: 'P1', area: 20 },
  { id: 'P2', area: 35 },
  { id: 'P3', area: 12 },
  { id: 'P4', area: 50 }
];

const meetsArea = (plot, minArea) => plot.area >= minArea;

const suitablePlots = (minArea) =>
  PLOTS.filter(plot => meetsArea(plot, minArea));

const normalizeCrop = (crop) => String(crop).trim().toLowerCase();

const normalizeCrops = (crops) =>
  crops.map(normalizeCrop);

const wantsTomatoes = (request) => normalizeCrops(request.crops).includes('tomatoes');

const addArea = (sum, request) => sum + request.minArea;

const totalRequestedArea = (requests) =>
  requests.reduce(addArea, 0);

const largestRequest = (requests) =>
  requests.reduce((best, r) => (r.minArea > best.minArea ? r : best));

const allocate = (requests) => {
  const allocations = requests.map(request => ({
    request,
    plots: suitablePlots(request.minArea)
  }));
  const valid = allocations.filter(entry => entry.plots.length > 0);
  const validRequests = valid.map(entry => entry.request);
  const allWantTomatoes = validRequests.every(wantsTomatoes);
  const names = validRequests.map(r => r.name);
  const neediest = validRequests.length > 0 ? largestRequest(validRequests).name : null;
  return [neediest, allWantTomatoes, names];
};

const formatPlot = (plot) => `${plot.id}(${plot.area})`;

const describePlots = (plots) =>
  plots.map(formatPlot).join(', ');

const buildReport = (requests) => {
  const [neediest, allWantTomatoes, names] = allocate(requests);
  const validRequests = requests.filter(r => suitablePlots(r.minArea).length > 0);
  const lines = validRequests.map(r =>
    `${r.name} needs ${r.minArea} -> ${describePlots(suitablePlots(r.minArea))}`
  );
  const rejected = requests.filter(r => !names.includes(r.name));
  rejected.forEach(r => lines.push(`${r.name} needs ${r.minArea} -> no suitable plot`));
  lines.push(`total requested area: ${totalRequestedArea(validRequests)}`);
  lines.push(`largest request: ${neediest === null ? 'none' : neediest}`);
  lines.push(`everyone wants tomatoes: ${allWantTomatoes}`);
  return lines.join('\n');
};

