const PLOTS = [
  { id: 'P1', area: 20 },
  { id: 'P2', area: 35 },
  { id: 'P3', area: 12 },
  { id: 'P4', area: 50 }
];

const meetsArea = function(plot, minArea) { return plot.area >= minArea; };

const suitablePlots = function(minArea) {
  return PLOTS.filter(function(plot) { return meetsArea(plot, minArea); });
};

const normalizeCrop = function(crop) { return String(crop).trim().toLowerCase(); };

const normalizeCrops = function(crops) {
  return crops.map(normalizeCrop);
};

const wantsTomatoes = function(request) { return normalizeCrops(request.crops).includes('tomatoes'); };

const addArea = function(sum, request) { return sum + request.minArea; };

const totalRequestedArea = function(requests) {
  return requests.reduce(addArea, 0);
};

const largestRequest = function(requests) {
  return requests.reduce(function(best, r) { return (r.minArea > best.minArea ? r : best); });
};

const allocate = function(requests) {
  const allocations = requests.map(function(request) { return ({
    request,
    plots: suitablePlots(request.minArea)
  }); });
  const valid = allocations.filter(function(entry) { return entry.plots.length > 0; });
  const validRequests = valid.map(function(entry) { return entry.request; });
  const allWantTomatoes = validRequests.every(wantsTomatoes);
  const names = validRequests.map(function(r) { return r.name; });
  const neediest = validRequests.length > 0 ? largestRequest(validRequests).name : null;
  return [neediest, allWantTomatoes, names];
};

const formatPlot = function(plot) { return `${plot.id}(${plot.area})`; };

const describePlots = function(plots) {
  return plots.map(formatPlot).join(', ');
};

const buildReport = function(requests) {
  const [neediest, allWantTomatoes, names] = allocate(requests);
  const validRequests = requests.filter(function(r) { return suitablePlots(r.minArea).length > 0; });
  const lines = validRequests.map(function(r) {
    return `${r.name} needs ${r.minArea} -> ${describePlots(suitablePlots(r.minArea))}`;
  });
  const rejected = requests.filter(function(r) { return !names.includes(r.name); });
  rejected.forEach(function(r) { lines.push(`${r.name} needs ${r.minArea} -> no suitable plot`); });
  lines.push(`total requested area: ${totalRequestedArea(validRequests)}`);
  lines.push(`largest request: ${neediest === null ? 'none' : neediest}`);
  lines.push(`everyone wants tomatoes: ${allWantTomatoes}`);
  return lines.join('\n');
};

const main = function() {
  const sample = [
    { name: 'sue', minArea: 10, crops: ['Tomatoes', 'basil'] },
    { name: 'raj', minArea: 30, crops: ['tomatoes'] },
    { name: 'mia', minArea: 80, crops: ['pumpkins'] }
  ];
  console.log(buildReport(sample));
  console.log(JSON.stringify(allocate(sample)));
};

main();

module.exports = { allocate, buildReport, totalRequestedArea, suitablePlots };

