const MIN_YEAR = 2010;

const addWatts = (sum, watts) => sum + watts;

const totalOutput = (readings) => readings.reduce(addWatts, 0);

const isRecent = (panel) => panel.year >= MIN_YEAR;

const summarize = (panel) => ({
  serial: panel.serial,
  total: totalOutput(panel.readings),
  hasZeroDay: panel.readings.some(watts => watts === 0),
});

const validate = (panel) => {
  if (typeof panel.serial !== 'string' || panel.serial.length === 0) {
    throw new Error('panel is missing a serial number');
  }
  if (!Array.isArray(panel.readings)) {
    throw new Error(`panel ${panel.serial} has invalid readings`);
  }
  if (panel.readings.some(watts => !Number.isFinite(watts))) {
    throw new Error(`panel ${panel.serial} has a non-numeric reading`);
  }
  if (!Number.isInteger(panel.year)) {
    throw new Error(`panel ${panel.serial} has an invalid installation year`);
  }
  return panel;
};

const higherOutput = (best, record) => (record.total > best.total ? record : best);

const bestOf = (records) => records.reduce(higherOutput, records[0]);

const averageOf = (records) => {
  const sum = records.reduce((acc, record) => acc + record.total, 0);
  return sum / records.length;
};

const serialsByOutput = (records) => [...records]
  .sort((a, b) => a.total - b.total)
  .map(record => record.serial);

const track = (panels) => {
  const records = panels
    .map(validate)
    .filter(isRecent)
    .map(summarize);

  if (records.length === 0) {
    return [null, false, 0, []];
  }

  const anyZero = records.some(record => record.hasZeroDay);
  return [bestOf(records).serial, anyZero, averageOf(records), serialsByOutput(records)];
};

const report = ([topSerial, anyZero, average, sorted]) => {
  const lines = [
    `top producer: ${topSerial === null ? 'none' : topSerial}`,
    `zero-output day detected: ${anyZero}`,
    `average weekly output: ${average.toFixed(1)} Wh`,
    `ranked serials: ${sorted.join(' < ')}`,
  ];
  return lines.map(line => `  ${line}`).join('\n');
};

const fleet = [
  { serial: 'alpha', readings: [10, 20, 0], year: 2015 },
  { serial: 'beta', readings: [40, 35, 30], year: 2018 },
  { serial: 'gamma', readings: [90, 80, 70], year: 2004 },
];

console.log(report(track(fleet)));

module.exports = { track, totalOutput, report };

