const add = (accumulator, value) => accumulator + value;

const average = (samples) => samples.reduce(add, 0) / samples.length;

const validateBatch = (batch) => {
  if (typeof batch.name !== 'string' || batch.name.trim() === '') {
    throw new TypeError('each batch needs a material name');
  }
  if (typeof batch.weight !== 'number' || Number.isNaN(batch.weight)) {
    throw new TypeError(`batch "${batch.name}" needs a numeric weight`);
  }
  if (!Array.isArray(batch.samples) || batch.samples.length === 0) {
    throw new TypeError(`batch "${batch.name}" needs at least one sample`);
  }
  return batch;
};

const summarize = (batch) => ({
  name: batch.name.trim(),
  weight: batch.weight,
  contamination: average(batch.samples),
});

const isClean = (summary) => summary.contamination <= 15;

const isGlass = (summary) => summary.name.toLowerCase() === 'glass';

const cleaner = (best, candidate) => (candidate.contamination < best.contamination ? candidate : best);

const byName = (a, b) => a.name.localeCompare(b.name);

const sort = (batches) => {
  const summaries = batches.map(validateBatch).map(summarize);
  const clean = summaries.filter(isClean);
  const totalWeight = clean.map((summary) => summary.weight).reduce(add, 0);
  const allGlass = clean.every(isGlass);
  const purest = clean.length > 0 ? clean.reduce(cleaner) : null;
  const names = clean.map((summary) => summary.name).sort(byName);
  return [purest === null ? null : purest.name, totalWeight, allGlass, names];
};

const formatPercent = (value) => `${value.toFixed(1)}%`;

const formatReport = (result) => {
  const [purestName, totalWeight, allGlass, names] = result;
  const lines = [
    `purest material: ${purestName === null ? 'none' : purestName}`,
    `clean weight: ${totalWeight}`,
    `all glass: ${allGlass}`,
    `clean materials: ${names.join(', ') || 'none'}`,
  ];
  return lines.join('\n');
};

const main = () => {
  const batches = [
    { name: 'glass', weight: 100, samples: [5, 15] },
    { name: 'plastic', weight: 250, samples: [20, 30, 10] },
    { name: 'aluminium', weight: 80, samples: [2, 4] },
