    .map(summarize)
    .map((summary) => `${summary.name}: ${formatPercent(summary.contamination)}`);
  console.log(overview.join('\n'));
  console.log(formatReport(sort([batches[0]])));
  console.log(formatReport(sort(batches)));
};

main();

module.exports = { sort, average, summarize, formatReport };

