const ROW_CAPACITY = {
  a: 10,
  b: 10,
  c: 12,
  d: 14,
  e: 8
};

const normalizeRow = (row) => String(row).trim().toLowerCase();

const capacityOf = (row) => {
  const capacity = ROW_CAPACITY[normalizeRow(row)];
  return capacity === undefined ? 0 : capacity;
};

const parseRequest = (request) => ({
  name: String(request.name).trim(),
  size: Number(request.size),
  rows: (request.rows || []).map(normalizeRow)
});

const isWellFormed = (request) =>
  request.name.length > 0 && Number.isInteger(request.size) && request.size > 0;

const usableRows = (request) => {
  const fitting = request.rows.filter(row => capacityOf(row) >= request.size);
  return fitting.sort();
};

const assign = (request) => {
  const rows = usableRows(request);
  return rows.length === 0 ? null : { ...request, row: rows[0] };
};

const optimize = (requests) => {
  const parsed = requests.map(parseRequest).filter(isWellFormed);
  const assignments = parsed.map(assign).filter(entry => entry !== null);

  const totalSeats = assignments.reduce((sum, entry) => sum + entry.size, 0);
  const hasLargeGroup = assignments.some(entry => entry.size > 10);

  const names = assignments
    .slice()
    .sort((left, right) => right.size - left.size)
    .map(entry => entry.name);

  return [totalSeats, hasLargeGroup, names];
};

const describeAssignments = (requests) => {
  const lines = requests
    .map(parseRequest)
    .filter(isWellFormed)
    .map(assign)
    .map((entry, index) =>
      entry === null
        ? `${index + 1}. request rejected (no row with enough capacity)`
        : `${index + 1}. ${entry.name} -> row ${entry.row} (${entry.size} seats)`
    );
  return lines.join('\n');
};

const bookings = [
  { name: 'dan', size: 4, rows: ['a'] },
  { name: 'erin', size: 12, rows: ['B', 'd', 'c'] },
  { name: 'faye', size: 9, rows: ['e', 'a'] },
  { name: 'gus', size: 20, rows: ['a', 'd'] }
];

console.log(describeAssignments(bookings));
console.log(optimize(bookings));
console.log(optimize([{ name: 'dan', size: 4, rows: ['a'] }]));

module.exports = { optimize, describeAssignments };

