const MIN_COMPETITOR_DISTANCE = 2;
const REVENUE_PER_VISITOR = 5;
const MIN_REVENUE = 500;
const HIGH_REVENUE = 1000;

const isClear = (stop) => {
  const distances = stop.competitorDistances || [];
  return distances.every(d => d >= MIN_COMPETITOR_DISTANCE);
};

const expectedRevenue = (stop) => stop.footTraffic * REVENUE_PER_VISITOR;

const withRevenue = (stop) => ({
  neighborhood: stop.neighborhood,
  revenue: expectedRevenue(stop)
});

const isWorthwhile = (priced) => priced.revenue >= MIN_REVENUE;

const validStops = (stops) => stops
  .filter(isClear)
  .map(withRevenue)
  .filter(isWorthwhile);

const allHighRevenue = (priced) =>
  priced.every(p => p.revenue >= HIGH_REVENUE);

const mostProfitable = (priced) => {
  if (priced.length === 0) {
    return null;
  }
  const best = priced.reduce((a, b) => (b.revenue > a.revenue ? b : a));
  return best.neighborhood;
};

const namesByRevenue = (priced) => [...priced]
  .sort((a, b) => a.revenue - b.revenue)
  .map(p => p.neighborhood);

const plan = (stops) => {
  const priced = validStops(stops);
  return [mostProfitable(priced), allHighRevenue(priced), namesByRevenue(priced)];
};

const formatMoney = (amount) => `$${amount.toLocaleString('en-US')}`;

const describeStop = (stop) => {
  const nearest = (stop.competitorDistances || []).reduce((m, d) => Math.min(m, d), Infinity);
  const competitor = Number.isFinite(nearest) ? `${nearest} mi` : 'none';
  return `${stop.neighborhood}: ${formatMoney(expectedRevenue(stop))} (nearest competitor ${competitor})`;
};

const report = (stops) => {
  const [best, high, names] = plan(stops);
  const lines = stops.map(describeStop);
  lines.push(`Best stop: ${best === null ? 'no viable stops' : best}`);
  lines.push(`All valid stops at or above ${formatMoney(HIGH_REVENUE)}: ${high}`);
  lines.push(`Route order: ${names.join(' -> ')}`);
  return lines.join('\n');
};

const main = () => {
  const stops = [
    { neighborhood: 'downtown', footTraffic: 200, competitorDistances: [3, 4] },
    { neighborhood: 'riverside', footTraffic: 400, competitorDistances: [1.5, 6] },
    { neighborhood: 'uptown', footTraffic: 150, competitorDistances: [5] },
    { neighborhood: 'harbor', footTraffic: 80, competitorDistances: [] }
  ];
  console.log(report(stops));
  console.log(JSON.stringify(plan([stops[0]])));
};

main();

module.exports = { plan, expectedRevenue, report };

