const roundWeight = (weight) => Math.round(weight * 1000) / 1000;

const scaleMalts = (malts, factor) =>
  malts.map(w => roundWeight(w * factor));

const addWeights = (sum, weight) => sum + weight;

const totalWeight = (malts) => malts.reduce(addWeights, 0);

const scaleRecipe = (recipe) => {
  const factor = scalingFactor(recipe.volume);
  const malts = scaleMalts(recipe.malts, factor);
  return { name: recipe.name, volume: recipe.volume, malts, total: roundWeight(totalWeight(malts)) };
};

const withinWeightLimit = (recipe) => recipe.total <= MAX_TOTAL_WEIGHT;

const isSmallAddition = (weight) => weight < SMALL_ADDITION_LIMIT;

const recipeHasSmallAddition = (recipe) => recipe.malts.some(isSmallAddition);

const hasSmallAddition = (recipes) => recipes.some(recipeHasSmallAddition);

const byTotalDescending = (a, b) => b.total - a.total;

const isInvalidWeight = (weight) => typeof weight !== 'number' || weight < 0;

const validateRecipe = (recipe) => {
  if (typeof recipe.name !== 'string' || recipe.name.length === 0) {
    throw new TypeError('each recipe needs a non-empty name');
  }
