  const scaled = recipes.map(validateRecipe).map(scaleRecipe);
  const kept = scaled.filter(withinWeightLimit);
  const smallAddition = hasSmallAddition(kept);
  const sorted = [...kept].sort(byTotalDescending);
  const names = sorted.map(r => r.name);
  return [names.length, smallAddition, names];
};

