const BOX_COUNT = 20;
const MIN_PER_BOX = 1;
const MAX_DISTANCE = 50;

const average = (numbers) => {
  const total = numbers.reduce(
    (sum, n) => sum + n,
    0,
  );
  return total / numbers.length;
};

const averageDistance = (crop) => average(crop.distances);

const isLocal = (crop) => averageDistance(crop) <= MAX_DISTANCE;

const weightPerBox = (crop) => crop.harvested / BOX_COUNT;

const describe = (crop) => ({
  vegetable: crop.vegetable,
  perBox: weightPerBox(crop),
});

const validateCrop = (crop) => {
  if (typeof crop.vegetable !== 'string' || crop.vegetable.length === 0) {
    throw new TypeError('each crop needs a vegetable name');
  }
  if (typeof crop.harvested !== 'number' || crop.harvested < 0) {
    throw new TypeError(`harvested weight for ${crop.vegetable} must be a non-negative number`);
  }
  if (!Array.isArray(crop.distances) || crop.distances.length === 0) {
    throw new TypeError(`${crop.vegetable} needs at least one farm distance`);
  }
};

const hasMinimum = (box) => box.perBox >= MIN_PER_BOX;

const meetsMinimum = (boxes) => boxes.every(hasMinimum);

const bestProvider = (boxes) =>
  boxes.reduce((best, box) => (box.perBox > best.perBox ? box : best)).vegetable;

const byName = (a, b) => a.localeCompare(b);

const sortedNames = (boxes) => {
  const names = boxes.map((box) => box.vegetable);
  return names.sort(byName);
};

