  const list = names.length > 0 ? names.join(', ') : 'none';
  const status = minimumMet ? 'all boxes meet the minimum' : 'some boxes fall short';
  return `top provider: ${top || 'none'}\nlocal crops: ${list}\n${status}`;
};

