const roundCups = (cups) => Math.round(cups * 100) / 100;

const validateDog = (dog) => {
  if (typeof dog.name !== "string" || dog.name.trim() === "") {
    throw new Error("each dog needs a name");
  }
  if (typeof dog.weight !== "number" || dog.weight <= 0) {
    throw new Error(`invalid weight for ${dog.name}`);
  }
  if (!Array.isArray(dog.activities) || dog.activities.length === 0) {
    throw new Error(`missing activity durations for ${dog.name}`);
  }
  return dog;
};

const averageActivity = (dog) =>
  sumOf(dog.activities) / dog.activities.length;

const dailyCups = (dog) => {
  const base = 2 + dog.weight / 10;
  return averageActivity(dog) > 60 ? base + 0.5 : base;
};

const toMeal = (dog) => ({
  name: dog.name,
  cups: roundCups(dailyCups(dog)),
  averageMinutes: roundCups(averageActivity(dog)),
});

const isLargeEater = (meal) => meal.cups >= 3;

const byCupsDescending = (a, b) => b.cups - a.cups;

const plan = (dogs) => {
  if (!Array.isArray(dogs)) {
    throw new Error("dogs must be an array");
  }
  const meals = dogs.map(validateDog).map(toMeal);
