const WEEKDAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

const maxReading = (readings) =>
  readings.reduce((best, t) => (t > best ? t : best), -Infinity);

const shortfall = (log) => log.target - maxReading(log.readings);

const dateKey = (date) => {
  const weekday = WEEKDAYS.indexOf(String(date).trim().toLowerCase());
  if (weekday >= 0) return weekday;
  const stamp = Date.parse(date);
  return Number.isNaN(stamp) ? Number.MAX_SAFE_INTEGER : stamp;
};

const validate = (log) => {
  if (!log || typeof log.date === 'undefined') throw new TypeError('log is missing a firing date');
  if (typeof log.target !== 'number') throw new TypeError(`log ${log.date} has no numeric target`);
  if (!Array.isArray(log.readings) || log.readings.length === 0) {
    throw new TypeError(`log ${log.date} has no recorded temperatures`);
  }
  return log;
};

const summarize = (log) => ({
  date: log.date,
  peak: maxReading(log.readings),
  shortfall: shortfall(log)
});

const average = (values) => {
  const total = values.reduce((sum, v) => sum + v, 0);
  return total / values.length;
};

const monitor = (readings) => {
  const summaries = readings.map(validate).map(summarize);
  const successes = summaries.filter((s) => s.shortfall <= 50);
  if (successes.length === 0) return [0, false, []];

  const peaks = successes.map((s) => s.peak);
  const highHeat = peaks.every((peak) => peak > 2000);
  const sorted = successes.slice().sort((a, b) => dateKey(a.date) - dateKey(b.date));
  return [average(peaks), highHeat, sorted.map((s) => s.date)];
};

const report = (result) => {
  const [avgPeak, highHeat, dates] = result;
  const lines = [
    `average peak: ${avgPeak.toFixed(1)}`,
    `all firings above 2000: ${highHeat ? 'yes' : 'no'}`,
    `successful firings: ${dates.join(', ') || 'none'}`
  ];
  return lines.join('\n');
};

const logs = [
  { date: 'monday', target: 2000, readings: [1900, 1960] },
  { date: 'wednesday', target: 2100, readings: [1500, 1800, 2090] },
  { date: 'tuesday', target: 2200, readings: [1400, 1700, 1905] },
  { date: 'friday', target: 2050, readings: [1990, 2040, 2010] }
];

console.log(monitor([logs[0]]));
console.log(report(monitor(logs)));

module.exports = { monitor, report, maxReading, shortfall };

