const average = (values) =>
  values.length === 0
    ? 0
    : values.reduce((sum, v) => sum + v, 0) / values.length;

const expectedResetTime = (room) =>
  room.baseResetTime + average(room.misplacedProps) * 2;

const normalize = (item) => ({
  theme: String(item.theme),
  baseResetTime: Number(item.baseResetTime),
  misplacedProps: (item.misplacedProps || []).map(n => Number(n)),
});

const isValid = (room) =>
  room.theme.length > 0 &&
  Number.isFinite(room.baseResetTime) &&
  room.misplacedProps.every(n => Number.isFinite(n));

const describe = (room) => {
  const expected = expectedResetTime(room);
  return {
    theme: room.theme,
    averageMisplaced: average(room.misplacedProps),
    expected,
  };
};

const selectComplex = (reports) =>
  reports.filter(r => r.expected >= 10);

const allUnder = (reports, limit) =>
  reports.every(r => r.expected < limit);

const longestTheme = (reports) => {
  const winner = reports.reduce(
    (best, r) => (best === null || r.expected > best.expected ? r : best),
    null,
  );
  return winner === null ? null : winner.theme;
};

const byExpected = (a, b) => a.expected - b.expected;

const sortedThemes = (reports) =>
  [...reports].sort(byExpected).map(r => r.theme);

const generate = (items) => {
  const rooms = (items || []).map(normalize).filter(isValid);
  const complex = selectComplex(rooms.map(describe));
  return [longestTheme(complex), allUnder(complex, 30), sortedThemes(complex)];
};

