  const [longest, quickReset, themes] = result;
  const lines = [
    `Longest reset: ${longest === null ? 'none' : longest}`,
    `Quick reset overall: ${quickReset ? 'yes' : 'no'}`,
  ];
  themes.forEach((theme, index) => lines.push(`${index + 1}. ${theme}`));
  return lines.join('\n');
};

