const totalMiles = (bike) => {
  const add = (sum, miles) => sum + miles;
  return bike.monthlyMiles.reduce(add, 0);
};

const isOlder = (bike) => bike.monthsInService >= 6;

const averageMonthlyMiles = (bike) => {
  const months = bike.monthlyMiles.length;
  return months === 0 ? 0 : totalMiles(bike) / months;
};

const validate = (bike) => {
  if (typeof bike.code !== 'string' || bike.code.length === 0) {
    throw new Error('each bicycle needs a bike code');
  }
  if (!Number.isFinite(bike.monthsInService) || bike.monthsInService < 0) {
    throw new Error(`bicycle ${bike.code} has an invalid months in service count`);
  }
  const milesInvalid = (m) => !Number.isFinite(m);
  if (!Array.isArray(bike.monthlyMiles) || bike.monthlyMiles.some(milesInvalid)) {
    throw new Error(`bicycle ${bike.code} has an invalid monthly miles list`);
  }
  return bike;
};

const highestMileageCode = (bikes) => {
  const better = (best, bike) => (totalMiles(bike) > totalMiles(best) ? bike : best);
  return bikes.reduce(better).code;
};

const hasExtremeMileage = (bikes) => {
  const extreme = (bike) => totalMiles(bike) > 5000;
  return bikes.some(extreme);
};

const codesByAverageDesc = (bikes) => {
  const byAverage = (a, b) => averageMonthlyMiles(b) - averageMonthlyMiles(a);
  return bikes
    .slice()
    .sort(byAverage)
    .map(bike => bike.code);
};

const schedule = (bicycles) => {
  if (!Array.isArray(bicycles) || bicycles.length === 0) {
    throw new Error('schedule needs a non-empty list of bicycles');
  }
  const fleet = bicycles.map(validate);
  const older = fleet.filter(isOlder);
  return [highestMileageCode(fleet), hasExtremeMileage(older), codesByAverageDesc(older)];
};

const formatReport = ([topCode, extreme, codes]) => {
  const lines = [
    `highest total mileage: ${topCode}`,
    `mileage above 5000 miles: ${extreme ? 'yes' : 'no'}`
  ];
  const order = codes.map((code, index) => `  ${index + 1}. ${code}`);
  return lines.concat(order.length === 0 ? ['  (no bicycles in service 6+ months)'] : order).join('\n');
};

const main = () => {
  const fleet = [
    { code: 'x', monthsInService: 10, monthlyMiles: [50, 100] },
    { code: 'y', monthsInService: 3, monthlyMiles: [400, 380, 410] },
    { code: 'z', monthsInService: 24, monthlyMiles: [600, 750, 900, 1200, 1400, 1500] },
    { code: 'w', monthsInService: 8, monthlyMiles: [120, 90, 140, 200] }
  ];
  console.log(formatReport(schedule(fleet)));
};

main();

module.exports = { schedule, totalMiles, averageMonthlyMiles, formatReport };

