const toTotal = (goals) => {
  return goals.reduce((sum, goals_in_match) => sum + goals_in_match, 0);
};

const normalize = (team) => {
  const goals = Array.isArray(team.goals) ? team.goals : [];
  return { mascot: String(team.mascot), deduction: Number(team.deduction) || 0, goals };
};

const scoreTeam = (team) => {
  const clean = normalize(team);
  return { ...clean, total: toTotal(clean.goals), score: toTotal(clean.goals) - clean.deduction };
};

const validTeams = (matches) => {
  const scored = matches.map(scoreTeam);
  return scored.filter((team) => team.score >= 0);
};

const scoredEveryMatch = (team) => {
  return team.goals.every((goalsInMatch) => goalsInMatch >= 1);
};

const allConsistent = (teams) => {
  return teams.every(scoredEveryMatch);
};

const bestMascot = (teams) => {
  if (teams.length === 0) return null;
  const best = teams.reduce((leader, team) => (team.score > leader.score ? team : leader));
  return best.mascot;
};

const averageScore = (teams) => {
  if (teams.length === 0) return 0;
  const total = teams.reduce((sum, team) => sum + team.score, 0);
  return total / teams.length;
};

const rankedMascots = (teams) => {
  const byScore = teams.slice();
  byScore.sort((a, b) => b.score - a.score);
  return byScore.map((team) => team.mascot);
};

const calculate = (matches) => {
  const teams = validTeams(matches);
  return [bestMascot(teams), allConsistent(teams), averageScore(teams), rankedMascots(teams)];
};

const formatStandings = ([winner, consistent, average, order]) => {
  const lines = order.map((mascot, index) => `${index + 1}. ${mascot}`);
  lines.push(`winner: ${winner}`);
  lines.push(`consistent scorers: ${consistent}`);
  lines.push(`average final score: ${average.toFixed(2)}`);
  return lines.join('\n');
};

const main = () => {
  const league = [
    { mascot: 'tigers', deduction: 1, goals: [2, 3] },
    { mascot: 'otters', deduction: 2, goals: [1, 1, 4] },
    { mascot: 'moles', deduction: 9, goals: [0, 2] },
  ];
  console.log(formatStandings(calculate(league)));
  console.log(JSON.stringify(calculate([{ mascot: 'tigers', deduction: 1, goals: [2, 3] }])));
};

main();

module.exports = { calculate, formatStandings, scoreTeam };

