  const scored = matches.map(scoreTeam);
  return scored.filter(function(team) { return team.score >= 0; });
};

const scoredEveryMatch = function(team) {
  return team.goals.every(function(goalsInMatch) { return goalsInMatch >= 1; });
};

const allConsistent = function(teams) {
  return teams.every(scoredEveryMatch);
};

const bestMascot = function(teams) {
  if (teams.length === 0) return null;
  const best = teams.reduce(function(leader, team) { return (team.score > leader.score ? team : leader); });
  return best.mascot;
};

const averageScore = function(teams) {
  if (teams.length === 0) return 0;
  const total = teams.reduce(function(sum, team) { return sum + team.score; }, 0);
  return total / teams.length;
};

const rankedMascots = function(teams) {
  const byScore = teams.slice();
  byScore.sort(function(a, b) { return b.score - a.score; });
  return byScore.map(function(team) { return team.mascot; });
};

const calculate = function(matches) {
  const teams = validTeams(matches);
  return [bestMascot(teams), allConsistent(teams), averageScore(teams), rankedMascots(teams)];
};

const formatStandings = function([winner, consistent, average, order]) {
  const lines = order.map(function(mascot, index) { return `${index + 1}. ${mascot}`; });
  lines.push(`winner: ${winner}`);
  lines.push(`consistent scorers: ${consistent}`);
  lines.push(`average final score: ${average.toFixed(2)}`);
  return lines.join('\n');
};

const main = function() {
  const league = [
    { mascot: 'tigers', deduction: 1, goals: [2, 3] },
    { mascot: 'otters', deduction: 2, goals: [1, 1, 4] },
    { mascot: 'moles', deduction: 9, goals: [0, 2] },
  ];
  console.log(formatStandings(calculate(league)));
  console.log(JSON.stringify(calculate([{ mascot: 'tigers', deduction: 1, goals: [2, 3] }])));
};

main();

module.exports = { calculate, formatStandings, scoreTeam };

