const normalize = (location) => ({
  street: String(location.street).trim(),
  soilVolume: Number(location.soilVolume),
  depths: toDepths(location.depths)
});

const validate = (segment) => {
  if (!segment.street) {
    throw new Error('segment is missing a street name');
  }
  if (segment.depths.length === 0 || segment.depths.some(d => !Number.isFinite(d))) {
    throw new Error(`invalid pipe depths for ${segment.street}`);
  }
  if (!Number.isFinite(segment.soilVolume)) {
    throw new Error(`invalid soil volume for ${segment.street}`);
  }
  return segment;
};

const minPipeDepth = (segment) => Math.min(...segment.depths);

const hasClearance = (segment) => minPipeDepth(segment) >= MIN_CLEARANCE;

const suitability = (segment) => segment.soilVolume * minPipeDepth(segment);

const byName = (a, b) => a.localeCompare(b);

const bestStreet = (scored) => scored.reduce(
  (best, entry) => (entry.score > best.score ? entry : best),
  { street: null, score: -Infinity }
).street;

