const agePenalty = (age) => age * 200;

const mileagePenalty = (mileage) => mileage * 0.1;

const conditionBonus = (condition) => Math.max(0, condition - 5) * 100;

const isRecent = (car) => car.age < 20;

const normalize = (car) => ({
  basePrice: Number(car.basePrice) || 0,
  age: Number(car.age) || 0,
  mileage: Number(car.mileage) || 0,
  condition: Number(car.condition) || 0,
});

const finalValue = (car) => {
  const { basePrice, age, mileage, condition } = normalize(car);
  return basePrice - agePenalty(age) - mileagePenalty(mileage) + conditionBonus(condition);
};

const appraise = (cars) => {
  if (!Array.isArray(cars)) {
    throw new TypeError('appraise expects a list of car records');
  }
  return cars
    .filter(isRecent)
    .map(finalValue)
    .filter((value) => value > 0)
    .sort((a, b) => b - a);
};

const formatMoney = (value) => `$${value.toFixed(2)}`;

const summarize = (values) => {
  if (values.length === 0) {
    return 'no vehicles retained any value';
  }
  const total = values.reduce((sum, value) => sum + value, 0);
  const average = total / values.length;
  const parts = values.map(formatMoney);
  return `${values.length} valued: ${parts.join(', ')} (avg ${formatMoney(average)})`;
};

