    throw new Error(`tank ${tank.id} needs non-empty numeric acidity and ammonia readings`);
  }
  return tank;
};

const monitor = (tanks) => {
  if (!Array.isArray(tanks)) {
    throw new TypeError('monitor expects a list of tank records');
  }
  return tanks
    .map(validateTank)
    .filter(hasHighAmmonia)
    .map(tank => average(tank.acidity))
    .filter(isDangerousAcidity)
    .sort((a, b) => a - b);
};

const round2 = (value) => Math.round(value * 100) / 100;

