const BASE_RATE = 0.05;

const baseFeed = (weight) => weight * BASE_RATE;

const totalFeed = (weight, activity) => baseFeed(weight) * activity;

const isHeavyEnough = (animal) => animal.weight > 10;

const isValidAnimal = (animal) => {
  if (!animal || typeof animal !== 'object') return false;
  const numericFields = ['weight', 'age', 'activity'];
  return numericFields.every((field) => Number.isFinite(animal[field]));
};

const ration = (animals) => {
  if (!Array.isArray(animals)) {
    throw new TypeError('ration expects an array of animal records');
  }
  const usable = animals.filter(isValidAnimal);
  return usable
    .filter(isHeavyEnough)
    .map((animal) => totalFeed(animal.weight, animal.activity))
    .filter((feed) => feed >= 1)
    .sort((a, b) => b - a);
};

const roundKg = (value) => Math.round(value * 100) / 100;

const formatFeed = (feed) => `${roundKg(feed).toFixed(2)} kg`;

const summarize = (feeds) => {
  const total = feeds.reduce((sum, feed) => sum + feed, 0);
  return {
    count: feeds.length,
    total: roundKg(total),
    heaviest: feeds.length ? roundKg(feeds[0]) : 0,
  };
};

const describeHerd = (label, animals) => {
  const feeds = ration(animals);
  const stats = summarize(feeds);
  const listed = feeds.map(formatFeed).join(', ') || 'none';
  return `${label}: ${stats.count} fed [${listed}] total ${stats.total} kg, top ${stats.heaviest} kg`;
};

const main = () => {
  const farm = [
    { species: 'cow', weight: 550, age: 4, activity: 1.2 },
    { species: 'goat', weight: 45, age: 2, activity: 1.0 },
