    { species: 'dog', weight: 12, age: 7, activity: 1.3 },
    { species: 'cat', weight: 5, age: 3, activity: 1.4 },
    { species: 'puppy', weight: 11, age: 1, activity: 1.6 },
  ];
  const zoo = [
    { species: 'elephant', weight: 4000, age: 20, activity: 1.1 },
    { species: 'gazelle', weight: 18, age: 4, activity: 2.0 },
    { species: 'parrot', weight: 1.2, age: 6, activity: 1.0 },
    { species: 'mystery', weight: 'unknown', age: 2, activity: 1.0 },
  ];

  const herds = [
    ['Farm', farm],
    ['Kennel', kennel],
    ['Zoo', zoo],
  ];
  herds.forEach(([label, animals]) => console.log(describeHerd(label, animals)));

  const grandTotal = herds
    .map(([, animals]) => summarize(ration(animals)).total)
    .reduce((sum, total) => sum + total, 0);
