const addSize = (acc, size) => acc + size;

const totalLoad = (jobs) => jobs.reduce(addSize, 0);

const utilization = (server) => (totalLoad(server.jobs) / server.capacity) * 100;

const isActive = (server) => server.jobs.length > 0;

const isHighLoad = (percent) => percent > 80;

const isBadSize = (size) => !Number.isFinite(size) || size < 0;

const validateServer = (server) => {
  if (typeof server.id !== 'string' || server.id.length === 0) {
    throw new Error('server identifier must be a non-empty string');
  }
  if (!Number.isFinite(server.capacity) || server.capacity <= 0) {
    throw new Error(`server ${server.id}: capacity must be a positive number`);
  }
  if (!Array.isArray(server.jobs) || server.jobs.some(isBadSize)) {
    throw new Error(`server ${server.id}: jobs must be an array of non-negative numbers`);
  }
  return server;
};

function balance(servers) {
  if (!Array.isArray(servers)) {
    throw new TypeError('servers must be an array');
  }
  return servers
    .map(validateServer)
    .filter(isActive)
    .map(utilization)
    .filter(isHighLoad)
    .sort((a, b) => b - a);
}

const formatPercent = (percent) => `${percent.toFixed(1)}%`;

const describe = (name, servers) => {
  const hot = balance(servers);
  const listed = hot.length > 0 ? hot.map(formatPercent).join(', ') : 'none';
  return `${name}: ${hot.length} overloaded server(s) -> ${listed}`;
};

const main = () => {
  const cluster = [
    { id: 'web-1', capacity: 100, jobs: [40, 35, 10] },
    { id: 'web-2', capacity: 100, jobs: [50, 45] },
    { id: 'web-3', capacity: 200, jobs: [] },
    { id: 'db-1', capacity: 500, jobs: [480, 15] },
  ];

  const edge = [
    { id: 'edge-a', capacity: 64, jobs: [8, 8] },
    { id: 'edge-b', capacity: 64, jobs: [60, 4, 2] },
  ];

  const idle = [{ id: 'spare-1', capacity: 32, jobs: [] }];

  const reports = [
    describe('cluster', cluster),
    describe('edge', edge),
    describe('idle', idle),
  ];
  reports.forEach(line => console.log(line));

  try {
    balance([{ id: 'bad-1', capacity: 0, jobs: [5] }]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
};

main();

module.exports = { balance, totalLoad, utilization };

