const toSeconds = (value) => {
  const seconds = Number(value);
  if (!Number.isFinite(seconds) || seconds < 0) {
    throw new RangeError(`invalid duration: ${value}`);
  }
  return seconds;
};

const normalizeCall = (call) => ({
  holdTime: toSeconds(call.hold_time),
  talkTime: toSeconds(call.talk_time),
  resolved: Boolean(call.resolved)
});

const totalDuration = (call) => call.holdTime + call.talkTime;

const isAbandoned = (call) => call.holdTime > 300 && !call.resolved;

const average = (values) => {
  const sum = values.reduce((running, value) => running + value, 0);
  return sum / values.length;
};

const analyze = (calls) => {
  const normalized = calls.map(call => normalizeCall(call));
  const handled = normalized.filter(call => !isAbandoned(call));
  const durations = handled.map(call => totalDuration(call));
  const lengthy = durations.filter(duration => duration > 600);
  const ranked = lengthy.sort((a, b) => b - a);
  if (ranked.length === 0) {
    return 0;
  }
  return average(ranked);
};

const formatSeconds = (seconds) => {
  const minutes = Math.floor(seconds / 60);
  const rest = Math.round(seconds % 60);
  return `${minutes}m${String(rest).padStart(2, '0')}s`;
};

const describeBatch = (label, calls) => {
  const meanLength = analyze(calls);
  const abandonedCount = calls
    .map(call => normalizeCall(call))
    .filter(call => isAbandoned(call))
    .length;
  const tail = meanLength === 0 ? 'no lengthy calls' : `mean ${formatSeconds(meanLength)}`;
  return `${label}: ${calls.length} calls, ${abandonedCount} abandoned, ${tail}`;
};

const batches = [
  ['monday', [
    { hold_time: 120, talk_time: 700, resolved: true },
    { hold_time: 400, talk_time: 500, resolved: false },
    { hold_time: 60, talk_time: 300, resolved: true },
    { hold_time: 320, talk_time: 900, resolved: true }
  ]],
  ['tuesday', [
    { hold_time: 30, talk_time: 90, resolved: true },
    { hold_time: 310, talk_time: 45, resolved: false }
  ]],
  ['wednesday', [
    { hold_time: 600, talk_time: 600, resolved: true },
    { hold_time: 700, talk_time: 20, resolved: false },
    { hold_time: 200, talk_time: 1000, resolved: false }
  ]]
];

batches.forEach(([label, calls]) => console.log(describeBatch(label, calls)));

module.exports = { analyze, totalDuration, isAbandoned };

