const INCH_TO_CM = 2.54;

const inchesToCm = (inches) => inches * INCH_TO_CM;

const sumMeasurementsInCm = (measurements) => {
  const converted = measurements.map(inchesToCm);
  return converted.reduce((total, value) => total + value, 0);
};

const isValidClient = (client) => {
  if (!client || typeof client.name !== 'string' || !Array.isArray(client.measurements)) {
    return false;
  }
  return client.measurements.every(m => typeof m === 'number' && Number.isFinite(m) && m > 0);
};

const hasEnoughMeasurements = (client) => client.measurements.length >= 3;

const convert = (clients) => {
  if (!Array.isArray(clients)) {
    throw new TypeError('convert expects a list of client records');
  }
  const invalid = clients.filter(client => !isValidClient(client));
  if (invalid.length > 0) {
    throw new TypeError(`malformed client records: ${invalid.length}`);
  }
  return clients
    .filter(hasEnoughMeasurements)
    .map(client => sumMeasurementsInCm(client.measurements))
    .filter(total => total >= 50)
    .sort((a, b) => a - b);
};

const formatCm = (value) => `${value.toFixed(2)} cm`;

const describeTotals = (totals) => {
  if (totals.length === 0) {
    return 'no qualifying clients';
  }
  return totals.map(formatCm).join(', ');
};

const runExample = (label, clients) => {
  try {
    const totals = convert(clients);
    console.log(`${label}: ${describeTotals(totals)}`);
  } catch (err) {
    console.log(`${label}: rejected (${err.message})`);
  }
};

