  const tailorQueue = [
    { name: 'Ada', measurements: [12, 18, 24, 30] },
    { name: 'Bram', measurements: [10, 9] },
    { name: 'Chen', measurements: [5, 6, 7] },
    { name: 'Dina', measurements: [40, 22, 16, 8, 4] },
    { name: 'Emil', measurements: [2, 3, 4] },
  ];
  runExample('tailor queue', tailorQueue);

  const singleClient = tailorQueue.filter(client => client.name === 'Chen');
  runExample('single client', singleClient);

  runExample('empty roster', []);
  runExample('bad roster', [{ name: 'Faye', measurements: [12, 'oops', 20] }]);
};

main();

