const average = (prices) => {
  const total = prices.reduce((sum, price) => sum + price, 0);
  return total / prices.length;
};

const hasPreviousSale = (record) => Array.isArray(record.sales) && record.sales.length > 0;

const estimateValue = (record) => average(record.sales) * record.rarity + record.condition;

const roundMoney = (amount) => Math.round(amount * 100) / 100;

const validateRecord = (record) => {
  if (typeof record.artist !== "string" || record.artist.trim() === "") {
    throw new Error("each record needs an artist name");
  }
  if (!(record.condition >= 0 && record.condition <= 10)) {
    throw new Error(`condition for ${record.artist} must be between 0 and 10`);
  }
  if (!(record.rarity > 0)) {
    throw new Error(`rarity multiplier for ${record.artist} must be positive`);
  }
  if (record.sales && record.sales.some((price) => typeof price !== "number" || price < 0)) {
    throw new Error(`sale prices for ${record.artist} must be non-negative numbers`);
  }
};

const appraise = (records) => {
  records.forEach(validateRecord);
  const sellable = records.filter(hasPreviousSale);
  const values = sellable.map(estimateValue);
  const worthwhile = values.filter((value) => value > 50);
  const sorted = worthwhile.sort((a, b) => b - a);
  return sorted.map(roundMoney);
};

const formatCurrency = (amount) => `$${amount.toFixed(2)}`;

const summarise = (label, values) => {
  const total = values.reduce((sum, value) => sum + value, 0);
  const listed = values.map(formatCurrency).join(", ");
  return `${label}: ${values.length} item(s) over $50 [${listed}] total ${formatCurrency(total)}`;
};

