const sumMonsterXp = (monsters) => monsters.reduce(
  (total, xp) => total + xp,
  0,
);

const totalExperience = (player) => sumMonsterXp(player.monsters) + player.questBonus;

const levelsGained = (experience) => Math.floor(experience / 1000);

const newLevel = (player) => player.baseLevel + levelsGained(totalExperience(player));

const hasMonsterKills = (player) => player.monsters.length > 0;

const isQualifying = (level) => level >= 10;

const descending = (a, b) => b - a;

const normalize = (player) => ({
  username: player.username,
  baseLevel: player.baseLevel || 0,
  monsters: Array.isArray(player.monsters) ? player.monsters.filter(xp => xp > 0) : [],
  questBonus: player.questBonus || 0,
});

const calculate = (players) => {
  const active = players.map(normalize).filter(hasMonsterKills);
  const levels = active.map(newLevel);
  return levels.filter(isQualifying).sort(descending);
};

const describe = (player) => {
  const clean = normalize(player);
  const xp = totalExperience(clean);
  return `${clean.username}: ${clean.baseLevel} -> ${newLevel(clean)} (${xp} xp)`;
};

const report = (label, players) => {
  console.log(`--- ${label} ---`);
  players.forEach(player => console.log(describe(player)));
  console.log('qualifying levels:', calculate(players));
};

const main = () => {
  const guild = [
    { username: 'aria', baseLevel: 8, monsters: [400, 650, 1200], questBonus: 500 },
