const sumMonsterXp = function(monsters) { return monsters.reduce(
  function(total, xp) { return total + xp; },
  0,
); };

const totalExperience = function(player) { return sumMonsterXp(player.monsters) + player.questBonus; };

const levelsGained = function(experience) { return Math.floor(experience / 1000); };

const newLevel = function(player) { return player.baseLevel + levelsGained(totalExperience(player)); };

const hasMonsterKills = function(player) { return player.monsters.length > 0; };

const isQualifying = function(level) { return level >= 10; };

const descending = function(a, b) { return b - a; };

const normalize = function(player) { return ({
  username: player.username,
  baseLevel: player.baseLevel || 0,
  monsters: Array.isArray(player.monsters) ? player.monsters.filter(function(xp) { return xp > 0; }) : [],
  questBonus: player.questBonus || 0,
}); };

const calculate = function(players) {
  const active = players.map(normalize).filter(hasMonsterKills);
  const levels = active.map(newLevel);
  return levels.filter(isQualifying).sort(descending);
};

const describe = function(player) {
  const clean = normalize(player);
  const xp = totalExperience(clean);
  return `${clean.username}: ${clean.baseLevel} -> ${newLevel(clean)} (${xp} xp)`;
};

