const baseToll = (axles) => (axles === 2 ? 2 : 5);

const weightSurcharge = (weightTons) => Math.max(0, Math.ceil(weightTons - 10));

const finalToll = (vehicle) => {
  const gross = baseToll(vehicle.axles) + weightSurcharge(vehicle.weightTons);
  return vehicle.hasPass ? gross * 0.5 : gross;
};

const isTolledVehicle = (vehicle) => vehicle.axles >= 2;

const highestFirst = (a, b) => b - a;

const tabulate = (vehicles) => {
  const sortedTolls = vehicles
    .filter(isTolledVehicle)
    .map((vehicle) => finalToll(vehicle))
    .filter((toll) => toll !== 0)
    .sort(highestFirst);
  return sortedTolls.reduce((total, toll) => total + toll, 0);
};

const formatCurrency = (amount) => `$${amount.toFixed(2)}`;

const parseRecord = (line) => {
  const fields = line.split(',').map((field) => field.trim());
  const [plate, axles, weightTons, hasPass] = fields;
  return {
    plate: plate.toUpperCase(),
    axles: Number.parseInt(axles, 10),
    weightTons: Number.parseFloat(weightTons),
    hasPass: hasPass === 'yes',
  };
};

const parseManifest = (text) => {
  const lines = text
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  return lines.map(parseRecord);
};

const describeVehicle = (vehicle) => {
  const passNote = vehicle.hasPass ? 'e-pass' : 'cash';
  return `${vehicle.plate}: ${vehicle.axles} axles, ${vehicle.weightTons}t, ${passNote}`;
};

const buildReport = (vehicles) => {
  const rows = vehicles.map((vehicle) => {
    const owed = isTolledVehicle(vehicle) ? formatCurrency(finalToll(vehicle)) : 'exempt';
    return `${describeVehicle(vehicle)} -> ${owed}`;
  });
  rows.push(`TOTAL: ${formatCurrency(tabulate(vehicles))}`);
  return rows.join('\n');
};

