  const manifest = `
    abc-123, 2, 4.5, no
    trk-900, 5, 18.2, no
    van-771, 3, 9.0, yes
    bik-042, 1, 0.3, no
    haul-55, 6, 24.9, yes
  `;
  const vehicles = parseManifest(manifest);
  console.log(buildReport(vehicles));
};

main();

module.exports = { tabulate, baseToll, finalToll, parseManifest, buildReport };

