const QUIET_START = 22;
const QUIET_END = 7;
const SEVERITY_THRESHOLD = 500;

const isQuietHour = (hour) => hour >= QUIET_START || hour < QUIET_END;

const severityScore = (complaint) => complaint.decibels * complaint.duration;

const validateComplaint = (complaint) => {
  const { unit, decibels, hour, duration } = complaint;
  if (typeof unit !== "string" && typeof unit !== "number") {
    throw new TypeError("complaint is missing a unit identifier");
  }
  if (!Number.isFinite(decibels) || decibels <= 0) {
    throw new RangeError(`unit ${unit}: decibel level must be positive`);
  }
  if (!Number.isInteger(hour) || hour < 0 || hour > 23) {
    throw new RangeError(`unit ${unit}: hour must be an integer in 0..23`);
  }
  if (!Number.isFinite(duration) || duration <= 0) {
    throw new RangeError(`unit ${unit}: duration must be positive`);
  }
  return complaint;
};

function filter(complaints) {
  const checked = complaints.map(validateComplaint);
  const quiet = checked.filter(c => isQuietHour(c.hour));
  const scores = quiet.map(severityScore);
  const severe = scores.filter(score => score > SEVERITY_THRESHOLD);
  const ranked = severe.sort((a, b) => b - a);
  return ranked.length > 0 ? ranked[0] : null;
}

const describeBatch = (label, complaints) => {
  const worst = filter(complaints);
  const verdict = worst === null
    ? "no severe quiet-hour noise issues"
    : `worst severity score ${worst}`;
  return `${label}: ${complaints.length} complaint(s) -> ${verdict}`;
};

const main = () => {
  const batches = [
    ["Tower A", [
      { unit: "A-101", decibels: 85, hour: 23, duration: 40 },
      { unit: "A-204", decibels: 70, hour: 14, duration: 90 },
      { unit: "A-310", decibels: 62, hour: 2, duration: 15 },
      { unit: "A-115", decibels: 95, hour: 6, duration: 35 },
    ]],
    ["Tower B", [
      { unit: "B-001", decibels: 60, hour: 23, duration: 5 },
      { unit: "B-002", decibels: 55, hour: 9, duration: 120 },
    ]],
    ["Annex", []],
  ];

  batches
    .map(([label, complaints]) => describeBatch(label, complaints))
    .forEach(line => console.log(line));

  try {
    filter([{ unit: "C-9", decibels: 80, hour: 25, duration: 10 }]);
  } catch (err) {
    console.log(`rejected input: ${err.message}`);
  }
};

main();

module.exports = { filter, isQuietHour, severityScore, describeBatch };

