const isHeavy = (pkg) => pkg.weightKg > 20;

const routingScore = (pkg) => pkg.priority * pkg.zone;

const isDeliverable = (pkg) => pkg.priority !== 0;

const describe = (pkg) => `${pkg.tracking} z${pkg.zone} ${pkg.weightKg}kg p${pkg.priority}`;

const highestFirst = (a, b) => b - a;

const validatePackage = (pkg) => {
  if (typeof pkg.tracking !== 'string' || pkg.tracking.length === 0) {
    throw new TypeError('package is missing a tracking number');
  }
  const numbers = [pkg.zone, pkg.weightKg, pkg.priority];
  if (numbers.some(value => typeof value !== 'number' || Number.isNaN(value))) {
    throw new TypeError(`package ${pkg.tracking} has non-numeric fields`);
  }
  return pkg;
};

const route = (packages) => {
  const checked = packages.map(validatePackage);
  const scores = checked.filter(isDeliverable).map(routingScore);
  const priorityScores = scores.filter(score => score > 50);
  return priorityScores.sort(highestFirst);
};

const heavyManifest = (packages) => packages.filter(isHeavy).map(describe);

const addWeight = (sum, pkg) => sum + pkg.weightKg;

const totalWeight = (packages) => packages.reduce(addWeight, 0);

const report = (label, packages) => {
  const scores = route(packages);
  const lines = [
    `${label}: ${packages.length} package(s), ${totalWeight(packages).toFixed(1)} kg total`,
    `  priority routes: ${scores.length ? scores.join(' > ') : '(none above 50)'}`,
  ];
  const heavyLines = heavyManifest(packages).map(entry => `  heavy: ${entry}`);
  return lines.concat(heavyLines).join('\n');
};

const main = () => {
  const express = [
    { tracking: 'AX100', zone: 12, weightKg: 4.5, priority: 5 },
    { tracking: 'AX101', zone: 3, weightKg: 26.0, priority: 0 },
    { tracking: 'AX102', zone: 30, weightKg: 22.5, priority: 4 },
    { tracking: 'AX103', zone: 9, weightKg: 1.2, priority: 2 },
    { tracking: 'AX104', zone: 25, weightKg: 18.0, priority: 3 },
  ];
  const regional = [
    { tracking: 'BR200', zone: 4, weightKg: 12.0, priority: 1 },
    { tracking: 'BR201', zone: 7, weightKg: 33.4, priority: 2 },
    { tracking: 'BR202', zone: 60, weightKg: 0.9, priority: 1 },
  ];
  const batches = [
    ['Express hub', express],
    ['Regional hub', regional],
    ['Empty hub', []],
  ];
  batches.forEach(([label, packages]) => console.log(report(label, packages)));

  const broken = [{ tracking: 'CX300', zone: 'far', weightKg: 5, priority: 2 }];
  try {
    route(broken);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
};

main();

module.exports = { route, isHeavy, routingScore, heavyManifest, report };

