const PERISHABLE_CATEGORIES = ['dairy', 'produce'];

const daysRemaining = (item) => item.shelfLife - item.daysSinceStocked;

const isHighlyPerishable = (item) => PERISHABLE_CATEGORIES.includes(String(item.category).toLowerCase());

const isValidItem = (item) => {
  if (!item || typeof item !== 'object') return false;
  if (typeof item.name !== 'string' || item.name.trim() === '') return false;
  return Number.isFinite(item.shelfLife) && Number.isFinite(item.daysSinceStocked);
};

const sort = (items) => {
  if (!Array.isArray(items)) {
    throw new TypeError('sort() expects an array of inventory items');
  }
  const clean = items.filter(isValidItem);
  const soonEnough = clean.filter(item => daysRemaining(item) <= 10);
  const remaining = soonEnough.map(daysRemaining);
  const urgent = remaining.filter(days => days < 5);
  return urgent.sort((a, b) => a - b);
};

const describeItem = (item) => {
  const days = daysRemaining(item);
  const flag = isHighlyPerishable(item) ? ' [highly perishable]' : '';
  return `${item.name} (${item.category}): ${days} day(s) left${flag}`;
};

const report = (label, inventory) => {
  const lines = [`=== ${label} ===`];
  inventory.filter(isValidItem).forEach(item => lines.push('  ' + describeItem(item)));
  const skipped = inventory.length - inventory.filter(isValidItem).length;
  if (skipped > 0) {
    lines.push(`  (${skipped} malformed record(s) ignored)`);
  }
  lines.push(`  urgent remaining days: [${sort(inventory).join(', ')}]`);
  return lines.join('\n');
};

const inventories = {
  'Cold case': [
    { name: 'Whole milk', category: 'dairy', shelfLife: 14, daysSinceStocked: 12 },
    { name: 'Cheddar block', category: 'dairy', shelfLife: 60, daysSinceStocked: 5 },
    { name: 'Spinach', category: 'produce', shelfLife: 7, daysSinceStocked: 4 },
    { name: 'Strawberries', category: 'produce', shelfLife: 5, daysSinceStocked: 4 },
  ],
  'Dry goods': [
    { name: 'Rice', category: 'grain', shelfLife: 365, daysSinceStocked: 30 },
    { name: 'Sourdough', category: 'bakery', shelfLife: 6, daysSinceStocked: 3 },
    { name: 'Yogurt', category: 'Dairy', shelfLife: 21, daysSinceStocked: 20 },
  ],
  'Messy feed': [
    { name: 'Kale', category: 'produce', shelfLife: 8, daysSinceStocked: 7 },
    { name: '', category: 'produce', shelfLife: 8, daysSinceStocked: 1 },
    { name: 'Mystery jar', category: 'canned', shelfLife: NaN, daysSinceStocked: 2 },
  ],
};

const main = () => {
  Object.entries(inventories).forEach(([label, inventory]) => {
    console.log(report(label, inventory));
  });
};

main();

module.exports = { sort, daysRemaining, isHighlyPerishable, report };

