const sumPigments = (pigments) => pigments.reduce(addOunces, 0);

const scaleFactor = (gallons) => gallons / REFERENCE_GALLONS;

const roundOunces = (oz) => Math.round(oz * 100) / 100;

const hasBlendableBase = (formula) => formula.pigments.length >= 2;

const requiredOunces = (formula) => {
  const base = sumPigments(formula.pigments);
  return roundOunces(base * scaleFactor(formula.gallons));
};

const mix = (formulas) =>
  formulas
    .filter(hasBlendableBase)
    .map(requiredOunces)
    .filter((oz) => oz < 100)
    .sort((a, b) => a - b);

const describeFormula = (formula) => {
  const pigmentList = formula.pigments.map((oz) => `${oz}oz`).join(' + ');
  return `${formula.color}: ${pigmentList} for ${formula.gallons} gal`;
};

