const priorityScore = (bug) => bug.severity * bug.affectedUsers;

const isDiscussed = (bug) => bug.comments.length > 3;

const isUnresolved = (bug) => bug.severity > 0;

const isHighPriority = (score) => score > 50;

const validateBug = (bug, index) => {
  if (bug === null || typeof bug !== 'object') {
    throw new TypeError(`bug at index ${index} is not an object`);
  }
  if (typeof bug.severity !== 'number' || typeof bug.affectedUsers !== 'number') {
    throw new TypeError(`bug at index ${index} needs numeric severity and affectedUsers`);
  }
  if (!Array.isArray(bug.comments)) {
    throw new TypeError(`bug at index ${index} needs a comments array`);
  }
  return bug;
};

const triage = (bugs) => {
  if (!Array.isArray(bugs)) {
    throw new TypeError('triage expects an array of bugs');
  }
  const checked = bugs.map((bug, index) => validateBug(bug, index));
  const unresolved = checked.filter(isUnresolved);
  const scores = unresolved.map(priorityScore);
  const high = scores.filter(isHighPriority);
  const sorted = high.sort((a, b) => b - a);
  return sorted.reduce((total, score) => total + score, 0);
};

const describeBacklog = (bugs) => {
  const unresolved = bugs.filter(isUnresolved);
  const debated = unresolved.filter(isDiscussed).map((bug) => bug.id);
  return {
    open: unresolved.length,
    debated,
    urgency: triage(bugs)
  };
};

const formatSummary = (label, report) => {
  const debatedList = report.debated.length > 0 ? report.debated.join(', ') : 'none';
  return `${label}: open=${report.open} urgency=${report.urgency} debated=[${debatedList}]`;
};

const runTests = (cases) => {
  cases.forEach(({ label, bugs }) => {
    console.log(formatSummary(label, describeBacklog(bugs)));
  });
};

const makeBug = (id, severity, affectedUsers, commentCount) => ({
  id,
  severity,
  affectedUsers,
  comments: Array.from({ length: commentCount }, (_, i) => `note ${i + 1} on ${id}`)
});

runTests([
  { label: 'empty backlog', bugs: [] },
  {
    label: 'all resolved',
    bugs: [makeBug('B-1', 0, 900, 5), makeBug('B-2', 0, 40, 1)]
  },
  {
    label: 'mixed backlog',
    bugs: [
      makeBug('B-10', 3, 25, 6),
      makeBug('B-11', 1, 10, 2),
      makeBug('B-12', 5, 200, 4),
      makeBug('B-13', 0, 500, 9)
    ]
  },
  {
    label: 'below threshold only',
    bugs: [makeBug('B-20', 2, 20, 1), makeBug('B-21', 1, 49, 0)]
  }
]);

module.exports = { triage, priorityScore, isDiscussed, describeBacklog, formatSummary };

