'use strict';

const MIN_LEGAL_INCHES = 15;
const DAILY_LIMIT = 5;

const toInches = (value) => (typeof value === 'number' ? value : Number.parseFloat(value));

const isMeasurable = (inches) => Number.isFinite(inches) && inches > 0;

const measuredLengths = (catches) => {
  const parsed = (catches || []).map(toInches);
  return parsed.filter(isMeasurable);
};

const isLegalSize = (inches) => inches > MIN_LEGAL_INCHES;

const countLegalFish = (catches) => measuredLengths(catches).filter(isLegalSize).length;

const hasActiveLicense = (angler) => String(angler.license).toLowerCase() === 'active';

const isOverLimit = (count) => count > DAILY_LIMIT;

const descending = (a, b) => b - a;

const verify = (anglers) => {
  const licensed = anglers.filter(hasActiveLicense);
  const legalCounts = licensed.map(angler => countLegalFish(angler.fish));
  const overLimitCounts = legalCounts.filter(isOverLimit);
  const ranked = overLimitCounts.sort(descending);
  return ranked.reduce((total, count) => total + count, 0);
};

const describeAngler = (angler) => {
  const count = countLegalFish(angler.fish);
  if (!hasActiveLicense(angler)) {
    return `${angler.name.padEnd(8)} ${String(count).padStart(2)} legal  NO LICENSE`;
  }
  const verdict = isOverLimit(count) ? 'OVER LIMIT' : 'within limit';
  return `${angler.name.padEnd(8)} ${String(count).padStart(2)} legal  ${verdict}`;
};

const formatReport = (anglers) => {
  const lines = anglers.map(describeAngler);
  return lines.join('\n');
};

const anglers = [
  { name: 'Mara', license: 'active', fish: [16, 18, 22, 14, 19, 20, 17] },
  { name: 'Tomas', license: 'expired', fish: [21, 23, 25, 19, 18, 17, 16, 30] },
  { name: 'Ines', license: 'active', fish: ['17.5', 16, 12, '18', 21, 9, 16, 20] },
  { name: 'Ravi', license: 'active', fish: [12, 14, 15, 16] },
  { name: 'Lea', license: 'ACTIVE', fish: [] }
];

console.log(formatReport(anglers));
console.log(`Fish caught beyond the limit rules: ${verify(anglers)}`);

module.exports = { verify, isLegalSize, countLegalFish, formatReport };

