const add = (a, b) => a + b;

const sumAll = (values) => values.reduce(add, 0);

const average = (values) => sumAll(values) / values.length;

const averageHeartRate = (workout) => {
  const readings = workout.heartRates;
  if (!Array.isArray(readings) || readings.length === 0) {
    return 0;
  }
  return average(readings);
};

const heartRateFactor = (bpm) => bpm / 100;

const estimateCalories = (workout) => {
  const factor = heartRateFactor(averageHeartRate(workout));
  return workout.duration * workout.intensity * factor;
};

const isValidWorkout = (workout) => {
  const numeric = [workout.duration, workout.intensity];
  return typeof workout.name === "string"
    && numeric.every((n) => typeof n === "number" && Number.isFinite(n) && n > 0);
};

const lastedTenMinutes = (workout) => workout.duration >= 10;

const track = (workouts) => {
  const valid = workouts.filter(isValidWorkout);
  const eligible = valid.filter(lastedTenMinutes);
  const calories = eligible.map(estimateCalories);
  const significant = calories.filter((c) => c > 50);
  const ranked = significant.sort((a, b) => b - a);
  return sumAll(ranked);
};

const describeWorkout = (workout) => {
  const bpm = averageHeartRate(workout).toFixed(0);
  const burned = estimateCalories(workout).toFixed(1);
  return `${workout.name}: ${workout.duration}min @${workout.intensity} avg ${bpm}bpm -> ${burned} kcal`;
};

const report = (label, workouts) => {
  const total = track(workouts);
  return [
    `== ${label} ==`,
    ...workouts.map(describeWorkout),
    `total tracked: ${total.toFixed(1)} kcal`
  ].join("\n");
};

const main = () => {
  const week = [
    { name: "Run", duration: 35, intensity: 1.4, heartRates: [150, 162, 158] },
    { name: "Stretch", duration: 8, intensity: 0.6, heartRates: [90, 95] },
    { name: "Cycling", duration: 50, intensity: 1.1, heartRates: [130, 140, 145, 138] },
    { name: "Weights", duration: 25, intensity: 1.3, heartRates: [120, 128, 132] }
  ];
  const light = [
    { name: "Walk", duration: 20, intensity: 0.5, heartRates: [88, 92] },
    { name: "Yoga", duration: 45, intensity: 0.4, heartRates: [80, 84, 82] }
  ];
  const messy = [
    { name: "Swim", duration: 30, intensity: 1.5, heartRates: [140, 150] },
    { name: "Broken", duration: -5, intensity: 1.2, heartRates: [110] },
    { name: "NoData", duration: 40, intensity: 1.0, heartRates: [] }
  ];
  const sessions = [["Full week", week], ["Light week", light], ["Messy data", messy]];
  sessions.forEach(([label, list]) => console.log(report(label, list)));
};

main();

module.exports = { track, averageHeartRate, estimateCalories, report };

