  const scored = documents.filter(hasWords).map(doc => completionPercent(doc));
  return scored.filter(isIncomplete).sort((a, b) => a - b);
};

const roundPercent = (percent) => Math.round(percent * 10) / 10;

const formatReport = (label, percentages) => {
  const header = `${label}: ${percentages.length} incomplete document(s)`;
  if (percentages.length === 0) {
    return header;
  }
  const body = percentages.map(p => `${roundPercent(p)}%`).join(', ');
  return `${header}\n  ${body}`;
};

