const isFullTime = (employee) => employee.daysInOffice > 3;

const topZone = (employee) => employee.preferences[0];

const isEngineering = (employee) => employee.department.toLowerCase() === 'engineering';

const isValidEmployee = (employee) => {
  if (!employee || typeof employee !== 'object') return false;
  if (typeof employee.department !== 'string') return false;
  if (!Number.isFinite(employee.daysInOffice)) return false;
  return Array.isArray(employee.preferences) && employee.preferences.every(z => Number.isFinite(z));
};

const normalize = (employees) => {
  if (!Array.isArray(employees)) {
    throw new TypeError('reassign expects an array of employee records');
  }
  return employees.filter(isValidEmployee);
};

function reassign(employees) {
  return normalize(employees)
    .filter(isEngineering)
    .map(topZone)
    .filter(zone => zone > 0)
    .sort((a, b) => a - b);
}

const summarize = (employees) => {
  const engineers = normalize(employees).filter(isEngineering);
  const resident = engineers.filter(isFullTime);
  return {
    engineers: engineers.length,
    fullTime: resident.length,
    fullTimeNames: resident.map(e => e.name || '(unnamed)'),
    zones: reassign(employees),
  };
};

const formatReport = (label, summary) => {
  const zoneList = summary.zones.length ? summary.zones.join(', ') : 'none';
  const names = summary.fullTimeNames.join(', ') || 'none';
  return [
    `--- ${label} ---`,
    `engineers: ${summary.engineers} (full-time in office: ${summary.fullTime})`,
    `full-time engineers: ${names}`,
    `allocated zones: ${zoneList}`,
  ].join('\n');
};

const runTests = (cases) => {
  cases.forEach(({ label, employees }) => {
    console.log(formatReport(label, summarize(employees)));
  });
};

const main = () => {
  runTests([
    {
      label: 'Floor 2 roster',
      employees: [
        { name: 'Ada', department: 'Engineering', daysInOffice: 5, preferences: [4, 7, 1] },
        { name: 'Bo', department: 'Sales', daysInOffice: 4, preferences: [2, 3] },
        { name: 'Cy', department: 'engineering', daysInOffice: 2, preferences: [0, 9] },
        { name: 'Dee', department: 'ENGINEERING', daysInOffice: 4, preferences: [2] },
      ],
    },
    {
      label: 'Contractors',
      employees: [
        { name: 'Eli', department: 'Support', daysInOffice: 1, preferences: [8] },
        { name: 'Fay', department: 'Engineering', daysInOffice: 3, preferences: [-1, 6] },
        { department: 'Engineering', daysInOffice: 'five', preferences: [3] },
      ],
    },
    { label: 'Empty roster', employees: [] },
  ]);
};

main();

module.exports = { reassign, isFullTime, topZone, summarize };

