const isHighSeverity = (severity) => severity > 7;

const countHighSeverity = (reports) => reports.filter(isHighSeverity).length;

const adjustedDifficulty = (trail) =>
  trail.baseRating + countHighSeverity(trail.reports);

const hasReports = (trail) => trail.reports.length > 0;

const validateTrail = (trail) => {
  if (typeof trail.name !== 'string' || trail.name.trim() === '') {
    throw new Error('Each trail needs a name');
  }
  if (!Number.isFinite(trail.baseRating)) {
    throw new Error(`Trail "${trail.name}" has a non-numeric base rating`);
  }
  if (!Array.isArray(trail.reports)) {
    throw new Error(`Trail "${trail.name}" has no report list`);
  }
  trail.reports.forEach((severity) => {
    if (!Number.isInteger(severity) || severity < 1 || severity > 10) {
      throw new Error(`Trail "${trail.name}" has an out-of-range report: ${severity}`);
    }
  });
  return trail;
};

function assess(trails) {
  return trails
    .map(validateTrail)
    .filter(hasReports)
    .map(adjustedDifficulty)
    .filter((score) => score > 10)
    .sort((a, b) => b - a);
}

const formatReport = (label, scores) => {
  const body = scores.length === 0 ? 'no trails of concern' : scores.join(', ');
  return `${label}: ${body}`;
};

function main() {
  const summer = [
    { name: 'Granite Ridge', baseRating: 8, reports: [9, 4, 10, 8] },
    { name: 'Meadow Loop', baseRating: 2, reports: [] },
    { name: 'Cedar Gulch', baseRating: 9, reports: [3, 2] },
    { name: 'Falls Traverse', baseRating: 6, reports: [8, 8, 9, 1, 7] },
  ];
  const winter = [
    { name: 'Ice Bowl', baseRating: 7, reports: [10, 10, 10] },
    { name: 'Nordic Flat', baseRating: 1, reports: [2, 3, 1] },
  ];
  const quiet = [
    { name: 'Visitor Center Path', baseRating: 1, reports: [] },
  ];

  const seasons = [
    ['Summer', summer],
    ['Winter', winter],
    ['Quiet season', quiet],
  ];

  seasons.forEach(([label, trails]) => {
    console.log(formatReport(label, assess(trails)));
  });

  const broken = [{ name: 'Mystery Spur', baseRating: 4, reports: [12] }];
  try {
    assess(broken);
  } catch (err) {
    console.log(`Rejected input: ${err.message}`);
  }
}

main();

module.exports = { assess, countHighSeverity, adjustedDifficulty };

