const MIN_INCLINE = 30;
const SNOW_THRESHOLD = 100;
const FRESH_THRESHOLD = 20;

const isSteepEnough = (slope) => slope.incline >= MIN_INCLINE;

const totalSnow = (slope) => slope.depth + slope.fresh;

const isHighRisk = (slope) => totalSnow(slope) > SNOW_THRESHOLD && slope.fresh > FRESH_THRESHOLD;

const byInclineDesc = (a, b) => b.incline - a.incline;

const uniqueFresh = (slopes) => {
  const seen = [];
  slopes.forEach(slope => {
    if (!seen.includes(slope.fresh)) {
      seen.push(slope.fresh);
    }
  });
  return seen;
};

const evaluate = (slopes) => {
  const eligible = slopes.filter(isSteepEnough);
  const risky = eligible.filter(isHighRisk).sort(byInclineDesc);
  return [risky.map(slope => slope.name), uniqueFresh(eligible)];
};

const parseSlope = (line) => {
  const [name, incline, depth, fresh] = line.split(",").map(part => part.trim());
  return {
    name,
    incline: Number(incline),
    depth: Number(depth),
    fresh: Number(fresh)
  };
};

const validate = (slope) => {
  const numeric = [slope.incline, slope.depth, slope.fresh];
  if (!slope.name || numeric.some(value => !Number.isFinite(value))) {
    throw new Error(`invalid slope record: ${JSON.stringify(slope)}`);
  }
  return slope;
};

const loadSlopes = (lines) => lines.map(parseSlope).map(validate);

const formatReport = ([names, freshValues]) => {
  const describe = (label, values) =>
    `${label}: ${values.length ? values.join(", ") : "(none)"}`;
  return [
    describe("High risk slopes", names),
    describe("Fresh amounts", freshValues)
  ].join("\n");
};

const main = () => {
  const records = loadSlopes([
    "Alpha, 35, 90, 25",
    "Beta, 20, 50, 10",
    "Gamma, 42, 95, 30",
    "Delta, 31, 60, 25",
    "Epsilon, 48, 120, 15"
  ]);
  console.log(formatReport(evaluate(records)));
  console.log(JSON.stringify(evaluate(records)));
};

main();

module.exports = { evaluate, loadSlopes, formatReport };

