const isUnfinished = (batch) => batch.current < batch.target;

const heatingRate = (batch) => batch.current / batch.time;

const degreesRemaining = (batch) => batch.target - batch.current;

const withMetrics = (batch) => ({
  ...batch,
  rate: heatingRate(batch),
  remaining: degreesRemaining(batch),
});

const isTooSlow = (batch) => batch.rate < 5;

const needsBigPush = (batch) => batch.remaining >= 50;

const byOrigin = (a, b) => a.origin.localeCompare(b.origin);

const uniqueTargets = (batches) => {
  const seen = [];
  batches.forEach((batch) => {
    if (!seen.includes(batch.target)) {
      seen.push(batch.target);
    }
  });
  return seen;
};

const validateBatch = (batch) => {
  const numeric = ["target", "current", "time"];
  const bad = numeric.find((key) => typeof batch[key] !== "number" || Number.isNaN(batch[key]));
  if (typeof batch.origin !== "string" || batch.origin.length === 0) {
    throw new TypeError("each batch needs a non-empty origin");
  }
  if (bad) {
    throw new TypeError(`batch ${batch.origin} has an invalid ${bad}`);
  }
  if (batch.time <= 0) {
    throw new RangeError(`batch ${batch.origin} must have a positive time`);
  }
  return batch;
};

const optimize = (batches) => {
  if (!Array.isArray(batches)) {
    throw new TypeError("optimize expects an array of batches");
  }
  const unfinished = batches.map(validateBatch).filter(isUnfinished);
  const slowOrigins = unfinished
    .map(withMetrics)
    .filter(isTooSlow)
    .filter(needsBigPush)
    .sort(byOrigin)
    .map((batch) => batch.origin);
  return [slowOrigins, uniqueTargets(unfinished)];
};

const describe = ([origins, targets]) => {
  const list = origins.length > 0 ? origins.join(", ") : "none";
  const temps = targets.map((target) => `${target}F`).join(" / ");
  return `slow batches: ${list}\nactive targets: ${temps || "none"}`;
};

const roastLog = [
  { origin: "Brazil", target: 200, current: 150, time: 40 },
  { origin: "Kenya", target: 200, current: 200, time: 30 },
  { origin: "Ethiopia", target: 230, current: 120, time: 30 },
  { origin: "Colombia", target: 210, current: 180, time: 20 },
  { origin: "Sumatra", target: 240, current: 100, time: 25 },
];

const report = optimize(roastLog);
console.log(JSON.stringify(report));
console.log(describe(report));

