const MIN_LINES = 10;
const MAX_WORDS = 50;
const FINALIST_THRESHOLD = 0.5;

const isValid = (poem) => poem.lines >= MIN_LINES && poem.words <= MAX_WORDS;

const rhymeScore = (poem) => poem.rhymes.length / poem.lines;

const isFinalist = (poem) => rhymeScore(poem) > FINALIST_THRESHOLD;

const byWordsAscending = (a, b) => a.words - b.words;

const uniqueLineCounts = (poems) => {
  const seen = new Set();
  poems.forEach(poem => seen.add(poem.lines));
  return [...seen];
};

const evaluate = (poems) => {
  const valid = poems.filter(poem => isValid(poem));
  const finalists = valid.filter(isFinalist).sort(byWordsAscending);
  return [finalists.map(poem => poem.title), uniqueLineCounts(valid)];
};

const formatScore = (poem) => rhymeScore(poem).toFixed(2);

const rejectionReason = (poem) => {
  const reasons = [];
  if (poem.lines < MIN_LINES) {
    reasons.push(`only ${poem.lines} lines`);
  }
  if (poem.words > MAX_WORDS) {
    reasons.push(`${poem.words} words`);
  }
  return reasons.join(" and ");
};

const report = (poems) => {
  const [titles, lineCounts] = evaluate(poems);
  const lines = poems.map(poem => {
    if (!isValid(poem)) {
      return `REJECTED ${poem.title}: ${rejectionReason(poem)}`;
