const isProgressive = m => m.velocity > 0;

const withEfficiency = m => ({ ...m, efficiency: m.velocity / m.fuel });

const isSelected = m => m.critical || m.efficiency > 2;

const byFuelAscending = (a, b) => a.fuel - b.fuel;

const uniqueVelocities = maneuvers => {
  const seen = new Set();
  const result = [];
  maneuvers.forEach(m => {
    if (!seen.has(m.velocity)) {
      seen.add(m.velocity);
      result.push(m.velocity);
    }
  });
  return result;
};

const validate = maneuvers => {
  if (!Array.isArray(maneuvers)) {
    throw new TypeError('adjust expects an array of maneuvers');
  }
  return maneuvers.filter(m => m && typeof m.fuel === 'number' && m.fuel > 0);
};

const adjust = maneuvers => {
  const usable = validate(maneuvers);
  const scored = usable.filter(isProgressive).map(withEfficiency);
  const selected = scored.filter(isSelected).sort(byFuelAscending);
  const criticals = scored.filter(m => m.critical);
  return [selected.map(m => m.thruster), uniqueVelocities(criticals)];
};

const formatReport = (thrusters, velocities) => {
  const names = thrusters.length ? thrusters.join(', ') : 'none';
  const deltas = velocities.map(v => `${v} m/s`).join(', ') || 'none';
  return `Selected thrusters: ${names}\nCritical delta-v: ${deltas}`;
};

const plan = [
  { thruster: 'Main', fuel: 10, velocity: 25, critical: true },
  { thruster: 'Retro', fuel: 4, velocity: 3, critical: false },
  { thruster: 'Vernier', fuel: 6, velocity: 0, critical: true },
  { thruster: 'Aux', fuel: 2, velocity: 12, critical: false },
  { thruster: 'Backup', fuel: 8, velocity: 25, critical: true },
  { thruster: 'Trim', fuel: 5, velocity: 4, critical: false }
];

const main = () => {
  const [thrusters, velocities] = adjust(plan);
  console.log(JSON.stringify([thrusters, velocities]));
  console.log(formatReport(thrusters, velocities));

  const fuelBudget = plan
    .filter(m => thrusters.includes(m.thruster))
    .reduce((total, m) => total + m.fuel, 0);
  console.log(`Total fuel for selected maneuvers: ${fuelBudget}`);
};

main();

module.exports = { adjust, formatReport };

