const isActive = (sensor) => sensor.active === true;

const stressFactor = (sensor) => sensor.amplitude * sensor.frequency;

const isOverStressed = (sensor) => stressFactor(sensor) > 100;

const byAmplitudeDesc = (a, b) => b.amplitude - a.amplitude;

const validateSensor = (sensor, index) => {
  if (!sensor || typeof sensor !== "object") {
    throw new TypeError(`sensor at index ${index} is not an object`);
  }
  if (typeof sensor.location !== "string" || sensor.location.length === 0) {
    throw new TypeError(`sensor at index ${index} has no location`);
  }
  if (!Number.isFinite(sensor.amplitude) || !Number.isFinite(sensor.frequency)) {
    throw new TypeError(`sensor "${sensor.location}" has non-numeric readings`);
  }
  return sensor;
};

const uniqueFrequencies = (sensors) => {
  const seen = new Set();
  sensors.forEach(sensor => seen.add(sensor.frequency));
  return [...seen].sort((a, b) => a - b);
};

function monitor(sensors) {
  if (!Array.isArray(sensors)) {
    throw new TypeError("monitor expects an array of sensor objects");
  }
  const active = sensors.map(validateSensor).filter(isActive);
  const flagged = active
    .filter(isOverStressed)
    .sort(byAmplitudeDesc)
    .map(sensor => sensor.location);
  return [flagged, uniqueFrequencies(active)];
}

const formatReading = (sensor) => {
  const factor = stressFactor(sensor).toFixed(1);
  const mark = isOverStressed(sensor) ? "ALERT" : "ok";
  return `${sensor.location.padEnd(12)} amp=${sensor.amplitude} f=${sensor.frequency} stress=${factor} [${mark}]`;
};

const report = (sensors) => {
  const [flaggedLocations, frequencies] = monitor(sensors);
  const lines = sensors.filter(isActive).map(formatReading);
  lines.push(`flagged: ${flaggedLocations.join(", ") || "none"}`);
  lines.push(`active frequencies: ${frequencies.join(", ")}`);
  return lines.join("\n");
};

const field = [
  { location: "Arch", amplitude: 5, frequency: 25, active: true },
  { location: "Deck North", amplitude: 12, frequency: 40, active: true },
  { location: "Deck South", amplitude: 9, frequency: 25, active: true },
  { location: "Pylon West", amplitude: 30, frequency: 60, active: false },
  { location: "Cable A", amplitude: 4, frequency: 18, active: true },
  { location: "Cable B", amplitude: 7, frequency: 40, active: true }
];

console.log(report(field));
console.log(JSON.stringify(monitor(field)));

