const requiredFields = ["photographer", "iso", "aperture", "shutter", "raw"];

const validateEntry = (entry, index) => {
  if (entry === null || typeof entry !== "object") {
    throw new TypeError(`Entry #${index} is not an object`);
  }
  const missing = requiredFields.filter(field => !(field in entry));
  if (missing.length > 0) {
    throw new TypeError(`Entry #${index} is missing: ${missing.join(", ")}`);
  }
  if (entry.shutter === 0) {
    throw new RangeError(`Entry #${index} has a shutter speed of zero`);
  }
  return entry;
};

const isRaw = entry => entry.raw === true;

const exposureValue = entry => entry.iso / entry.shutter;

const isProperlyExposed = entry => exposureValue(entry) >= 100;

const isWideEnough = entry => entry.aperture <= 8;

const byIsoAscending = (a, b) => a.iso - b.iso;

const uniqueApertures = entries => {
  const seen = [];
  entries.forEach(entry => {
    if (!seen.includes(entry.aperture)) {
      seen.push(entry.aperture);
    }
  });
  return seen;
};

const filter = (entries) => {
  const checked = entries.map(validateEntry);
  const finalists = checked
    .filter(isRaw)
    .filter(isProperlyExposed)
    .filter(isWideEnough)
    .sort(byIsoAscending);
  const names = finalists.map(entry => entry.photographer);
  return [names, uniqueApertures(finalists)];
};

const describeEntry = entry => {
  const ev = exposureValue(entry).toFixed(1);
  return `${entry.photographer}: ISO ${entry.iso}, f/${entry.aperture}, EV ${ev}`;
};

const formatReport = ([names, apertures]) => {
  const roster = names.length > 0 ? names.join(", ") : "nobody";
  const glass = apertures.map(a => `f/${a}`).join(" ");
  return `Finalists: ${roster}\nApertures in play: ${glass || "none"}`;
