const MIN_TEMPERATURE = 20;
const CRITICAL_INDEX = 30;

const isValidSurvey = (survey) => {
  if (!survey || typeof survey !== "object") return false;
  const numeric = ["coverage", "bleaching", "temperature"];
  return typeof survey.zone === "string" && numeric.every(key => typeof survey[key] === "number");
};

const healthIndex = (survey) => survey.coverage - 2 * survey.bleaching;

const warmEnough = (survey) => survey.temperature >= MIN_TEMPERATURE;

const uniqueTemperatures = (surveys) => {
  const seen = [];
  surveys.forEach(survey => {
    if (!seen.includes(survey.temperature)) seen.push(survey.temperature);
  });
  return seen;
};

const assess = (surveys) => {
  if (!Array.isArray(surveys)) {
    throw new TypeError("assess expects an array of survey objects");
  }
  const clean = surveys.filter(survey => {
    if (!isValidSurvey(survey)) {
      throw new TypeError(`malformed survey: ${JSON.stringify(survey)}`);
    }
    return warmEnough(survey);
  });
  const critical = clean
    .filter(survey => healthIndex(survey) < CRITICAL_INDEX)
    .sort((a, b) => b.temperature - a.temperature)
    .map(survey => survey.zone);
  return [critical, uniqueTemperatures(clean)];
};

const describeSurvey = (survey) => {
  const index = healthIndex(survey);
  const status = index < CRITICAL_INDEX ? "CRITICAL" : "stable";
  return `${survey.zone.padEnd(10)} ${survey.temperature}C  index=${index}  ${status}`;
};

const report = (surveys) => {
  const [critical, temperatures] = assess(surveys);
  const lines = surveys.filter(warmEnough).map(describeSurvey);
  const discarded = surveys.length - lines.length;
  lines.push(`discarded (below ${MIN_TEMPERATURE}C): ${discarded}`);
  lines.push(`critical zones: ${critical.join(", ") || "none"}`);
  lines.push(`temperatures seen: ${temperatures.join(", ")}`);
  return lines.join("\n");
};

const main = () => {
  const dataset = [
    { zone: "North", coverage: 60, bleaching: 20, temperature: 25 },
    { zone: "Reefline", coverage: 80, bleaching: 10, temperature: 27 },
    { zone: "Shoals", coverage: 45, bleaching: 30, temperature: 31 },
    { zone: "Deepwater", coverage: 70, bleaching: 5, temperature: 18 },
    { zone: "Lagoon", coverage: 50, bleaching: 25, temperature: 27 }
  ];
  console.log(report(dataset));
  console.log(JSON.stringify(assess(dataset)));
};

main();

module.exports = { assess, report, healthIndex };

