const MASS_THRESHOLD = 50;
const ENERGY_THRESHOLD = 10000;

const isValidImpact = (impact) => {
  if (!impact || typeof impact !== 'object') return false;
  const numeric = [impact.mass, impact.velocity, impact.crater];
  return typeof impact.region === 'string' && numeric.every(v => typeof v === 'number' && Number.isFinite(v));
};

const kineticEnergy = (impact) => impact.mass * impact.velocity * impact.velocity;

const byCraterDescending = (a, b) => b.crater - a.crater;

const uniqueMasses = (impacts) => {
  const seen = new Set();
  impacts.forEach(impact => seen.add(impact.mass));
  return [...seen];
};

const track = (impacts) => {
  const heavy = impacts.filter(isValidImpact).filter(impact => impact.mass > MASS_THRESHOLD);
  const significant = heavy
    .filter(impact => kineticEnergy(impact) >= ENERGY_THRESHOLD)
    .slice()
    .sort(byCraterDescending);
  return [significant.map(impact => impact.region), uniqueMasses(heavy)];
};

const formatEnergy = (value) => {
  if (value >= 1e6) return `${(value / 1e6).toFixed(2)} MJ-eq`;
  return `${Math.round(value).toLocaleString('en-US')} J-eq`;
};

const describeImpact = (impact) => {
  const energy = formatEnergy(kineticEnergy(impact));
  return `${impact.region}: crater ${impact.crater} km, mass ${impact.mass}, ${energy}`;
};

const buildReport = (impacts) => {
  const [regions, masses] = track(impacts);
  const lookup = new Map(impacts.filter(isValidImpact).map(impact => [impact.region, impact]));
  const lines = regions.map(region => describeImpact(lookup.get(region)));
  lines.push(`Significant strikes: ${regions.length}`);
  lines.push(`Masses observed above ${MASS_THRESHOLD}: ${masses.join(', ') || 'none'}`);
  return lines.join('\n');
};

