const isAdult = (patient) => patient.age >= 18;

const severity = (patient) => patient.pain + Math.abs(patient.heart - 80);

const isCritical = (patient) => severity(patient) >= 20;

const byAgeThenPain = (a, b) => {
  if (b.age !== a.age) {
    return b.age - a.age;
  }
  return b.pain - a.pain;
};

const validate = (patient, index) => {
  const fields = ["age", "pain", "heart"];
  const missing = fields.filter(key => typeof patient[key] !== "number");
  if (missing.length > 0) {
    throw new TypeError(
      `patient #${index} (${patient.name}) has non-numeric ${missing.join(", ")}`
    );
  }
  return patient;
};

const uniqueAges = (patients) => {
  const seen = [];
  patients.forEach(patient => {
    if (!seen.includes(patient.age)) {
      seen.push(patient.age);
    }
  });
  return seen;
};

const prioritize = (patients) => {
  const adults = patients
    .map(validate)
    .filter(isAdult);
  const names = adults
    .filter(isCritical)
    .sort(byAgeThenPain)
    .map(patient => patient.name);
  return [names, uniqueAges(adults)];
};

const describe = (patient) =>
  `${patient.name} (age ${patient.age}, severity ${severity(patient)})`;

const report = (patients) => {
  const [names, ages] = prioritize(patients);
  const lookup = new Map(patients.map(patient => [patient.name, patient]));
  const header = names.length > 0
    ? `Admission queue (${names.length} patient(s)):`
    : "Admission queue: nobody meets the severity threshold.";
  return [
    header,
    ...names.map(name => `  - ${describe(lookup.get(name))}`),
    `Adult ages seen: ${ages.join(", ")}`
  ].join("\n");
};

const ward = [
  { name: "John", age: 45, pain: 8, heart: 95 },
  { name: "Mia", age: 17, pain: 9, heart: 130 },
  { name: "Rosa", age: 71, pain: 4, heart: 52 },
  { name: "Ahmed", age: 45, pain: 9, heart: 108 },
  { name: "Leo", age: 30, pain: 2, heart: 78 },
  { name: "Greta", age: 71, pain: 7, heart: 99 }
];

console.log(report(ward));

module.exports = { prioritize, severity, report };

