const isUrgent = (lighthouse) => lighthouse.intensity < 80 || priorityMetric(lighthouse) > 5;

const uniqueBatteries = (lighthouses) => {
  const seen = [];
  lighthouses.forEach((lighthouse) => {
    if (!seen.includes(lighthouse.battery)) {
      seen.push(lighthouse.battery);
    }
  });
  return seen;
};

