  const processed = lighthouses.filter(isDue);
  const urgent = processed
    .filter(isUrgent)
    .sort((a, b) => priorityMetric(b) - priorityMetric(a));
  return [urgent.map((lighthouse) => lighthouse.name), uniqueBatteries(processed)];
};

