const isYoungQueen = (hive) => hive.queen <= 24;

const estimatePopulation = (hive) => hive.comb * hive.activity * 100;

const isVulnerable = (hive) => estimatePopulation(hive) < 5000;

const byCombAscending = (a, b) => a.comb - b.comb;

const collectActivities = (hives) => {
  const seen = new Set();
  hives.forEach(hive => seen.add(hive.activity));
  return [...seen];
};

const estimate = (hives) => {
  const considered = hives.filter(isYoungQueen);
  const vulnerable = considered
    .filter(isVulnerable)
    .sort(byCombAscending)
    .map(hive => hive.identifier);
  return [vulnerable, collectActivities(considered)];
};

const describeHive = (hive) => {
  const population = estimatePopulation(hive);
  const status = isVulnerable(hive) ? "vulnerable" : "stable";
  return `${hive.identifier}: ${population} bees (${status})`;
};

const buildReport = (hives) => {
  const [identifiers, activities] = estimate(hives);
  const retired = hives.filter(hive => !isYoungQueen(hive));
  const lines = hives.filter(isYoungQueen).map(describeHive);
  retired.forEach(hive => {
    lines.push(`${hive.identifier}: queen aged ${hive.queen} months, hive excluded`);
  });
  lines.push(`Vulnerable order: ${identifiers.join(" < ") || "none"}`);
  lines.push(`Activity rates seen: ${activities.join(", ") || "none"}`);
  return lines.join("\n");
};

const totalPopulation = (hives) => hives
  .filter(isYoungQueen)
  .reduce((sum, hive) => sum + estimatePopulation(hive), 0);

const main = () => {
  const apiary = [
    { identifier: "A1", comb: 10, activity: 4, queen: 12 },
    { identifier: "B2", comb: 18, activity: 4, queen: 30 },
    { identifier: "C3", comb: 6, activity: 7, queen: 24 },
    { identifier: "D4", comb: 22, activity: 3, queen: 9 },
    { identifier: "E5", comb: 4, activity: 9, queen: 18 },
    { identifier: "F6", comb: 30, activity: 2, queen: 6 }
  ];

  console.log(buildReport(apiary));
  console.log(`Estimated colony strength: ${totalPopulation(apiary)} bees`);
  console.log(JSON.stringify(estimate(apiary)));
  console.log(JSON.stringify(estimate([{ identifier: "A1", comb: 10, activity: 4, queen: 12 }])));
};

main();

module.exports = { estimate, estimatePopulation, buildReport, totalPopulation };

