const MIN_ISSUE_YEAR = 2015;
const MIN_SCORE = 90;

const isConsidered = (visa) => Number.isInteger(visa.issue) && visa.issue >= MIN_ISSUE_YEAR;

const scoreOf = (visa) => visa.duration * (visa.multiple ? 2 : 1);

const isValid = (visa) => scoreOf(visa) >= MIN_SCORE;

const byIssueThenDuration = (a, b) => {
  if (a.issue !== b.issue) {
    return a.issue - b.issue;
  }
  return b.duration - a.duration;
};

const countryCode = (visa) => String(visa.country).trim().toUpperCase();

const uniqueYears = (visas) => {
  const seen = new Set();
  visas.forEach(visa => seen.add(visa.issue));
  return [...seen];
};

const validate = (visas) => {
  const considered = visas.filter(isConsidered);
  const codes = considered
    .filter(isValid)
    .sort(byIssueThenDuration)
    .map(countryCode);
  return [codes, uniqueYears(considered)];
};

const describeVisa = (visa) => `${countryCode(visa)} ${visa.issue}: ${visa.duration}d` +
  `${visa.multiple ? " (multiple)" : ""} -> score ${scoreOf(visa)}`;

const formatReport = (visas) => {
  const [codes, years] = validate(visas);
  const lines = visas.map(describeVisa);
  const sortedYears = [...years].sort((a, b) => a - b);
  lines.push(`Accepted: ${codes.length ? codes.join(", ") : "none"}`);
  lines.push(`Years considered: ${sortedYears.join(", ") || "none"}`);
  return lines.join("\n");
};

const main = () => {
  const applications = [
    { country: "fr", duration: 60, issue: 2018, multiple: true },
    { country: "DE", duration: 30, issue: 2014, multiple: true },
    { country: "JP", duration: 90, issue: 2018, multiple: false },
    { country: "BR", duration: 45, issue: 2016, multiple: true },
    { country: "US", duration: 40, issue: 2020, multiple: false },
    { country: "in", duration: 120, issue: 2016, multiple: false }
  ];
  console.log(formatReport(applications));
  console.log(JSON.stringify(validate(applications)));
};

main();

module.exports = { validate, scoreOf, formatReport };

