const MELT_THRESHOLD = 10000;

const isFiniteNumber = (n) => typeof n === "number" && Number.isFinite(n);

const isValidGlacier = (g) => Boolean(g) && typeof g.name === "string" && [g.surface, g.temperature, g.summer].every(isFiniteNumber);

const isThawing = (glacier) => glacier.temperature >= 0;

const meltVolume = (glacier) => glacier.surface * glacier.temperature * glacier.summer;

const bySurfaceAscending = (a, b) => a.surface - b.surface;

const uniqueTemperatures = (glaciers) => {
  const seen = [];
  glaciers.forEach(g => {
    if (!seen.includes(g.temperature)) seen.push(g.temperature);
  });
  return seen;
};

const estimate = (glaciers) => {
  if (!Array.isArray(glaciers)) throw new TypeError("estimate expects an array of glaciers");
  const invalid = glaciers.find(g => !isValidGlacier(g));
  if (invalid !== undefined) throw new TypeError("malformed glacier record encountered");

  const considered = glaciers.filter(isThawing);
  const rapid = considered
    .filter(g => meltVolume(g) > MELT_THRESHOLD)
    .sort(bySurfaceAscending)
    .map(g => g.name);

  return [rapid, uniqueTemperatures(considered)];
};

const formatVolume = (volume) => `${Math.round(volume).toLocaleString("en-US")} m³`;

const meltReport = (glaciers) => {
  const [rapidNames, temperatures] = estimate(glaciers);
  const lookup = new Map(glaciers.map(g => [g.name, g]));
  const lines = rapidNames.map(name => `  ${name}: ${formatVolume(meltVolume(lookup.get(name)))}`);
  const totalLoss = rapidNames.reduce((sum, name) => sum + meltVolume(lookup.get(name)), 0);
  const tempList = temperatures
    .slice()
    .sort((a, b) => a - b)
    .map(t => `${t}°C`)
    .join(", ");

  return [
    `Rapidly melting glaciers (${rapidNames.length}):`,
    ...(lines.length ? lines : ["  none"]),
    `Combined annual loss: ${formatVolume(totalLoss)}`,
    `Temperature readings considered: ${tempList || "none"}`
  ].join("\n");
};

const main = () => {
  const survey = [
    { name: "Ice", surface: 10, temperature: 2, summer: 600 },
    { name: "Frostspine", surface: 120, temperature: -3, summer: 40 },
    { name: "Bluecrown", surface: 45, temperature: 2, summer: 90 },
    { name: "Hollowfield", surface: 300, temperature: 4, summer: 75 },
    { name: "Whitebay", surface: 8, temperature: 0, summer: 110 }
  ];

  console.log(estimate(survey));
  console.log(meltReport(survey));
};

main();

module.exports = { estimate, meltVolume, meltReport };

