const volume = (m) => m.diameter * m.stem;

const inRange = (v, low, high) => v >= low && v <= high;

const isValid = (m) => {
  if (m === null || typeof m !== 'object') return false;
  const numeric = ['diameter', 'stem'].every(key => typeof m[key] === 'number' && m[key] > 0);
  return typeof m.species === 'string' && m.species.length > 0 && numeric;
};

const byDiameterDesc = (a, b) => b.diameter - a.diameter;

const uniqueStems = (clean) => {
  const seen = new Set();
  clean.forEach(m => seen.add(m.stem));
  return [...seen];
};

const assess = (mushrooms) => {
  if (!Array.isArray(mushrooms)) {
    throw new TypeError('assess expects an array of mushroom objects');
  }
  const bad = mushrooms.findIndex(m => !isValid(m));
  if (bad !== -1) {
    throw new TypeError(`mushroom at index ${bad} is malformed`);
  }
  const clean = mushrooms.filter(isClean);
  const selected = clean
    .filter(m => inRange(volume(m), 20, 100))
    .sort(byDiameterDesc);
  return [selected.map(m => m.species), uniqueStems(clean)];
};

