const tensionIndex = (flight) => flight.string / flight.altitude;

const qualifies = (flight) => flight.altitude > 50 && tensionIndex(flight) < 2;

const isValidFlight = (flight) => {
  if (!flight || typeof flight !== "object") return false;
  const numeric = ["string", "altitude", "wind"];
  return typeof flight.contestant === "string"
    && numeric.every(key => typeof flight[key] === "number" && Number.isFinite(flight[key]))
    && flight.altitude > 0;
};

const byAltitudeDesc = (a, b) => b.altitude - a.altitude;

const uniqueWinds = (flights) => {
  const seen = [];
  flights.forEach(flight => {
    if (!seen.includes(flight.wind)) seen.push(flight.wind);
  });
  return seen;
};

const isRecordable = (flight) => isValidFlight(flight) && isSafe(flight);

const safeFlights = (kites) => kites.filter(isRecordable);

const rankedFlights = (kites) => safeFlights(kites).filter(qualifies).sort(byAltitudeDesc);

const rank = (kites) => {
  if (!Array.isArray(kites)) throw new TypeError("rank expects an array of flights");
  const winners = rankedFlights(kites).map(flight => flight.contestant);
  return [winners, uniqueWinds(safeFlights(kites))];
};

const describeFlight = (flight) => {
  const tension = tensionIndex(flight).toFixed(2);
  return `  ${flight.contestant}: ${flight.altitude}m, tension ${tension}, wind ${flight.wind}`;
};

const report = (kites) => {
  const [contestants, winds] = rank(kites);
  const podium = contestants.map((name, index) => `${index + 1}. ${name}`);
  return [
