const isOlderAudience = (show) => show.age >= 10;

const popularity = (show) => show.booked / show.duration;

const isPopular = (show) => popularity(show) > 1.5;

const byBookedThenDuration = (a, b) => {
  if (b.booked !== a.booked) {
    return b.booked - a.booked;
  }
  return a.duration - b.duration;
};

const normalize = (show) => ({
  topic: String(show.topic),
  duration: Number(show.duration),
  age: Number(show.age),
  booked: Number(show.booked)
});

const isValidShow = (show) => {
  if (!show || typeof show !== 'object') {
    return false;
  }
  const fields = [show.duration, show.age, show.booked];
  return fields.every(value => Number.isFinite(Number(value)) && Number(value) > 0);
};

const uniqueAges = (shows) => {
  const seen = shows.map(show => show.age);
  return [...new Set(seen)];
};

const schedule = (shows) => {
  const valid = (Array.isArray(shows) ? shows : []).filter(isValidShow).map(normalize);
  const older = valid.filter(isOlderAudience);
  const selected = older
    .filter(isPopular)
    .sort(byBookedThenDuration)
    .map(show => show.topic);
  return [selected, uniqueAges(older)];
};

const describe = (show) => `${show.topic} (age ${show.age}, ratio ${popularity(show).toFixed(2)})`;

const report = (shows) => {
  const [topics, ages] = schedule(shows);
  const lines = topics.map((topic, index) => `${index + 1}. ${topic}`);
  const agesLine = ages.sort((a, b) => a - b).join(', ');
  return [`Programs: ${lines.join(' | ') || 'none'}`, `Ages targeted: ${agesLine || 'none'}`];
};

const main = () => {
  const catalogue = [
    { topic: 'Mars', duration: 40, age: 12, booked: 80 },
    { topic: 'Volcanoes', duration: 30, age: 10, booked: 90 },
    { topic: 'Bubbles', duration: 25, age: 6, booked: 70 },
    { topic: 'Quantum', duration: 50, age: 16, booked: 90 },
    { topic: 'Tides', duration: 60, age: 14, booked: 60 },
    { topic: 'Eclipse', duration: 20, age: 12, booked: 90 }
  ];
