const isPlayable = (hand) => hand.bust === false;

const efficiency = (hand) => hand.total / hand.cards;

const qualifies = (hand) => hand.total >= 17 && efficiency(hand) > 5;

const validateHand = (hand, index) => {
  if (!hand || typeof hand !== "object") {
    throw new TypeError(`hand at index ${index} is not an object`);
  }
  if (typeof hand.dealer !== "string" || hand.dealer.length === 0) {
    throw new TypeError(`hand at index ${index} has no dealer name`);
  }
  if (!Number.isFinite(hand.total) || !Number.isInteger(hand.cards) || hand.cards < 1) {
    throw new TypeError(`hand at index ${index} has invalid total/cards`);
  }
  if (typeof hand.bust !== "boolean") {
    throw new TypeError(`hand at index ${index} has a non-boolean bust flag`);
  }
  return hand;
};

const byTotalThenCards = (a, b) => b.total - a.total || a.cards - b.cards;

const uniqueCardCounts = (hands) => {
  const seen = new Set();
  hands.forEach(hand => seen.add(hand.cards));
  return [...seen];
};

function audit(hands) {
  if (!Array.isArray(hands)) {
    throw new TypeError("audit expects an array of hands");
  }
  const clean = hands.map(validateHand).filter(isPlayable);
  const flagged = clean
    .filter(qualifies)
    .sort(byTotalThenCards)
    .map(hand => hand.dealer);
  return [flagged, uniqueCardCounts(clean)];
}

const formatReport = (hands) => {
  const [dealers, counts] = audit(hands);
  const countList = counts.map(n => String(n)).join(", ");
  return [
    `hands submitted: ${hands.length}`,
    `efficient hands: ${dealers.length}`,
    ...dealers.map(name => `  flagged: ${name}`),
    `card counts in play: ${countList || "none"}`
  ].join("\n");
};

const main = () => {
  const table = [
    { dealer: "Sam", total: 18, cards: 3, bust: false },
    { dealer: "Rita", total: 20, cards: 2, bust: false },
