const QUALIFYING_SCORE = 50;

const validateRoutine = (routine) => {
  if (!routine || typeof routine.name !== 'string' || routine.name.trim() === '') {
    throw new Error('every routine needs an athlete name');
  }
  if (!Array.isArray(routine.execution) || routine.execution.length !== 5) {
    throw new Error(`${routine.name} must have exactly five execution scores`);
  }
  const bad = routine.execution.filter(score => !Number.isFinite(score));
  if (bad.length > 0 || !Number.isFinite(routine.difficulty)) {
    throw new Error(`${routine.name} has a non-numeric score`);
  }
  return routine;
};

const dropExtremes = (execution) => {
  const ordered = [...execution].sort((a, b) => a - b);
  return ordered.slice(1, ordered.length - 1);
};

const addScore = (total, score) => total + score;

const sumScores = (scores) => scores.reduce(addScore, 0);

const executionTotal = (execution) => sumScores(dropExtremes(execution));

const finalScore = (routine) => executionTotal(routine.execution) + routine.difficulty;

const qualifies = (routine) => finalScore(routine) >= QUALIFYING_SCORE;

const rank = (routines) => {
  const scored = routines
    .map(validateRoutine)
    .filter(qualifies)
    .map(routine => ({ name: routine.name, score: finalScore(routine) }));
  scored.sort((a, b) => b.score - a.score);
  return scored.map(entry => entry.name);
};

const formatEntry = (routine, place) => {
  const execution = executionTotal(routine.execution).toFixed(2);
  const total = finalScore(routine).toFixed(2);
  const status = qualifies(routine) ? `place ${place}` : 'did not qualify';
  return `${routine.name.padEnd(8)} E ${execution}  D ${routine.difficulty.toFixed(1)}  = ${total}  (${status})`;
};

const buildReport = (routines) => {
  const ranking = rank(routines);
  const placeOf = (name) => ranking.indexOf(name) + 1;
  return routines
    .map(routine => formatEntry(routine, placeOf(routine.name)))
    .join('\n');
};

const main = () => {
