const QUALIFYING_SCORE = 50;

const validateRoutine = function (routine) {
  if (!routine || typeof routine.name !== 'string' || routine.name.trim() === '') {
    throw new Error('every routine needs an athlete name');
  }
  if (!Array.isArray(routine.execution) || routine.execution.length !== 5) {
    throw new Error(`${routine.name} must have exactly five execution scores`);
  }
  const bad = routine.execution.filter(function (score) { return !Number.isFinite(score); });
  if (bad.length > 0 || !Number.isFinite(routine.difficulty)) {
    throw new Error(`${routine.name} has a non-numeric score`);
  }
  return routine;
};

const dropExtremes = function (execution) {
  const ordered = [...execution].sort(function (a, b) { return a - b; });
  return ordered.slice(1, ordered.length - 1);
};

const addScore = function (total, score) { return total + score; };

const sumScores = function (scores) { return scores.reduce(addScore, 0); };

const executionTotal = function (execution) { return sumScores(dropExtremes(execution)); };

const finalScore = function (routine) { return executionTotal(routine.execution) + routine.difficulty; };

const qualifies = function (routine) { return finalScore(routine) >= QUALIFYING_SCORE; };

const rank = function (routines) {
  const scored = routines
    .map(validateRoutine)
    .filter(qualifies)
    .map(function (routine) { return { name: routine.name, score: finalScore(routine) }; });
  scored.sort(function (a, b) { return b.score - a.score; });
  return scored.map(function (entry) { return entry.name; });
};

const formatEntry = function (routine, place) {
  const execution = executionTotal(routine.execution).toFixed(2);
  const total = finalScore(routine).toFixed(2);
  const status = qualifies(routine) ? `place ${place}` : 'did not qualify';
  return `${routine.name.padEnd(8)} E ${execution}  D ${routine.difficulty.toFixed(1)}  = ${total}  (${status})`;
};

const buildReport = function (routines) {
  const ranking = rank(routines);
  const placeOf = function (name) { return ranking.indexOf(name) + 1; };
  return routines
    .map(function (routine) { return formatEntry(routine, placeOf(routine.name)); })
    .join('\n');
};

const main = function () {
  const routines = [
    { name: 'Jane', execution: [8.7, 9.0, 8.8, 8.5, 8.9], difficulty: 24.0 },
    { name: 'Amara', execution: [9.1, 9.3, 9.0, 9.2, 8.8], difficulty: 25.5 },
