const IGNORED_SPECIES = 'Pigeon';

const isIgnored = (sighting) => sighting.species === IGNORED_SPECIES;

const flockSizes = (sightings) => sightings.map(
  s => s.flockSize
);

const average = (numbers) => {
  if (numbers.length === 0) return 0;
  const total = numbers.reduce((sum, n) => sum + n, 0);
  return total / numbers.length;
};

const maxLatitude = (sightings) => sightings.reduce(
  (hi, s) => Math.max(hi, s.latitude),
  -90
);

const isValidSighting = (sighting) => {
  if (!sighting || typeof sighting.species !== 'string' || sighting.species.trim() === '') return false;
  if (!Number.isFinite(sighting.flockSize) || sighting.flockSize <= 0) return false;
  return Number.isFinite(sighting.latitude) && Math.abs(sighting.latitude) <= 90;
};

const parseLine = (line) => {
  const [species, size, lat] = line.split(',').map(field => field.trim());
  return { species, flockSize: Number(size), latitude: Number(lat) };
};

const parseLog = (lines) => lines.map(parseLine).filter(isValidSighting);

const round1 = (value) => Math.round(value * 10) / 10;

function analyze(sightings) {
  const kept = sightings.filter(s => !isIgnored(s));
  if (kept.length === 0) {
    return 'No sightings to report.';
  }
  const avg = average(flockSizes(kept));
  const top = maxLatitude(kept);
  return `Average size ${round1(avg)}, max latitude ${round1(top)}.`;
}

const speciesTally = (sightings) => {
  const counts = new Map();
  sightings.forEach(s => counts.set(s.species, (counts.get(s.species) || 0) + s.flockSize));
  return counts;
};

const formatTally = (counts) => {
  const entries = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  return entries.map(
    ([species, birds]) => `  ${species}: ${birds} birds`
  ).join('\n');
};

const main = () => {
  const log = [
    'Robin, 10, 40',
    'Pigeon, 25, 51.5',
    'Osprey, 2, 58.3',
    'Robin, 6, 44.1',
    'Snowy Owl, 1, 66.7',
    'Pigeon, 40, 48'
  ];
  const sightings = parseLog(log);
  console.log(analyze(sightings));
  const watched = sightings.filter(s => !isIgnored(s));
  console.log('Birds counted by species:');
  console.log(formatTally(speciesTally(watched)));
};

main();

