const PASS_MARK = 60;
const LATE_PENALTY = 10;

const validateProject = (project) => {
  if (!project || typeof project.title !== 'string' || !project.title.trim()) {
    throw new Error('Each project needs a non-empty title');
  }
  if (!Array.isArray(project.scores) || project.scores.length !== 4) {
    throw new Error(`Project "${project.title}" must have four component scores`);
  }
  const invalid = project.scores.filter(s => typeof s !== 'number' || Number.isNaN(s));
  if (invalid.length > 0) {
    throw new Error(`Project "${project.title}" has non-numeric component scores`);
  }
  return project;
};

const averageScores = (scores) => {
  const total = scores.reduce((sum, score) => sum + score, 0);
  return total / scores.length;
};

const applyLatePenalty = (average, isLate) => (isLate ? average - LATE_PENALTY : average);

const isPassing = (score) => score >= PASS_MARK;

const scoreProject = (project) => {
  validateProject(project);
  const average = averageScores(project.scores);
  return {
    title: project.title,
    score: applyLatePenalty(average, Boolean(project.late)),
  };
};

const byScoreDescending = (a, b) => {
  if (b.score !== a.score) {
    return b.score - a.score;
  }
  return a.title.localeCompare(b.title);
};

