const distanceFromCenter = (arrow) => Math.hypot(arrow.horizontal, arrow.vertical);

const arrowToPoints = (distance) => {
  if (distance < 2) return 10;
  if (distance < 5) return 5;
  return 0;
};

const sumPoints = (points) =>
  points.reduce((total, p) => total + p, 0);

const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const normalizeArrow = (arrow, index, archerName) => {
  if (arrow === null || typeof arrow !== 'object') {
    throw new TypeError(`${archerName}: arrow ${index} is not a coordinate object`);
  }
  const { horizontal, vertical } = arrow;
  if (!isFiniteNumber(horizontal) || !isFiniteNumber(vertical)) {
    throw new TypeError(`${archerName}: arrow ${index} has non-numeric coordinates`);
  }
  return { horizontal, vertical };
};

const scoreArcher = (archer) => {
  if (typeof archer.name !== 'string' || archer.name.length === 0) {
    throw new TypeError('every archer needs a non-empty name');
  }
  const coordinates = Array.isArray(archer.coordinates) ? archer.coordinates : [];
  const points = coordinates
    .map((arrow, index) => normalizeArrow(arrow, index, archer.name))
    .map(distanceFromCenter)
    .map(arrowToPoints);
  return { name: archer.name, score: sumPoints(points) };
};

const tally = (archers) => {
  if (!Array.isArray(archers)) {
    throw new TypeError('tally expects an array of archers');
  }
  return archers
    .map(scoreArcher)
    .filter((result) => result.score > 20)
    .map((result) => result.name);
};

const formatScoreboard = (archers) => {
  const rows = archers.map(scoreArcher);
  const widest = rows.reduce((width, row) => Math.max(width, row.name.length), 0);
  return rows
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
    .map((row) => `${row.name.padEnd(widest)}  ${String(row.score).padStart(3)}`)
    .join('\n');
};

const main = () => {
  const archers = [
    {
      name: 'Bob',
      coordinates: [
        { horizontal: 0, vertical: 1 },
        { horizontal: 1, vertical: 1 },
        { horizontal: -2, vertical: 3 },
      ],
    },
    {
      name: 'Alice',
      coordinates: [
        { horizontal: 0, vertical: 0 },
        { horizontal: 1, vertical: -1 },
        { horizontal: 3, vertical: 3 },
        { horizontal: 9, vertical: 2 },
      ],
    },
    {
      name: 'Clara',
      coordinates: [
        { horizontal: 4, vertical: 0 },
        { horizontal: -3, vertical: 3 },
        { horizontal: 6, vertical: 6 },
      ],
    },
  ];

  console.log(formatScoreboard(archers));
  console.log('Winners:', tally(archers).join(', ') || 'none');
};

main();

module.exports = { tally, distanceFromCenter, arrowToPoints, sumPoints, formatScoreboard };

