const isDeepDive = (dive) => dive.depth > 20;

const minutesToHours = (minutes) => minutes / 60;

const siteNames = (dives) =>
  dives.map(dive => dive.site);

const isValidDive = (dive) => {
  if (!dive || typeof dive.site !== 'string' || dive.site.trim() === '') {
    return false;
  }
  return Number.isFinite(dive.depth) && Number.isFinite(dive.duration);
};

const normalizeDive = (dive) => ({
  site: dive.site.trim(),
  depth: dive.depth,
  duration: dive.duration
});

