const MAX_LAP_SECONDS = 60;

const isValidLap = (lap) => typeof lap === 'number' && Number.isFinite(lap) && lap > 0 && lap <= MAX_LAP_SECONDS;

const validLaps = (laps) => {
  if (!Array.isArray(laps)) {
    return [];
  }
  return laps.filter(isValidLap);
};

const minLap = (laps) => laps.reduce(
  (best, lap) => (lap < best ? lap : best),
  Infinity
);

const sumLaps = (laps) => laps.reduce(
  (total, lap) => total + lap,
  0
);

const averageLap = (laps) => sumLaps(laps) / laps.length;

const racerStats = (racer) => {
  const laps = validLaps(racer.laps);
  return {
    name: racer.name,
    laps,
    fastest: minLap(laps),
    average: laps.length > 0 ? averageLap(laps) : NaN
  };
};

const byFastestLap = (a, b) => a.fastest - b.fastest;

const buildStandings = (racers) => racers
  .map(racerStats)
  .filter(stats => stats.laps.length > 0)
  .sort(byFastestLap);

function analyze(racers) {
  return buildStandings(racers).map(stats => stats.name);
}

const formatSeconds = (seconds) => `${seconds.toFixed(3)}s`;

const formatRow = (stats, index) => {
  const position = String(index + 1).padStart(2, ' ');
  const name = stats.name.padEnd(10, ' ');
  const fastest = formatSeconds(stats.fastest);
  return `${position}. ${name} fastest ${fastest}  avg ${formatSeconds(stats.average)}  (${stats.laps.length} laps)`;
};

const hasDiscardedLaps = (racer) => {
  const submitted = Array.isArray(racer.laps) ? racer.laps.length : 0;
  return validLaps(racer.laps).length !== submitted;
};

const report = (racers) => {
  const lines = buildStandings(racers).map(formatRow);
  const excluded = racers
    .filter(hasDiscardedLaps)
    .map(racer => racer.name);
  if (excluded.length > 0) {
    lines.push(`Discarded laps over ${MAX_LAP_SECONDS}s for: ${excluded.join(', ')}`);
  }
  return lines.join('\n');
};

const field = [
  { name: 'Speed', laps: [50, 55, 65] },
  { name: 'Ayrton', laps: [48.5, 47.25, 61] },
  { name: 'Dawdler', laps: [72, 80] },
  { name: 'Nina', laps: [52, 49.75, 49.5, 58] }
];

console.log(report(field));
console.log(`Order: ${analyze(field).join(' > ')}`);

module.exports = { analyze, report, isValidLap, validLaps, minLap, averageLap };

