const EXCLUDED_REGION = 'North';
const QUALIFYING_TOTAL = 80;

const isFromRegion = (wine, region) => wine.region === region;

const totalScore = (wine) => [wine.aroma, wine.taste, wine.finish]
  .reduce((sum, criterion) => sum + criterion, 0);

const qualifies = (scored) => scored.total >= QUALIFYING_TOTAL;

const validate = (wine) => {
  if (typeof wine.label !== 'string' || wine.label.trim() === '') {
    throw new Error('Every wine needs a non-empty label');
  }
  if (typeof wine.region !== 'string' || wine.region.trim() === '') {
    throw new Error(`Wine ${wine.label} is missing a region`);
  }
  ['aroma', 'taste', 'finish'].forEach((criterion) => {
    const value = wine[criterion];
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new Error(`Wine ${wine.label} has an invalid ${criterion} score`);
    }
  });
  return wine;
};

const score = (wine) => ({ label: wine.label, total: totalScore(wine) });

const byTotalDescending = (a, b) => b.total - a.total;

const rank = (wines) => wines
  .map(validate)
  .filter((wine) => !isFromRegion(wine, EXCLUDED_REGION))
  .map(score)
  .filter(qualifies)
  .sort(byTotalDescending)
  .map((scored) => scored.label);

const describe = (wines) => {
  const ranked = rank(wines);
  if (ranked.length === 0) {
    return 'No wines qualified for the final round.';
  }
  const lines = ranked.map((label, index) => `${index + 1}. ${label}`);
  return `Qualifying wines (${ranked.length}):\n${lines.join('\n')}`;
};

const main = () => {
  const tasting = [
    { label: 'Red', region: 'West', aroma: 30, taste: 30, finish: 30 },
    { label: 'Amber', region: 'West', aroma: 25, taste: 24, finish: 20 },
    { label: 'Slate', region: 'North', aroma: 33, taste: 34, finish: 32 },
    { label: 'Dune', region: 'East', aroma: 20, taste: 19, finish: 18 },
    { label: 'Cinder', region: 'South', aroma: 28, taste: 29, finish: 30 }
  ];

  console.log(describe(tasting));

  const rejected = tasting
    .filter((wine) => isFromRegion(wine, EXCLUDED_REGION))
    .map((wine) => `${wine.label} (${totalScore(wine)} pts, excluded region)`);

  if (rejected.length > 0) {
    console.log(`Excluded: ${rejected.join(', ')}`);
  }

  try {
    rank([{ label: 'Flawed', region: 'West', aroma: 30, taste: '30', finish: 30 }]);
  } catch (error) {
    console.log(`Validation error: ${error.message}`);
  }
};

main();

