const validateSpeaker = (speaker) => {
  if (typeof speaker.name !== 'string' || speaker.name.trim() === '') {
    throw new Error('每位选手都必须有姓名');
  }
  if (!Array.isArray(speaker.scores) || speaker.scores.length !== 5) {
    throw new Error(`${speaker.name} 必须有恰好五个评分`);
  }
  const bad = speaker.scores.filter(score => typeof score !== 'number' || Number.isNaN(score));
  if (bad.length > 0) {
    throw new Error(`${speaker.name} 的评分中包含非数字`);
  }
  return speaker;
};

const highestOf = (scores) => scores.reduce(
  (best, score) => (score > best ? score : best),
  scores[0]
);

const lowestOf = (scores) => scores.reduce(
  (worst, score) => (score < worst ? score : worst),
  scores[0]
);

const removeOne = (scores, target) => {
  const index = scores.indexOf(target);
  return scores.slice(0, index).concat(scores.slice(index + 1));
};

const trimExtremes = (scores) => {
  const withoutHigh = removeOne(scores, highestOf(scores));
  return removeOne(withoutHigh, lowestOf(withoutHigh));
};

const averageMiddleThree = (scores) => {
  const middle = trimExtremes(scores);
  const total = middle.reduce((sum, score) => sum + score, 0);
  return total / middle.length;
};

const applyNoviceBonus = (average, isNovice) => (isNovice ? average + 0.5 : average);

const scoreSpeaker = (speaker) => {
  validateSpeaker(speaker);
  const average = averageMiddleThree(speaker.scores);
  return { name: speaker.name, points: applyNoviceBonus(average, speaker.novice === true) };
};

const evaluate = (speakers) => {
  const scored = speakers.map(speaker => scoreSpeaker(speaker));
  const qualified = scored.filter(entry => entry.points > 27);
  qualified.sort((a, b) => b.points - a.points);
  return qualified.map(entry => entry.name);
};

const describeRanking = (speakers) => {
  const winners = evaluate(speakers);
  if (winners.length === 0) {
    return '没有选手的平均分超过 27 分';
  }
  const lines = winners.map((name, position) => `${position + 1}. ${name}`);
  return lines.join('\n');
};

