const TIME_PENALTY = 5;
const QUALIFYING_SCORE = 40;

const doubleTaste = (taste) => taste * 2;

const sumScores = (presentation, doubledTaste, texture) => presentation + doubledTaste + texture;

const deductTimePenalty = (score, exceeded) => (exceeded ? score - TIME_PENALTY : score);

const readScore = (baker, field) => {
  const raw = baker[field];
  const value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new TypeError(`Baker "${baker.name}" has an invalid ${field} score: ${raw}`);
  }
  return value;
};

const scoreBaker = (baker) => {
  const presentation = readScore(baker, 'presentation');
  const taste = readScore(baker, 'taste');
  const texture = readScore(baker, 'texture');
  const total = sumScores(presentation, doubleTaste(taste), texture);
  return deductTimePenalty(total, Boolean(baker.exceededTimeLimit));
};

const qualifies = (entry) => entry.score >= QUALIFYING_SCORE;

const byScoreDescending = (a, b) => b.score - a.score;

const judge = (bakers) => {
  if (!Array.isArray(bakers)) {
    throw new TypeError('judge expects an array of bakers');
  }
  return bakers
    .map(baker => ({ name: baker.name, score: scoreBaker(baker) }))
    .filter(qualifies)
    .sort(byScoreDescending)
    .map(entry => entry.name);
};

