const TIME_PENALTY = 5;
const QUALIFYING_SCORE = 40;

const doubleTaste = function (taste) { return taste * 2; };

const sumScores = function (presentation, doubledTaste, texture) { return presentation + doubledTaste + texture; };

const deductTimePenalty = function (score, exceeded) { return (exceeded ? score - TIME_PENALTY : score); };

const readScore = function (baker, field) {
  const raw = baker[field];
  const value = Number(raw);
  if (!Number.isFinite(value)) {
    throw new TypeError(`Baker "${baker.name}" has an invalid ${field} score: ${raw}`);
  }
  return value;
};

const scoreBaker = function (baker) {
  const presentation = readScore(baker, 'presentation');
  const taste = readScore(baker, 'taste');
  const texture = readScore(baker, 'texture');
  const total = sumScores(presentation, doubleTaste(taste), texture);
  return deductTimePenalty(total, Boolean(baker.exceededTimeLimit));
};

const qualifies = function (entry) { return entry.score >= QUALIFYING_SCORE; };

const byScoreDescending = function (a, b) { return b.score - a.score; };

const judge = function (bakers) {
  if (!Array.isArray(bakers)) {
    throw new TypeError('judge expects an array of bakers');
  }
  return bakers
    .map(function (baker) { return { name: baker.name, score: scoreBaker(baker) }; })
    .filter(qualifies)
    .sort(byScoreDescending)
    .map(function (entry) { return entry.name; });
};

const scoreboard = function (bakers) { return bakers
  .map(function (baker) { return `${baker.name}: ${scoreBaker(baker)}`; })
  .join('\n'); };

const announceWinners = function (names) {
  if (names.length === 0) {
    return 'No baker reached the qualifying score.';
  }
  return names
    .map(function (name, index) { return `${index + 1}. ${name}`; })
    .join('\n');
};

