const addScore = (total, score) => total + score;

const sumOpponents = (scores) => scores.reduce(addScore, 0);

const withTiebreak = (player) => ({
  name: player.name,
  score: player.score,
  tiebreak: sumOpponents(player.opponents)
});

const isQualified = (player) => player.score >= 5;

const byScoreThenTiebreak = (a, b) => {
  if (b.score !== a.score) {
    return b.score - a.score;
  }
  return b.tiebreak - a.tiebreak;
};

const validatePlayer = (player, index) => {
  if (typeof player.name !== 'string' || player.name.length === 0) {
    throw new TypeError(`player at index ${index} has no name`);
  }
  if (!Number.isFinite(player.score)) {
    throw new TypeError(`player ${player.name} has a non-numeric score`);
  }
  if (!Array.isArray(player.opponents) || !player.opponents.every(Number.isFinite)) {
    throw new TypeError(`player ${player.name} has invalid opponent scores`);
  }
  return player;
};

const tiebreak = (players) => {
  if (!Array.isArray(players)) {
    throw new TypeError('players must be an array');
  }
  return players
    .map(validatePlayer)
    .map(withTiebreak)
    .filter(isQualified)
    .sort(byScoreThenTiebreak)
    .map(entry => entry.name);
};

