const TARGET_GENRE = 'drama';
const MIN_MINUTES = 10;
const MAX_MINUTES = 30;

const normalizeTag = (tag) => String(tag).trim().toLowerCase();

const isShortDuration = (duration) =>
  Number.isFinite(duration) && duration > MIN_MINUTES && duration < MAX_MINUTES;

const hasGenre = (tags, genre) => {
  if (!Array.isArray(tags)) return false;
  const wanted = normalizeTag(genre);
  return tags.some((tag) => normalizeTag(tag) === wanted);
};

const titleOf = (film) => String(film.title);

const extractTitles = (films) => films.map(titleOf);

const isWellFormed = (film) =>
  Boolean(film) && typeof film.title === 'string' && typeof film.duration === 'number';

const screen = (films) => {
  if (!Array.isArray(films)) return [];
  const usable = films.filter(isWellFormed);
  const qualifying = usable.filter(
    (film) => isShortDuration(film.duration) && hasGenre(film.tags, TARGET_GENRE)
  );
  return extractTitles(qualifying).sort((a, b) => a.localeCompare(b));
};

const describeRejection = (film) => {
  const reasons = [];
  if (!isShortDuration(film.duration)) reasons.push(`duration ${film.duration} out of range`);
  if (!hasGenre(film.tags, TARGET_GENRE)) reasons.push(`missing "${TARGET_GENRE}" tag`);
  return `${film.title}: ${reasons.join('; ')}`;
};

const buildReport = (films) => {
  const accepted = screen(films);
  const rejected = films
    .filter(isWellFormed)
    .filter((film) => !accepted.includes(film.title))
    .map(describeRejection);
  const lines = [`Accepted (${accepted.length}):`];
  accepted.forEach((title) => lines.push(`  + ${title}`));
  lines.push(`Rejected (${rejected.length}):`);
  rejected.forEach((note) => lines.push(`  - ${note}`));
  return lines.join('\n');
};

