const dropMin = (scores) => {
  if (scores.length <= 1) {
    return scores.slice();
  }
  const lowest = scores.reduce((min, s) => (s < min ? s : min), scores[0]);
  const index = scores.indexOf(lowest);
  return scores.filter((_, i) => i !== index);
};

const average = (scores) => {
  if (scores.length === 0) {
    return 0;
  }
  const total = scores.reduce((sum, s) => sum + s, 0);
  return total / scores.length;
};

const ERROR_PENALTY = 2;

const combine = (technicalAvg, artisticAvg, hadError) => {
  const raw = technicalAvg + artisticAvg;
  return hadError ? raw - ERROR_PENALTY : raw;
};

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const isScoreList = (arr) => {
  return Array.isArray(arr) && arr.every(isNumber);
};

const validate = (routine) => {
  if (typeof routine.name !== 'string' || routine.name.length === 0) {
    throw new Error('routine is missing a team name');
  }
  if (!isScoreList(routine.technical) || !isScoreList(routine.artistic)) {
    throw new Error(`routine for ${routine.name} has invalid scores`);
  }
};

const evaluate = (routine) => {
  validate(routine);
  const technicalAvg = average(dropMin(routine.technical));
  const artisticAvg = average(dropMin(routine.artistic));
  return { name: routine.name, final: combine(technicalAvg, artisticAvg, routine.error) };
};

const score = (routines) => {
  const results = routines.map((routine) => evaluate(routine));
  results.sort((a, b) => b.final - a.final || a.name.localeCompare(b.name));
  return results.map((result) => result.name);
};

