  const ranking = score(routines);
  const finals = new Map(routines.map((routine) => {
    const result = evaluate(routine);
    return [result.name, result.final];
  }));
  const lines = ranking.map((name, i) => `${i + 1}. ${name} — ${finals.get(name).toFixed(2)}`);
  return lines.join('\n');
};

