const sum = (scores) => {
  let total = 0;
  scores.forEach((score) => {
    total += score;
  });
  return total;
};

const average = (scores) => {
  if (scores.length === 0) {
    return 0;
  }
  return sum(scores) / scores.length;
};

const levelOf = (avg) => {
  if (avg > 80) {
    return 'advanced';
  }
  if (avg > 50) {
    return 'intermediate';
  }
  return 'beginner';
};

const validate = (student) => {
  if (typeof student.name !== 'string' || student.name.trim() === '') {
    throw new Error('every student needs a name');
  }
  if (!Array.isArray(student.scores)) {
    throw new Error(`scores for ${student.name} must be an array`);
  }
  const invalid = student.scores.filter(score => typeof score !== 'number' || Number.isNaN(score));
  if (invalid.length > 0) {
    throw new Error(`scores for ${student.name} must all be numbers`);
  }
  return student;
};

const groupByLevel = (students) => {
  const groups = { advanced: [], intermediate: [], beginner: [] };
  students.forEach((student) => {
    const avg = average(validate(student).scores);
    groups[levelOf(avg)].push(student.name);
  });
  return groups;
};

const place = (students) => {
  const groups = groupByLevel(students);
  return [...groups.advanced, ...groups.intermediate];
};

const describe = (student) => {
  const avg = average(student.scores);
  return `${student.name}: ${avg.toFixed(1)} (${levelOf(avg)})`;
};

const report = (students) => {
  const lines = students.map(describe);
  return lines.join('\n');
};

