const PENALTY_PER_OBSTACLE = 5;
const TIME_LIMIT = 100;

const penaltyFor = (missedObstacles) => missedObstacles.length * PENALTY_PER_OBSTACLE;

const totalTime = (pilot) => pilot.baseTime + penaltyFor(pilot.missedObstacles);

const isValidPilot = (pilot) =>
  typeof pilot === 'object' &&
  pilot !== null &&
  typeof pilot.name === 'string' &&
  pilot.name.trim().length > 0 &&
  Number.isFinite(pilot.baseTime) &&
  Array.isArray(pilot.missedObstacles);

const normalize = (pilot) => ({
  name: pilot.name.trim(),
  baseTime: pilot.baseTime,
  missedObstacles: pilot.missedObstacles.slice(),
});

const describeTime = (seconds) => {
  const rounded = Math.round(seconds * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
};

const formatResult = (pilot) =>
  `${pilot.name} finished the course in ${describeTime(pilot.total)} seconds.`;

const scorePilot = (pilot) => {
  const clean = normalize(pilot);
  return {
    name: clean.name,
    penalty: penaltyFor(clean.missedObstacles),
    total: totalTime(clean),
  };
};

const byTotalAscending = (a, b) => a.total - b.total || a.name.localeCompare(b.name);

function process(pilots) {
  if (!Array.isArray(pilots)) {
    throw new TypeError('process expects an array of pilots');
  }
  const invalid = pilots.filter((pilot) => !isValidPilot(pilot));
  if (invalid.length > 0) {
    throw new TypeError(`process received ${invalid.length} malformed pilot record(s)`);
  }
