const PENALTY_PER_OBSTACLE = 5;
const TIME_LIMIT = 100;

const penaltyFor = function (missedObstacles) { return missedObstacles.length * PENALTY_PER_OBSTACLE; };

const totalTime = function (pilot) { return pilot.baseTime + penaltyFor(pilot.missedObstacles); };

const isValidPilot = function (pilot) {
  return typeof pilot === 'object' &&
  pilot !== null &&
  typeof pilot.name === 'string' &&
  pilot.name.trim().length > 0 &&
  Number.isFinite(pilot.baseTime) &&
  Array.isArray(pilot.missedObstacles);
};

const normalize = function (pilot) { return ({
  name: pilot.name.trim(),
  baseTime: pilot.baseTime,
  missedObstacles: pilot.missedObstacles.slice(),
}); };

const describeTime = function (seconds) {
  const rounded = Math.round(seconds * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
};

const formatResult = function (pilot) {
  return `${pilot.name} finished the course in ${describeTime(pilot.total)} seconds.`;
};

const scorePilot = function (pilot) {
  const clean = normalize(pilot);
  return {
    name: clean.name,
    penalty: penaltyFor(clean.missedObstacles),
    total: totalTime(clean),
  };
};

const byTotalAscending = function (a, b) { return a.total - b.total || a.name.localeCompare(b.name); };

