  const valid = filterValid(climber.routes);
  return {
    name: climber.name,
    hardest: valid.length > 0 ? maxOf(valid) : 0,
    average: average(valid),
    count: valid.length
  };
};

const byHardestDescending = (a, b) => {
  if (b.hardest !== a.hardest) return b.hardest - a.hardest;
  return a.name.localeCompare(b.name);
