const HANDICAP_BASE = 200;
const HANDICAP_FACTOR = 0.8;
const QUALIFY_THRESHOLD = 180;

const handicapFor = (historicalAverage) => {
  const raw = HANDICAP_FACTOR * (HANDICAP_BASE - historicalAverage);
  return raw > 0 ? raw : 0;
};

const adjustGames = (games, handicap) => {
  return games.map(score => score + handicap);
};

const averageOf = (values) => {
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const adjustedAverage = (bowler) => {
  const handicap = handicapFor(bowler.historicalAverage);
  return averageOf(adjustGames(bowler.games, handicap));
};

const validateBowler = (bowler) => {
  if (typeof bowler.name !== 'string' || bowler.name.trim() === '') {
    throw new Error('Every bowler needs a name');
  }
  if (!Number.isFinite(bowler.historicalAverage)) {
    throw new Error(`Bad historical average for ${bowler.name}`);
  }
  if (!Array.isArray(bowler.games) || bowler.games.length !== 3) {
    throw new Error(`${bowler.name} must have exactly three recent games`);
  }
  const bad = bowler.games.find(score => !Number.isFinite(score) || score < 0);
  if (bad !== undefined) {
    throw new Error(`Invalid game score ${bad} for ${bowler.name}`);
  }
  return bowler;
};

function calculate(bowlers) {
  return bowlers
    .map(validateBowler)
    .filter(bowler => adjustedAverage(bowler) > QUALIFY_THRESHOLD)
    .map(bowler => bowler.name);
}

const describeBowler = (bowler) => {
  const handicap = handicapFor(bowler.historicalAverage);
  const adjusted = adjustGames(bowler.games, handicap);
  const shown = adjusted.map(score => score.toFixed(1)).join(', ');
  return `${bowler.name}: handicap ${handicap.toFixed(1)}, adjusted [${shown}], average ${averageOf(adjusted).toFixed(1)}`;
};

const report = (bowlers) => {
  const lines = bowlers.map(describeBowler);
  const qualifiers = calculate(bowlers);
  const tail = qualifiers.length > 0 ? qualifiers.join(', ') : 'nobody';
  return lines.concat(`Over ${QUALIFY_THRESHOLD}: ${tail}`).join('\n');
};

const main = () => {
  const league = [
    { name: 'Ron', historicalAverage: 150, games: [150, 160, 170] },
    { name: 'Deb', historicalAverage: 195, games: [120, 130, 125] },
    { name: 'Tia', historicalAverage: 210, games: [185, 190, 178] }
  ];
  console.log(report(league));
};

main();

module.exports = { calculate, handicapFor, adjustGames, averageOf, adjustedAverage, report };

