const TIME_LIMIT = 45;

const isCompleted = (team) => team.completed === true;

const addMinutes = (sum, t) => sum + t;

const totalTime = (team) => team.times.reduce(addMinutes, 0);

const higher = (max, t) => (t > max ? t : max);

const slowestPuzzle = (team) => team.times.reduce(higher, 0);

const isPositiveNumber = (t) => typeof t === 'number' && Number.isFinite(t) && t >= 0;

const isValidTeam = (team) => {
  if (!team || typeof team.name !== 'string' || team.name.trim() === '') return false;
  if (!Array.isArray(team.times) || team.times.length === 0) return false;
  return team.times.every(isPositiveNumber);
};

const summarize = (team) => ({
  name: team.name.trim(),
  total: totalTime(team),
  slowest: slowestPuzzle(team),
});

const analyze = (teams) => {
  if (!Array.isArray(teams)) {
    throw new TypeError('analyze expects an array of teams');
  }

  const invalid = teams.filter(team => !isValidTeam(team));
  if (invalid.length > 0) {
    throw new TypeError(`Malformed team records: ${invalid.length}`);
  }

  return teams
    .filter(isCompleted)
    .map(summarize)
    .filter(entry => entry.total < TIME_LIMIT)
    .sort((a, b) => a.total - b.total)
    .map(entry => entry.name);
};

const formatMinutes = (minutes) => {
  const whole = Math.floor(minutes);
  const seconds = Math.round((minutes - whole) * 60);
  return `${whole}m ${String(seconds).padStart(2, '0')}s`;
};

const report = (teams) => {
  const winners = analyze(teams);
  const lookup = new Map(teams.map(team => [team.name.trim(), team]));
  const lines = winners.map((name, index) => {
    const team = lookup.get(name);
    return `${index + 1}. ${name} — total ${formatMinutes(totalTime(team))}, ` +
      `slowest puzzle ${formatMinutes(slowestPuzzle(team))}`;
  });
  return lines.length > 0 ? lines.join('\n') : 'No team escaped in under 45 minutes.';
};

