const THRESHOLD = 20;

const wordLengths = (words) =>
  words.map(word => word.length);

const addLengths = (sum, length) => sum + length;

const totalScore = (words) => wordLengths(words).reduce(addLengths, 0);

const meetsThreshold = (score) => score >= THRESHOLD;

const cleanWords = (words) => {
  if (!Array.isArray(words)) {
    return [];
  }
  const trimmed = words.map(word => String(word).trim());
  return trimmed.filter(word => word.length > 0);
};

const scoreContestant = (contestant) => ({
  name: String(contestant.name).trim(),
  score: totalScore(cleanWords(contestant.words)),
});

const byScoreDescending = (a, b) => {
  if (b.score !== a.score) {
    return b.score - a.score;
  }
  return a.name.localeCompare(b.name);
};

const qualify = (contestants) => {
  const scored = contestants.map(contestant => scoreContestant(contestant));
  const advancing = scored.filter(entry => meetsThreshold(entry.score));
  advancing.sort(byScoreDescending);
  return advancing.map(entry => entry.name);
};

const describeContestant = (contestant) => {
  const words = cleanWords(contestant.words);
  const breakdown = words.map(word => `${word}(${word.length})`).join(' + ');
  const entry = scoreContestant(contestant);
  const verdict = meetsThreshold(entry.score) ? 'advances' : 'eliminated';
  return `${entry.name}: ${breakdown} = ${entry.score} -> ${verdict}`;
};

const buildReport = (contestants) => {
  const lines = contestants.map(contestant => describeContestant(contestant));
  const winners = qualify(contestants);
  const summary = winners.length > 0
    ? `Advancing: ${winners.join(', ')}`
    : 'Advancing: nobody';
  return lines.concat(summary).join('\n');
};

