const QUALIFYING_LIMIT = 200;
const LEG_COUNT = 4;

const addMinutes = (sum, t) => sum + t;

const totalTime = (times) => times.reduce(addMinutes, 0);

const faster = (best, t) => (t < best ? t : best);

const minLeg = (times) => times.reduce(faster, Infinity);

const qualifies = (team) => totalTime(team.times) < QUALIFYING_LIMIT;

const filterQualifying = (teams) => teams.filter(qualifies);

const isPositiveNumber = (t) => typeof t === 'number' && Number.isFinite(t) && t > 0;

const isValidTeam = (team) => {
  if (!team || typeof team.name !== 'string' || team.name.trim() === '') {
    return false;
  }
  if (!Array.isArray(team.times) || team.times.length !== LEG_COUNT) {
    return false;
  }
  return team.times.every(isPositiveNumber);
};

const formatLeg = (minutes) => {
  const whole = Math.floor(minutes);
  const seconds = Math.round((minutes - whole) * 60);
  if (seconds === 0) {
    return `${whole}`;
  }
  return `${whole}:${String(seconds).padStart(2, '0')}`;
};

const describe = (team) => `${team.name} fastest leg ${formatLeg(minLeg(team.times))}`;

const evaluate = (teams) => {
  if (!Array.isArray(teams)) {
    throw new TypeError('evaluate expects an array of teams');
  }
  const bad = teams.find((team) => !isValidTeam(team));
  if (bad) {
    throw new TypeError(`invalid team entry: ${JSON.stringify(bad)}`);
  }
  return filterQualifying(teams).map(describe);
};

const byTotal = (a, b) => totalTime(a.times) - totalTime(b.times);

const standing = (team) => `${team.name} total ${formatLeg(totalTime(team.times))}`;

const rankByTotal = (teams) => {
  const sorted = [...teams].sort(byTotal);
  return sorted.map(standing);
};

const main = () => {
  const teams = [
    { name: 'Fast', times: [40, 40, 40, 40] },
    { name: 'Steady', times: [52, 49.5, 51, 50] },
    { name: 'Breeze', times: [48, 47, 46.25, 49] },
    { name: 'Slow', times: [60, 58, 61, 59] },
  ];

  evaluate(teams).forEach((line) => console.log(line));
  console.log('--- standings ---');
  rankByTotal(teams).forEach((line) => console.log(line));
};

main();

module.exports = { evaluate, totalTime, minLeg, filterQualifying, rankByTotal };

