const MIN_SEQUENCE = 10;
const MILESTONE = 50;
const REQUIRED_TOTAL = 200;

const validSequences = (sequences) => sequences.filter(
  len => len >= MIN_SEQUENCE
);

const countMilestones = (sequences) => sequences.filter(
  len => len >= MILESTONE
).length;

const sumValid = (sequences) => validSequences(sequences).reduce(
  (total, len) => total + len,
  0
);

const longestRun = (sequences) => sequences.reduce(
  (best, len) => (len > best ? len : best),
  0
);

const normalizeSequences = (sequences) => {
  if (!Array.isArray(sequences)) {
    return [];
  }
  const numbers = sequences.map(
    len => Number(len)
  );
  return numbers.filter(
    len => Number.isFinite(len) && len > 0
  );
};

const profile = (juggler) => {
  const sequences = normalizeSequences(juggler.sequences);
  return {
    name: String(juggler.name).trim(),
    milestones: countMilestones(sequences),
    validCatches: sumValid(sequences),
    longest: longestRun(sequences)
  };
};

const qualifies = (record) => record.milestones >= 1 && record.validCatches > REQUIRED_TOTAL;

const screen = (jugglers) => {
  if (!Array.isArray(jugglers)) {
    throw new TypeError('screen expects an array of jugglers');
  }
  const records = jugglers.map(
    juggler => profile(juggler)
  );
  return records
    .filter(record => record.name.length > 0)
    .filter(qualifies)
    .map(record => record.name)
    .sort((a, b) => a.localeCompare(b));
};

const describe = (juggler) => {
  const record = profile(juggler);
  const verdict = qualifies(record) ? 'ADVANCES' : 'cut';
  return `${record.name}: ${record.validCatches} valid catches, ` +
    `${record.milestones} run(s) of ${MILESTONE}+, longest ${record.longest} — ${verdict}`;
};

const report = (jugglers) => jugglers.map(describe).join('\n');

const roster = [
  { name: 'Jay', sequences: [50, 50, 50, 50, 50] },
  { name: 'Mina', sequences: [60, 9, 8, 200] },
  { name: 'Ozzy', sequences: [49, 49, 49, 49, 49] },
  { name: 'Bea', sequences: [51, 30, 40] },
  { name: 'Cal', sequences: [] }
];

console.log(report(roster));
console.log('Finalists:', screen(roster).join(', '));

module.exports = { screen, validSequences, countMilestones, sumValid, describe, report };

