const FAULT_PENALTY = 3;
const CLEAN_RUN_BONUS = 5;
const TIME_LIMIT = 60;

const countFaults = (dog) => {
  if (!Array.isArray(dog.faults)) {
    return 0;
  }
  return dog.faults.filter(code => typeof code === 'string' && code.trim() !== '').length;
};

const finalTime = (dog) => {
  const faults = countFaults(dog);
  const base = Number(dog.base);
  if (faults === 0) {
    return base - CLEAN_RUN_BONUS;
  }
  return base + faults * FAULT_PENALTY;
};

const qualifies = (dog) => finalTime(dog) <= TIME_LIMIT;

const validate = (dog) => {
  if (!dog || typeof dog.name !== 'string' || dog.name.trim() === '') {
    throw new Error('each dog needs a name');
  }
  if (!Number.isFinite(Number(dog.base))) {
    throw new Error(`invalid base run time for ${dog.name}`);
  }
  return dog;
};

const score = (dogs) => {
  const runs = dogs.map(validate).map(dog => ({
    name: dog.name,
    faults: countFaults(dog),
    time: finalTime(dog)
  }));
  const qualified = runs.filter(run => run.time <= TIME_LIMIT);
  qualified.sort((a, b) => a.time - b.time || a.name.localeCompare(b.name));
  return qualified.map(run => run.name);
};

const describe = (dog) => {
  const faults = countFaults(dog);
  const status = qualifies(dog) ? 'qualified' : 'eliminated';
  return `${dog.name}: ${finalTime(dog).toFixed(1)}s (${faults} faults) - ${status}`;
};

const report = (dogs) => dogs.map(describe).join('\n');

const main = () => {
  const entries = [
    { name: 'Rex', base: 50, faults: ['jump', 'tunnel'] },
    { name: 'Nala', base: 58, faults: [] },
    { name: 'Boomer', base: 55, faults: ['weave', 'jump', 'seesaw'] },
    { name: 'Pip', base: 49, faults: ['tunnel'] }
  ];
  console.log(report(entries));
  console.log('Placings:', score(entries).join(', '));
};

main();

module.exports = { score, countFaults, finalTime, qualifies, report };

