const MIN_DEPTH = 10;
const RISK_THRESHOLD = 5000;

const isDeepEnough = (core) => core.depth >= MIN_DEPTH;

const add = (acc, value) => acc + value;

const average = (values) => values.reduce(add, 0) / values.length;

const summarize = (core) => ({
  year: core.year,
  avgAnomaly: average(core.anomalies),
  carbonRisk: core.carbon * core.depth,
});

const byAnomalyDesc = (a, b) => b.avgAnomaly - a.avgAnomaly;

const findHighRiskYear = (summaries) => {
  const hit = summaries.find(s => s.carbonRisk > RISK_THRESHOLD);
  return hit ? hit.year : null;
};

const isWarming = (summary) => summary.avgAnomaly > 0;

const allPositive = (summaries) => summaries.every(isWarming);

const sumPositiveAnomalies = (cores) =>
  cores
    .flatMap(core => core.anomalies)
    .filter(a => a > 0)
    .reduce(add, 0);

const evaluate = (cores) => {
  const valid = cores.filter(isDeepEnough);
  const summaries = valid.map(summarize).sort(byAnomalyDesc);
  const topYear = summaries.length ? summaries[0].year : null;
  return [
    topYear,
    findHighRiskYear(summaries),
    allPositive(summaries),
    sumPositiveAnomalies(valid),
  ];
};

const formatReport = ([topYear, riskYear, positive, total]) => {
  const lines = [
    `Warmest core year: ${topYear === null ? 'none' : topYear}`,
    `First high-risk year: ${riskYear === null ? 'none' : riskYear}`,
    `All anomalies positive: ${positive}`,
    `Sum of positive anomalies: ${total.toFixed(2)}`,
  ];
  return lines.map(line => `  ${line}`).join('\n');
};

const main = () => {
  const cores = [
    { year: 2000, depth: 20, carbon: 300, anomalies: [2, 4] },
    { year: 1975, depth: 8, carbon: 900, anomalies: [5, 5] },
    { year: 1950, depth: 45, carbon: 150, anomalies: [1.5, -0.5, 2.0] },
    { year: 1920, depth: 60, carbon: 120, anomalies: [0.4, 0.2] },
  ];
  const result = evaluate(cores);
  console.log(`Records kept: ${cores.filter(isDeepEnough).length}`);
  console.log(formatReport(result));
  console.log(`Raw result: [${result.join(', ')}]`);
};

main();

module.exports = { evaluate, summarize, sumPositiveAnomalies, formatReport };

