const isValidLaunch = (balloon) => balloon.launchAltitude >= 0;

const highestReading = (readings) => {
  return readings.reduce((best, pressure) => (pressure > best ? pressure : best), -Infinity);
};

const summarize = (balloon) => {
  return {
    flightId: balloon.flightId,
    maxPressure: highestReading(balloon.pressureReadings),
  };
};

const byPressureDescending = (a, b) => b.maxPressure - a.maxPressure;

const process = (balloons) => {
  const valid = balloons.filter(isValidLaunch);
  const summaries = valid.map(summarize).sort(byPressureDescending);

  const topFlightId = summaries.length > 0 ? summaries[0].flightId : undefined;
  const highPressureFlight = summaries.find((s) => s.maxPressure > 100);
  const hasLowPressure = summaries.some((s) => s.maxPressure < 50);

  const allReadings = valid.flatMap((balloon) => balloon.pressureReadings);
  const significant = allReadings.filter((pressure) => pressure > 20);
  const total = significant.reduce((sum, pressure) => sum + pressure, 0);

  return [
    topFlightId,
    highPressureFlight === undefined ? undefined : highPressureFlight.flightId,
    hasLowPressure,
    total,
  ];
};

const describeResult = ([topFlightId, foundFlightId, hasLowPressure, total]) => {
  const lines = [
    `top flight: ${topFlightId === undefined ? 'none' : topFlightId}`,
    `first above 100 hPa: ${foundFlightId === undefined ? 'none' : foundFlightId}`,
    `any below 50 hPa: ${hasLowPressure ? 'yes' : 'no'}`,
    `sum of readings above 20 hPa: ${total}`,
  ];
  return lines.join('\n');
};

const main = () => {
  const fleet = [
    { flightId: 'Alpha', launchAltitude: 10, pressureReadings: [30, 40] },
    { flightId: 'Bravo', launchAltitude: -5, pressureReadings: [900, 950] },
    { flightId: 'Charlie', launchAltitude: 120, pressureReadings: [18, 105, 60] },
    { flightId: 'Delta', launchAltitude: 0, pressureReadings: [22, 19, 47] },
  ];

  console.log(describeResult(process(fleet)));

  const grounded = fleet.filter((balloon) => !isValidLaunch(balloon));
  grounded.forEach((balloon) => {
    console.log(`skipped ${balloon.flightId}: altitude ${balloon.launchAltitude}`);
  });
};

main();

module.exports = { process, summarize, highestReading, describeResult };

