const isViable = (dish) => dish.initialCount > 0;

const applyGrowth = (count, percent) => count * (1 + percent / 100);

const finalCount = (dish) => dish.growth.reduce(applyGrowth, dish.initialCount);

const summarize = (dish) => ({
  sample: dish.sample,
  finalCount: Math.round(finalCount(dish)),
  initialCount: dish.initialCount,
});

const bySample = (a, b) => a.sample.localeCompare(b.sample);

const average = (values) => {
  if (values.length === 0) return 0;
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const evaluate = (dishes) => {
  const valid = dishes.filter(isViable);
  const results = valid.map(summarize).sort(bySample);

  const firstSample = results.length > 0 ? results[0].sample : null;

  const millionaire = results.find(r => r.finalCount > 1000000);
  const millionaireSample = millionaire ? millionaire.sample : null;

  const allGrew = results.every(r => r.finalCount > r.initialCount);

  const highPercentages = valid
    .flatMap(dish => dish.growth)
    .filter(percent => percent > 10);

  return [firstSample, millionaireSample, allGrew, average(highPercentages)];
};

const formatReport = ([firstSample, millionaireSample, allGrew, avgHigh]) => {
  const lines = [
    `First sample alphabetically: ${firstSample ?? 'none'}`,
    `First above one million: ${millionaireSample ?? 'none'}`,
    `All valid dishes grew: ${allGrew ? 'yes' : 'no'}`,
    `Average high growth: ${avgHigh.toFixed(2)}%`,
  ];
  return lines.join('\n');
};

const parseDish = (line) => {
  const [sample, initial, growth] = line.split('|');
  return {
    sample: sample.trim(),
    initialCount: Number(initial),
    growth: growth.split(',').map(value => Number(value.trim())),
  };
};

