const MIN_TRAFFIC = 500;
const SEVERITY_TARGET = 10000;
const SEVERITY_FLOOR = 1000;
const DEEP_THRESHOLD = 5;

const maxDepth = (depths) =>
  depths.reduce((best, d) => Math.max(best, d), 0);

const isBusyEnough = (report) => report.traffic >= MIN_TRAFFIC;

const summarize = (report) => ({
  street: report.street,
  severity: report.traffic * maxDepth(report.depths)
});

const bySeverityDesc = (a, b) => b.severity - a.severity;

const validateReport = (report, index) => {
  if (typeof report.street !== 'string' || report.street.length === 0) {
    throw new TypeError(`report ${index} is missing a street name`);
  }
  if (!Number.isFinite(report.traffic) || report.traffic < 0) {
    throw new TypeError(`report ${index} has an invalid traffic volume`);
  }
  if (!Array.isArray(report.depths)) {
    throw new TypeError(`report ${index} has no depth measurements`);
  }
  if (report.depths.some(d => !Number.isFinite(d))) {
    throw new TypeError(`report ${index} has invalid depth measurements`);
  }
};

const prioritize = (reports) => {
  reports.forEach(validateReport);
  const valid = reports.filter(isBusyEnough);
  const summaries = valid.map(summarize).sort(bySeverityDesc);
  const worstStreet = summaries.length > 0 ? summaries[0].street : null;
  const urgent = summaries.find(s => s.severity > SEVERITY_TARGET);
  const allAboveFloor = summaries.every(s => s.severity > SEVERITY_FLOOR);
  const deepTotal = valid
    .flatMap(report => report.depths)
    .filter(depth => depth >= DEEP_THRESHOLD)
    .reduce((sum, depth) => sum + depth, 0);
  return [worstStreet, urgent ? urgent.street : null, allAboveFloor, deepTotal];
};

const describe = ([worst, urgent, allAboveFloor, deepTotal]) => [
  `worst street: ${worst ?? 'none'}`,
  `first urgent street: ${urgent ?? 'none'}`,
  `all above ${SEVERITY_FLOOR}: ${allAboveFloor ? 'yes' : 'no'}`,
  `deep measurement total: ${deepTotal} cm`
].join('\n');

const main = () => {
  const reports = [
    { street: 'Maple Ave', traffic: 1200, depths: [3, 7.5, 2] },
    { street: 'Birch Lane', traffic: 420, depths: [12, 9] },
    { street: 'Cedar Blvd', traffic: 3000, depths: [4, 6, 5.5] },
    { street: 'Oak Street', traffic: 800, depths: [1.5, 2] },
    { street: 'Pine Court', traffic: 640, depths: [8, 3, 5] }
  ];
  console.log(describe(prioritize(reports)));
};

main();

module.exports = { prioritize, describe, summarize, maxDepth };

