const MIN_VOLUME = 100;
const ALERT_THRESHOLD = 5;
const SAFE_LIMIT = 10;

const isValidTank = (tank) => tank.volume >= MIN_VOLUME;

const addReading = (total, reading) => total + reading;

const sumReadings = (readings) => readings.reduce(addReading, 0);

const summarize = (tank) => ({ id: tank.id, ammonia: sumReadings(tank.readings) });

const byAmmoniaDesc = (a, b) => b.ammonia - a.ammonia;

const balance = (tanks) => {
  const valid = tanks.filter(isValidTank);
  const summaries = valid.map(summarize).sort(byAmmoniaDesc);

  const highest = summaries.length > 0 ? summaries[0].id : null;

  const flagged = summaries.find(s => s.ammonia > ALERT_THRESHOLD);
  const flaggedId = flagged ? flagged.id : null;

  const allSafe = summaries.every(s => s.ammonia < SAFE_LIMIT);

  const readings = valid.flatMap(tank => tank.readings);
  const product = readings
    .filter(r => r !== 0)
    .reduce((acc, r) => acc * r, 1);

  return [highest, flaggedId, allSafe, product];
};

const formatReport = ([highest, flaggedId, allSafe, product]) => {
  const lines = [
    `Highest ammonia tank: ${highest ?? 'none'}`,
    `First tank above ${ALERT_THRESHOLD} ppm: ${flaggedId ?? 'none'}`,
    `All tanks below ${SAFE_LIMIT} ppm: ${allSafe ? 'yes' : 'no'}`,
    `Product of non-zero readings: ${product}`,
  ];
  return lines.join('\n');
};

const parseTank = (line) => {
  const [id, volume, ...rest] = line.split(',').map(field => field.trim());
  return {
    id,
    volume: Number(volume),
    readings: rest.map(Number),
  };
};

const loadTanks = (text) => text
  .split('\n')
  .map(line => line.trim())
  .filter(line => line.length > 0)
  .map(parseTank);

const main = () => {
  const data = [
    'A1, 220, 1.5, 2, 0, 0.5',
    'B2, 80, 6, 4',
    'C3, 150, 3, 0, 4',
    'D4, 400, 0, 0, 0',
  ].join('\n');

  const tanks = loadTanks(data);
  const invalid = tanks.filter(tank => !isValidTank(tank));

  if (invalid.length > 0) {
    const names = invalid.map(tank => tank.id).join(', ');
    console.log(`Skipping undersized tanks: ${names}`);
  }

  console.log(formatReport(balance(tanks)));
};

main();

module.exports = { balance, loadTanks, formatReport };

