  const viable = generators.filter(isViable);
  const summaries = viable.map(summarize).sort(byEnergyDescending);

  const topSite = summaries.length ? summaries[0].coastalSite : null;

  const powerful = summaries.find(s => s.totalEnergy > ENERGY_THRESHOLD);
  const foundSite = powerful ? powerful.coastalSite : null;

  const hasLowEnergy = summaries.some(s => s.totalEnergy < LOW_ENERGY_LIMIT);

  const highVelocitySum = viable
    .flatMap(g => g.velocities)
    .filter(v => v > HIGH_VELOCITY_CUTOFF)
    .reduce((total, v) => total + v, 0);

  return [topSite, foundSite, hasLowEnergy, highVelocitySum];
};

