const HEALTHY_MIN = 10;
const LONG_BRANCH = 5;

const isMature = (tree) => Number(tree.age) >= MIN_AGE;

const branchesOf = (tree) => (Array.isArray(tree.branches) ? tree.branches : []);

const addLength = (sum, len) => sum + Number(len);

const totalGrowth = (tree) => branchesOf(tree).reduce(addLength, 0);

const summarize = (tree) => ({
  species: tree.species,
  totalGrowth: totalGrowth(tree),
});

const byGrowthDescending = (a, b) => b.totalGrowth - a.totalGrowth;

const average = (values) => {
  if (values.length === 0) return 0;
  return values.reduce(addLength, 0) / values.length;
};

const schedule = (trees) => {
  const valid = trees.filter(isMature);
  const summaries = valid.map(summarize).sort(byGrowthDescending);

  const fastest = summaries.length > 0 ? summaries[0].species : null;
  const found = summaries.find((s) => s.totalGrowth > GROWTH_THRESHOLD);
  const allHealthy = summaries.every((s) => s.totalGrowth >= HEALTHY_MIN);

  const allBranches = valid.flatMap(branchesOf).map(Number);
  const longBranches = allBranches.filter((len) => len > LONG_BRANCH);

  return [fastest, found ? found.species : null, allHealthy, average(longBranches)];
};

const formatLength = (cm) => `${cm.toFixed(1)} cm`;

