  const [fastest, found, allHealthy, avgLong] = result;
  const lines = [
    `Fastest growing species: ${fastest === null ? 'none' : fastest}`,
    `First species above ${GROWTH_THRESHOLD} cm: ${found === null ? 'none' : found}`,
    `All summaries at least ${HEALTHY_MIN} cm: ${allHealthy ? 'yes' : 'no'}`,
    `Average long branch: ${formatLength(avgLong)}`,
  ];
  return lines.join('\n');
};

