const MIN_JEWELS = 17;

const isValidMovement = (movement) =>
  Number.isFinite(movement.jewels) && movement.jewels >= MIN_JEWELS;

const average = (values) =>
  values.length === 0 ? 0 : values.reduce((acc, v) => acc + v, 0) / values.length;

const summarize = (movement) => ({
  serial: movement.serial,
  averageVariation: average(movement.variations),
});

const byAbsoluteVariation = (a, b) =>
  Math.abs(a.averageVariation) - Math.abs(b.averageVariation);

const calibrate = (movements) => {
  const valid = movements.filter(isValidMovement);
  const summaries = valid.map(summarize).sort(byAbsoluteVariation);

  const mostAccurate = summaries.length > 0 ? summaries[0].serial : null;

  const perfect = summaries.find((s) => s.averageVariation === 0);
  const perfectSerial = perfect ? perfect.serial : null;

  const hasDrifter = summaries.some((s) => s.averageVariation > 20);

  const allVariations = valid.flatMap((m) => m.variations);
  const absoluteSum = allVariations
    .filter((v) => v !== 0)
    .reduce((acc, v) => acc + Math.abs(v), 0);

  return [mostAccurate, perfectSerial, hasDrifter, absoluteSum];
};

const formatSerial = (serial) => (serial === null ? 'none' : serial);

const buildReport = ([mostAccurate, perfectSerial, hasDrifter, absoluteSum]) =>
  [
    `Most accurate movement: ${formatSerial(mostAccurate)}`,
    `Perfectly calibrated:   ${formatSerial(perfectSerial)}`,
    `Drift beyond 20s:       ${hasDrifter ? 'yes' : 'no'}`,
    `Total absolute drift:   ${absoluteSum.toFixed(2)}s`,
  ].join('\n');

