const MIN_JEWELS = 17;

const isValidMovement = function (movement) {
  return Number.isFinite(movement.jewels) && movement.jewels >= MIN_JEWELS;
};

const average = function (values) {
  return values.length === 0 ? 0 : values.reduce(function (acc, v) { return acc + v; }, 0) / values.length;
};

const summarize = function (movement) {
  return {
    serial: movement.serial,
    averageVariation: average(movement.variations),
  };
};

const byAbsoluteVariation = function (a, b) {
  return Math.abs(a.averageVariation) - Math.abs(b.averageVariation);
};

const calibrate = function (movements) {
  const valid = movements.filter(isValidMovement);
  const summaries = valid.map(summarize).sort(byAbsoluteVariation);

  const mostAccurate = summaries.length > 0 ? summaries[0].serial : null;

  const perfect = summaries.find(function (s) { return s.averageVariation === 0; });
  const perfectSerial = perfect ? perfect.serial : null;

  const hasDrifter = summaries.some(function (s) { return s.averageVariation > 20; });

  const allVariations = valid.flatMap(function (m) { return m.variations; });
  const absoluteSum = allVariations
    .filter(function (v) { return v !== 0; })
    .reduce(function (acc, v) { return acc + Math.abs(v); }, 0);

  return [mostAccurate, perfectSerial, hasDrifter, absoluteSum];
};

const formatSerial = function (serial) { return (serial === null ? 'none' : serial); };

const buildReport = function ([mostAccurate, perfectSerial, hasDrifter, absoluteSum]) {
  return [
    `Most accurate movement: ${formatSerial(mostAccurate)}`,
    `Perfectly calibrated:   ${formatSerial(perfectSerial)}`,
    `Drift beyond 20s:       ${hasDrifter ? 'yes' : 'no'}`,
    `Total absolute drift:   ${absoluteSum.toFixed(2)}s`,
  ].join('\n');
};

