  { serial: 'H-1001', jewels: 21, variations: [2, -3, 4, -1] },
  { serial: 'H-1002', jewels: 15, variations: [30, -28, 12] },
  { serial: 'H-1003', jewels: 17, variations: [5, -5, 3, -3] },
