const MAX_DEPTH = 20;
const LOW_DENSITY = 5;
const HIGH_DENSITY = 50;

const isShallow = (meadow) => meadow.depth <= MAX_DEPTH;

const minDensity = (counts) =>
  counts.reduce((lowest, count) => Math.min(lowest, count), Infinity);

const summarize = (meadow) => ({
  sector: meadow.sector,
  minDensity: minDensity(meadow.densities)
});

const byMinDensity = (a, b) => a.minDensity - b.minDensity;

const assess = (meadows) => {
  const valid = meadows.filter(isShallow);

  const summaries = valid.map(summarize).sort(byMinDensity);

  const lowestSector = summaries.length > 0 ? summaries[0].sector : null;

  const sparse = summaries.find((summary) => summary.minDensity < LOW_DENSITY);
  const sparseSector = sparse ? sparse.sector : null;

  const allPopulated = summaries.every((summary) => summary.minDensity >= 1);

  const allCounts = valid.flatMap((meadow) => meadow.densities);

  const highTotal = allCounts
    .filter((count) => count > HIGH_DENSITY)
    .reduce((sum, count) => sum + count, 0);

  return [lowestSector, sparseSector, allPopulated, highTotal];
};

const formatReport = ([lowestSector, sparseSector, allPopulated, highTotal]) => {
  const lines = [
    `Lowest density sector: ${lowestSector ?? 'none'}`,
    `First sparse sector: ${sparseSector ?? 'none'}`,
    `All meadows populated: ${allPopulated ? 'yes' : 'no'}`,
    `High density total: ${highTotal}`
  ];
  return lines.join('\n');
};

