const MIN_DURATION = 10;
const HIGH_PITCH_HZ = 2000;
const DIVERSITY_TARGET = 20;

const isValid = (recording) => recording.duration >= MIN_DURATION;

const uniqueFrequencies = (frequencies) => {
  const seen = new Set();
  frequencies.forEach(freq => seen.add(freq));
  return seen;
};

const summarize = (recording) => ({
  region: recording.region,
  uniqueCount: uniqueFrequencies(recording.frequencies).size
});

const byUniqueCountDesc = (a, b) => b.uniqueCount - a.uniqueCount;

const average = (values) => {
  if (values.length === 0) return 0;
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const monitor = (recordings) => {
  const valid = recordings.filter(isValid);
  const summaries = valid.map(summarize).sort(byUniqueCountDesc);

  const mostDiverse = summaries.length > 0 ? summaries[0].region : null;

  const diverseSummary = summaries.find(s => s.uniqueCount > DIVERSITY_TARGET);
  const foundRegion = diverseSummary ? diverseSummary.region : null;

  const hasSilentHabitat = summaries.some(s => s.uniqueCount === 0);

  const allFrequencies = valid.flatMap(recording => recording.frequencies);
  const highPitch = allFrequencies.filter(freq => freq > HIGH_PITCH_HZ);

  return [mostDiverse, foundRegion, hasSilentHabitat, average(highPitch)];
};

const formatReport = ([mostDiverse, foundRegion, hasSilent, avgHighPitch]) => {
  const lines = [
    `Most diverse habitat: ${mostDiverse ?? 'none'}`,
    `First habitat over ${DIVERSITY_TARGET} frequencies: ${foundRegion ?? 'none'}`,
    `Silent habitat detected: ${hasSilent ? 'yes' : 'no'}`,
    `Average high pitch: ${avgHighPitch.toFixed(2)} Hz`
  ];
  return lines.join('\n');
};

const spread = (start, step, count) =>
  Array.from({ length: count }, (_, i) => start + i * step);

const recordings = [
  { region: 'Mangrove', duration: 45, frequencies: spread(1500, 130, 24) },
  { region: 'Alpine Meadow', duration: 8, frequencies: spread(2200, 50, 30) },
  { region: 'Boreal Forest', duration: 22, frequencies: spread(900, 200, 14) },
  { region: 'Salt Flat', duration: 18, frequencies: [] },
  { region: 'Cloud Forest', duration: 31, frequencies: spread(2050, 75, 19) }
];

console.log(formatReport(monitor(recordings)));

module.exports = { monitor, summarize, average, formatReport };

