const MIN_DEPTH = 2;
const HEAVY_THRESHOLD = 100;
const TARGET_FRAGMENT = 10;

const addWeight = (sum, weight) => sum + weight;

const isExcavated = (grid) => grid.depth >= MIN_DEPTH;

const totalWeight = (fragments) => fragments.reduce(addWeight, 0);

const summarize = (grid) => ({
  square: grid.square,
  total: totalWeight(grid.fragments)
});

const byWeightDescending = (a, b) => b.total - a.total;

const isUsableFragment = (weight) => Number.isFinite(weight) && weight > 0;

const normalizeGrid = (grid) => ({
  square: String(grid.square).trim(),
  depth: Number(grid.depth),
  fragments: (grid.fragments || []).map(Number).filter(isUsableFragment)
});

const track = (grids) => {
  const valid = grids.map(normalizeGrid).filter(isExcavated);
  const summaries = valid.map(summarize).sort(byWeightDescending);

  const heaviest = summaries.length > 0 ? summaries[0].square : null;
  const found = summaries.find(s => s.total > HEAVY_THRESHOLD);
  const allPositive = summaries.every(s => s.total > 0);

  const fragments = valid.flatMap(grid => grid.fragments);
  const tenGramTotal = fragments
    .filter(w => w === TARGET_FRAGMENT)
    .reduce(addWeight, 0);

  return [heaviest, found ? found.square : null, allPositive, tenGramTotal];
};

const formatGrams = (grams) => `${grams.toFixed(1)} g`;

const describeDig = ([heaviest, found, allPositive, tenGramTotal]) => [
  `Heaviest square: ${heaviest || 'none'}`,
  `First square over ${HEAVY_THRESHOLD} g: ${found || 'none'}`,
  `All squares productive: ${allPositive ? 'yes' : 'no'}`,
  `Ten-gram fragments total: ${formatGrams(tenGramTotal)}`
].join('\n');

const site = [
  { square: 'A1', depth: 1.4, fragments: [40, 10, 55] },
  { square: 'A2', depth: 2.0, fragments: [10, 10, 12, 9] },
  { square: 'B1', depth: 3.6, fragments: [80, 10, 44, 7] },
  { square: 'B2', depth: 2.8, fragments: [10, 5] },
  { square: 'C1', depth: 4.1, fragments: [60, 61, -3] }
];

const main = () => {
  const report = track(site);
  console.log(describeDig(report));
  const deepSquares = site.map(normalizeGrid).filter(isExcavated).map(g => g.square);
  console.log(`Squares excavated to ${MIN_DEPTH} m or more: ${deepSquares.join(', ')}`);
};

main();

