const MIN_DIAMETER = 8;
const LOW_PRESSURE_LIMIT = 12;
const HIGH_PRESSURE_LIMIT = 20;
const OPTIMAL_RANGE = [14, 16];

const isUsableTube = (tube) => tube.diameter >= MIN_DIAMETER;

const add = (sum, value) => sum + value;

const average = (values) => values.reduce(add, 0) / values.length;

const summarize = (tube) => ({
  color: tube.color,
  averagePressure: average(tube.pressures),
});

const byAveragePressure = (a, b) => a.averagePressure - b.averagePressure;

const isOptimal = (pressure) => pressure >= OPTIMAL_RANGE[0] && pressure <= OPTIMAL_RANGE[1];

const calculate = (tubes) => {
  const valid = tubes.filter(isUsableTube);
  const summaries = valid.map(summarize).sort(byAveragePressure);

  const lowestPressureColor = summaries.length ? summaries[0].color : null;

  const lowPressureSummary = summaries.find(s => s.averagePressure < LOW_PRESSURE_LIMIT);
  const foundColor = lowPressureSummary ? lowPressureSummary.color : null;

  const hasHighPressure = summaries.some(s => s.averagePressure > HIGH_PRESSURE_LIMIT);

  const allReadings = valid.flatMap(tube => tube.pressures);
  const optimalSum = allReadings.filter(isOptimal).reduce(add, 0);

  return [lowestPressureColor, foundColor, hasHighPressure, optimalSum];
};

const formatPressure = (value) => value.toFixed(2);

const describeTube = (tube) => {
  const readings = tube.pressures.map(formatPressure).join(', ');
  return `${tube.color} (⌀${tube.diameter}mm): ${readings}`;
};

const report = (tubes) => {
  const [lowestColor, foundColor, overpressure, optimalSum] = calculate(tubes);
  const lines = tubes.map(describeTube);
  lines.push(`Lowest average pressure: ${lowestColor ?? 'none'}`);
  lines.push(`First below ${LOW_PRESSURE_LIMIT}: ${foundColor ?? 'none'}`);
  lines.push(`Any above ${HIGH_PRESSURE_LIMIT}: ${overpressure ? 'yes' : 'no'}`);
  lines.push(`Sum of optimal readings: ${formatPressure(optimalSum)}`);
  return lines.join('\n');
};

const main = () => {
  const inventory = [
    { color: 'neon red', diameter: 12, pressures: [14.5, 15.2, 16.0] },
    { color: 'argon blue', diameter: 7.5, pressures: [11.0, 12.4] },
    { color: 'krypton white', diameter: 9, pressures: [10.5, 11.2, 12.1] },
    { color: 'xenon violet', diameter: 15, pressures: [21.4, 22.8, 19.9] },
    { color: 'helium gold', diameter: 8, pressures: [15.5, 14.0, 18.6] },
  ];
  console.log(report(inventory));
};

main();

module.exports = { calculate, report, summarize, average };

