const MIN_HORSE_AGE = 7;
const KNOCKDOWN_FAULTS = 4;
const CLEAR_ROUND_LIMIT = 20;

const isEligible = (round) => round.horseAge >= MIN_HORSE_AGE;

const addFaults = (sum, faults) => sum + faults;

const totalPenalties = (penalties) => penalties.reduce(addFaults, 0);

const summarise = (round) => ({
  rider: round.rider,
  total: totalPenalties(round.penalties),
});

const byTotalAscending = (a, b) => a.total - b.total;

const score = (rounds) => {
  const validRounds = rounds.filter(isEligible);
  const summaries = validRounds.map(summarise).sort(byTotalAscending);

  const winner = summaries.length > 0 ? summaries[0].rider : null;

  const perfect = summaries.find(s => s.total === 0);
  const perfectRider = perfect ? perfect.rider : null;

  const allUnderLimit = summaries.every(s => s.total < CLEAR_ROUND_LIMIT);

  const allPenalties = validRounds.flatMap(round => round.penalties);
  const knockdowns = allPenalties.filter(p => p === KNOCKDOWN_FAULTS);
  const knockdownTotal = totalPenalties(knockdowns);

  return [winner, perfectRider, allUnderLimit, knockdownTotal];
};

const parseRound = (line) => {
  const [rider, age, faults] = line.split('|').map(part => part.trim());
  return {
    rider,
    horseAge: Number(age),
    penalties: faults.length === 0 ? [] : faults.split(',').map(Number),
  };
};

const formatReport = ([winner, perfectRider, allUnderLimit, knockdownTotal]) => {
  const lines = [
    `Winner: ${winner ?? 'none'}`,
    `First clear round: ${perfectRider ?? 'none'}`,
    `All rounds under ${CLEAR_ROUND_LIMIT} faults: ${allUnderLimit ? 'yes' : 'no'}`,
    `Faults from knockdowns: ${knockdownTotal}`,
  ];
  return lines.join('\n');
};

const main = () => {
  const entries = [
    'Ella Novak    | 9  | 4,0,4',
    'Tomas Bergh   | 6  | 0,0,0',
    'Marta Iversen | 11 | 0,0,0',
    'Pia Lindqvist | 8  | 4,4,1,8',
    'Jon Aleksy    | 7  | 0,4,0',
  ];
  const rounds = entries.map(parseRound);
  console.log(formatReport(score(rounds)));
};

main();

