const QUIET_THRESHOLD = 60;
const HIGH_PEAK_FLOOR = 70;

const total = (values) =>
  values.reduce((sum, value) => sum + value, 0);

const average = (values) => total(values) / values.length;

const isMature = (violin) => violin.woodAge >= MIN_WOOD_AGE && violin.peaks.length > 0;

const summarize = (violin) => ({
  maker: violin.maker,
  averagePeak: average(violin.peaks)
});

const byAverageDescending = (a, b) => b.averagePeak - a.averagePeak;

const measure = (violins) => {
  const valid = violins.filter(isMature);
  const summaries = valid.map(summarize).sort(byAverageDescending);

  const loudestMaker = summaries.length > 0 ? summaries[0].maker : null;

  const found = summaries.find((s) => s.averagePeak > LOUD_THRESHOLD);
  const foundMaker = found ? found.maker : null;

  const hasQuiet = summaries.some((s) => s.averagePeak < QUIET_THRESHOLD);

  const allPeaks = valid.flatMap((violin) => violin.peaks);
  const highPeakSum = total(allPeaks.filter((peak) => peak >= HIGH_PEAK_FLOOR));

  return [loudestMaker, foundMaker, hasQuiet, highPeakSum];
};

