const SAFE_THRESHOLD = 200;
const FAST_DRIP = 0.5;

const isMature = (formation) => formation.currentLength >= MIN_LENGTH;

const addRate = (total, rate) => total + rate;

const sumRates = (rates) => rates.reduce(addRate, 0);

const toSummary = (formation) => ({
  chamber: formation.chamber,
  projected: formation.currentLength + sumRates(formation.dripRates)
});

const byProjectedDesc = (a, b) => b.projected - a.projected;

const average = (values) => {
  if (values.length === 0) {
    return 0;
  }
  return sumRates(values) / values.length;
};

const buildSummaries = (formations) => {
  const mature = formations.filter(isMature);
  return mature.map(toSummary).sort(byProjectedDesc);
};

const collectFastRates = (formations) => {
  const allRates = formations.filter(isMature).flatMap((formation) => formation.dripRates);
  return allRates.filter((rate) => rate > FAST_DRIP);
};

function project(formations) {
  const summaries = buildSummaries(formations);
  const longest = summaries.length > 0 ? summaries[0].chamber : null;
  const tall = summaries.find((summary) => summary.projected > TALL_THRESHOLD);
  const allSafe = summaries.every((summary) => summary.projected > SAFE_THRESHOLD);
  const avgFastRate = average(collectFastRates(formations));
  return [longest, tall ? tall.chamber : null, allSafe, avgFastRate];
}

