const COOL_THRESHOLD = 90;
const OPTIMAL_TEMP = 100;

const isCertified = (flight) => flight.volume >= MIN_VOLUME;

const intervalsOf = (flight) => flight.intervals || [];

const temperatureOf = (interval) => interval.temperature;

const temperaturesOf = (flight) => intervalsOf(flight).map(temperatureOf);

const maxTemperature = (flight) => {
  const temps = temperaturesOf(flight);
  return temps.length === 0 ? 0 : temps.reduce((a, b) => Math.max(a, b), -Infinity);
};

const summarize = (flight) => ({
  pilot: flight.pilot,
  maxTemp: maxTemperature(flight)
});

const byTempDescending = (a, b) => b.maxTemp - a.maxTemp;

const evaluate = (flights) => {
  const valid = flights.filter(isCertified);
  const summaries = valid.map(summarize).sort(byTempDescending);

  const hottestPilot = summaries.length > 0 ? summaries[0].pilot : null;

  const found = summaries.find(s => s.maxTemp > HOT_THRESHOLD);
  const foundPilot = found ? found.pilot : null;

  const hasCoolFlight = summaries.some(s => s.maxTemp < COOL_THRESHOLD);

  const allTemps = valid.flatMap(temperaturesOf);
  const optimalSum = allTemps
    .filter(t => t === OPTIMAL_TEMP)
    .reduce((sum, t) => sum + t, 0);

  return [hottestPilot, foundPilot, hasCoolFlight, optimalSum];
};

