const DEEP_SNOW = 8;

const addDepth = (sum, depth) => sum + depth;

const totalVolume = (depths) => depths.reduce(addDepth, 0);

const isValidRoute = (route) => {
  if (!route || typeof route.district !== 'string' || route.district.trim() === '') return false;
  if (!Number.isFinite(route.priority)) return false;
  return Array.isArray(route.depths) && route.depths.every(d => Number.isFinite(d) && d >= 0);
};

const summarize = (route) => ({
  district: route.district,
  volume: totalVolume(route.depths),
});

const byVolumeDesc = (a, b) => b.volume - a.volume;

const clear = (routes) => {
  if (!Array.isArray(routes)) throw new TypeError('routes must be an array');

  const invalid = routes.filter(r => !isValidRoute(r));
  if (invalid.length > 0) throw new TypeError(`${invalid.length} malformed route(s) supplied`);

  const valid = routes.filter(route => route.priority >= MIN_PRIORITY);
  const summaries = valid.map(summarize).sort(byVolumeDesc);

  const heaviest = summaries.length > 0 ? summaries[0].district : null;
  const urgent = summaries.find(s => s.volume > URGENT_VOLUME);
  const allStocked = summaries.every(s => s.volume >= MIN_VOLUME);

  const deepSnowSum = valid
    .flatMap(route => route.depths)
    .filter(depth => depth > DEEP_SNOW)
    .reduce(addDepth, 0);

  return [heaviest, urgent ? urgent.district : null, allStocked, deepSnowSum];
};

const formatReport = ([heaviest, urgentDistrict, allStocked, deepSnowSum]) => {
  const lines = [
    `Heaviest snow district: ${heaviest ?? 'none'}`,
    `First district over ${URGENT_VOLUME} in: ${urgentDistrict ?? 'none'}`,
    `All districts at or above ${MIN_VOLUME} in: ${allStocked ? 'yes' : 'no'}`,
    `Deep snow (> ${DEEP_SNOW} in) total: ${deepSnowSum.toFixed(1)} in`,
  ];
  return lines.map(line => `  ${line}`).join('\n');
};

