const MIN_FINAL_SCORE = 60;

const validate = (performance) => {
  const { name, scores, penalty } = performance;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('each performance needs a band name');
  }
  if (!Array.isArray(scores) || scores.length < 3) {
    throw new TypeError(`${name}: at least three judge scores are required`);
  }
  if (scores.some(score => typeof score !== 'number' || Number.isNaN(score))) {
    throw new TypeError(`${name}: judge scores must be numbers`);
  }
  if (typeof penalty !== 'number' || penalty < 0) {
    throw new TypeError(`${name}: penalty must be a non-negative number`);
  }
};

const dropExtremes = (scores) => {
  const sorted = [...scores].sort((a, b) => a - b);
  return sorted.slice(1, -1);
};

const mean = (values) => {
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
};

const finalScore = (performance) => mean(dropExtremes(performance.scores)) - performance.penalty;

const toEntry = (performance) => ({ name: performance.name, score: finalScore(performance) });

const byScoreDescending = (a, b) => b.score - a.score;

const formatEntry = (entry) => `${entry.name} scored ${entry.score.toFixed(2)}`;

const rank = (performances) => {
  performances.forEach(validate);
  return performances
    .map(toEntry)
    .filter(entry => entry.score >= MIN_FINAL_SCORE)
    .sort(byScoreDescending)
    .map(formatEntry);
};

const addPlacing = (line, index) => `${index + 1}. ${line}`;

const eliminated = (performances) => performances
  .map(toEntry)
  .filter(entry => entry.score < MIN_FINAL_SCORE)
  .map(entry => entry.name);

const main = () => {
  const performances = [
    { name: 'Tigers', scores: [88, 92, 79, 85], penalty: 1 },
    { name: 'Comets', scores: [95, 91, 90, 99], penalty: 4 },
    { name: 'Dragons', scores: [70, 64, 58, 61], penalty: 6 },
    { name: 'Larks', scores: [55, 60, 40, 62], penalty: 3 },
    { name: 'Wolves', scores: [81, 84, 77, 90], penalty: 0 },
  ];

  const ranked = rank(performances);
  ranked
    .map(addPlacing)
    .forEach(line => console.log(line));

  const cut = eliminated(performances);
  if (cut.length > 0) {
    console.log(`Below ${MIN_FINAL_SCORE}: ${cut.join(', ')}`);
  }
};

main();

module.exports = { rank, finalScore, dropExtremes };

