    throw new TypeError(`${name}: judge scores must be numbers`);
  }
  if (typeof penalty !== 'number' || penalty < 0) {
    throw new TypeError(`${name}: penalty must be a non-negative number`);
  }
};

const dropExtremes = function (scores) {
  const sorted = [...scores].sort(function (a, b) { return a - b; });
  return sorted.slice(1, -1);
};

const mean = function (values) {
  const total = values.reduce(function (sum, value) { return sum + value; }, 0);
  return total / values.length;
};

const finalScore = function (performance) { return mean(dropExtremes(performance.scores)) - performance.penalty; };

const toEntry = function (performance) { return { name: performance.name, score: finalScore(performance) }; };

const byScoreDescending = function (a, b) { return b.score - a.score; };

const formatEntry = function (entry) { return `${entry.name} scored ${entry.score.toFixed(2)}`; };

const rank = function (performances) {
  performances.forEach(validate);
  return performances
    .map(toEntry)
    .filter(function (entry) { return entry.score >= MIN_FINAL_SCORE; })
    .sort(byScoreDescending)
    .map(formatEntry);
};

const addPlacing = function (line, index) { return `${index + 1}. ${line}`; };

const eliminated = function (performances) { return performances
  .map(toEntry)
  .filter(function (entry) { return entry.score < MIN_FINAL_SCORE; })
  .map(function (entry) { return entry.name; }); };

const main = function () {
  const performances = [
    { name: 'Tigers', scores: [88, 92, 79, 85], penalty: 1 },
    { name: 'Comets', scores: [95, 91, 90, 99], penalty: 4 },
    { name: 'Dragons', scores: [70, 64, 58, 61], penalty: 6 },
    { name: 'Larks', scores: [55, 60, 40, 62], penalty: 3 },
    { name: 'Wolves', scores: [81, 84, 77, 90], penalty: 0 },
  ];

  const ranked = rank(performances);
  ranked
    .map(addPlacing)
    .forEach(function (line) { return console.log(line); });

  const cut = eliminated(performances);
  if (cut.length > 0) {
    console.log(`Below ${MIN_FINAL_SCORE}: ${cut.join(', ')}`);
  }
};

main();

module.exports = { rank, finalScore, dropExtremes };

