const EARTH_UNIT = 1;

const validate = (recovery) => {
  const fields = ['species', 'originLat', 'originLon', 'recoveryLat', 'recoveryLon'];
  const missing = fields.filter(key => recovery[key] === undefined || recovery[key] === null);
  if (missing.length > 0) {
    throw new Error(`recovery is missing fields: ${missing.join(', ')}`);
  }
  if (typeof recovery.species !== 'string' || recovery.species.trim() === '') {
    throw new Error('species must be a non-empty string');
  }
  return {
    species: recovery.species.trim(),
    originLat: Number(recovery.originLat),
    originLon: Number(recovery.originLon),
    recoveryLat: Number(recovery.recoveryLat),
    recoveryLon: Number(recovery.recoveryLon)
  };
};

const travelDistance = (recovery) => {
  const dLat = Math.abs(recovery.recoveryLat - recovery.originLat);
  const dLon = Math.abs(recovery.recoveryLon - recovery.originLon);
  return (dLat + dLon) * EARTH_UNIT;
};

const isLongDistance = (distance) => distance > 10;

const groupMaxima = (measured) => {
  const maxima = new Map();
  measured.forEach(entry => {
    const current = maxima.get(entry.species);
    if (current === undefined || entry.distance > current) {
      maxima.set(entry.species, entry.distance);
    }
  });
  return maxima;
};

