const PANEL_MIN_YIELD = 500;

const isSouthFacing = (roof) => String(roof.orientation).trim().toLowerCase() === 'south';

const shadeFactor = (roof) => {
  const loss = Number(roof.shadeReduction);
  return (100 - Math.min(Math.max(loss, 0), 100)) / 100;
};

const energyYield = (roof) => Number(roof.usableArea) * Number(roof.tiltFactor) * shadeFactor(roof);

const isWellFormed = (roof) => {
  const numeric = [roof.usableArea, roof.tiltFactor, roof.shadeReduction];
  return Boolean(roof && roof.address) && numeric.every(v => Number.isFinite(Number(v)));
};

const describe = (roof) => `${roof.address} (${Math.round(roof.yield)} units)`;

const evaluate = (roofs) => {
  if (!Array.isArray(roofs)) {
    throw new TypeError('evaluate expects an array of roof records');
  }

  const candidates = roofs
    .filter(isWellFormed)
    .filter(isSouthFacing)
    .map(roof => ({ address: roof.address, yield: energyYield(roof) }))
    .filter(entry => entry.yield >= PANEL_MIN_YIELD)
    .sort((a, b) => a.yield - b.yield);

  return candidates.map(entry => entry.address);
};

const report = (roofs) => {
  const ranked = roofs
    .filter(isWellFormed)
    .filter(isSouthFacing)
    .map(roof => ({ address: roof.address, yield: energyYield(roof) }))
    .filter(entry => entry.yield >= PANEL_MIN_YIELD)
    .sort((a, b) => a.yield - b.yield);

  const total = ranked.reduce((sum, entry) => sum + entry.yield, 0);
  const lines = ranked.map(describe);
  lines.push(`Total estimated output: ${Math.round(total)} units across ${ranked.length} roofs`);
  return lines.join('\n');
};

const neighborhood = [
  { address: '12 Maple St', usableArea: 900, tiltFactor: 0.95, orientation: 'South', shadeReduction: 10 },
  { address: '14 Maple St', usableArea: 400, tiltFactor: 0.85, orientation: 'south', shadeReduction: 5 },
