const CUTOFF_YEAR = 1990;

const isVintage = (item) => item.year <= CUTOFF_YEAR;

const isQualifying = (item) => item.working && isVintage(item);

const normalizeBrand = (brand) => String(brand).trim();

const parseValue = (value) => {
  const numeric = typeof value === "number" ? value : parseFloat(value);
  return Number.isFinite(numeric) ? numeric : 0;
};

const validate = (item) => {
  if (!item || typeof item !== "object") {
    throw new TypeError("each inventory entry must be an object");
  }
  if (!item.brand || !normalizeBrand(item.brand)) {
    throw new TypeError("each inventory entry needs a brand");
  }
  if (!Number.isInteger(item.year)) {
    throw new TypeError(`bad release year for ${item.brand} ${item.model}`);
  }
  return item;
};

const accumulate = (totals, item) => {
  const brand = normalizeBrand(item.brand);
  totals.set(brand, (totals.get(brand) || 0) + parseValue(item.value));
  return totals;
};

function inventory(items) {
  if (!Array.isArray(items)) {
    throw new TypeError("inventory expects an array of items");
  }
  const totals = items
    .map(validate)
    .filter(isQualifying)
    .reduce(accumulate, new Map());

  return [...totals.entries()].sort((a, b) => a[0].localeCompare(b[0]));
}

const formatMoney = (amount) => `$${amount.toFixed(2)}`;

const describeRow = (row) => `${row[0].padEnd(12, ".")} ${formatMoney(row[1])}`;

const report = (items) => {
  const rows = inventory(items);
  const grandTotal = rows.reduce((sum, row) => sum + row[1], 0);
  const lines = rows.map(describeRow);
  lines.push(`${"TOTAL".padEnd(12, ".")} ${formatMoney(grandTotal)}`);
  return lines.join("\n");
};

