const HAZARD_LABEL = 'hazardous waste';
const CONTAMINATION_LIMIT = 15;

const normalizeIncident = (incident) => String(incident).trim().toLowerCase();

const collectIncidents = (route) => {
  const raw = Array.isArray(route.incidents) ? route.incidents : [];
  return raw.map(normalizeIncident).filter(label => label.length > 0);
};

const contaminationPercentage = (route) => {
  const total = Number(route.totalWeight);
  const contaminated = Number(route.contaminatedWeight);
  if (!Number.isFinite(total) || total <= 0) return 0;
  if (!Number.isFinite(contaminated) || contaminated <= 0) return 0;
  return (contaminated / total) * 100;
};

const hasHazard = (incidents) => incidents.includes(HAZARD_LABEL);

const routeId = (route) => {
  const id = route.routeId !== undefined ? route.routeId : route.id;
  return id === undefined ? 'UNKNOWN' : String(id);
};

const audit = (routes) => {
  const source = Array.isArray(routes) ? routes : [];
  const assessed = source.map(route => ({
    routeId: routeId(route),
    contamination: contaminationPercentage(route),
    incidents: collectIncidents(route)
  }));
  const flagged = assessed.filter(entry =>
    entry.contamination > CONTAMINATION_LIMIT || hasHazard(entry.incidents)
  );
  return flagged
    .map(entry => ({ routeId: entry.routeId, contamination: entry.contamination }))
    .sort((a, b) => b.contamination - a.contamination);
};

const formatLine = (entry) => `${entry.routeId.padEnd(10)} ${entry.contamination.toFixed(2)}%`;

const report = (routes) => {
  const flagged = audit(routes);
  if (flagged.length === 0) return 'No routes flagged.';
  const header = `${'ROUTE'.padEnd(10)} CONTAMINATION`;
  return [header, ...flagged.map(formatLine)].join('\n');
};

const fleet = [
  { routeId: 'R-101', totalWeight: 4200, contaminatedWeight: 300, incidents: ['overfill'] },
  { routeId: 'R-102', totalWeight: 3800, contaminatedWeight: 950, incidents: [] },
  { routeId: 'R-103', totalWeight: 5000, contaminatedWeight: 120, incidents: ['Hazardous Waste'] },
  { routeId: 'R-104', totalWeight: 2600, contaminatedWeight: 1300, incidents: ['bin damage'] },
  { routeId: 'R-105', totalWeight: 0, contaminatedWeight: 40, incidents: ['missed pickup'] },
  { routeId: 'R-106', totalWeight: 7100, contaminatedWeight: 1100, incidents: ['  hazardous waste '] }
];

console.log(report(fleet));

const worstRoute = audit(fleet).map(entry => entry.routeId)[0];
console.log(`Priority inspection: ${worstRoute}`);

module.exports = { audit, report, contaminationPercentage };

