const EARTH_RADIUS_KM = 6371;
const MIN_FAST_KW = 50;

const toRadians = degrees => (degrees * Math.PI) / 180;

const distanceKm = (lat1, lon1, lat2, lon2) => {
  const dLat = toRadians(lat2 - lat1);
  const dLon = toRadians(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRadians(lat1)) * Math.cos(toRadians(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(a));
};

const isInService = station => !station.outOfService;

const fastestCharger = station => {
  const speeds = station.chargers || [];
  return speeds.reduce((best, kw) => (kw > best ? kw : best), 0);
};

const isFast = station => fastestCharger(station) >= MIN_FAST_KW;

const describe = (stations, latitude, longitude) =>
  stations.filter(isInService).map(station => ({
    name: station.name,
    peakKw: fastestCharger(station),
    distance: distanceKm(latitude, longitude, station.latitude, station.longitude)
  }));

const locate = (stations, latitude, longitude) => {
  const usable = stations.filter(isInService).filter(isFast);
  const measured = usable.map(station => ({
    name: station.name,
    distance: distanceKm(latitude, longitude, station.latitude, station.longitude)
  }));
  measured.sort((a, b) => a.distance - b.distance);
  return measured.map(entry => entry.name);
};

const formatReport = (stations, latitude, longitude) => {
  const ranked = locate(stations, latitude, longitude);
  const details = describe(stations, latitude, longitude);
  const lookup = new Map(details.map(entry => [entry.name, entry]));
  const lines = ranked.map((name, index) => {
    const entry = lookup.get(name);
    return `${index + 1}. ${name} — ${entry.peakKw} kW, ${entry.distance.toFixed(1)} km`;
  });
  return lines.length ? lines.join('\n') : 'No fast chargers nearby.';
};

