  record !== null &&
  typeof record === 'object' &&
  typeof record.user === 'string' &&
  typeof record.genre === 'string' &&
  Number.isFinite(record.minutes);

const qualifies = (record) => record.completed === true && record.minutes >= MIN_MINUTES;

const normalizeGenre = (genre) => genre.trim().toLowerCase();

const groupMinutesByGenre = (records) => {
  const totals = new Map();
  records.forEach((record) => {
    const key = normalizeGenre(record.genre);
    totals.set(key, (totals.get(key) || 0) + record.minutes);
  });
  return totals;
};

const minutesToHours = (minutes) => Math.round((minutes / 60) * 100) / 100;

