  const valid = checkouts.filter(isValidRecord).filter(qualifies);
  const totals = groupMinutesByGenre(valid);
  const pairs = [...totals.entries()].map(([genre, minutes]) => [genre, minutesToHours(minutes)]);
  return pairs.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
};

