const normalizeName = (name) => String(name ?? '').trim();

const facilityKey = (facility) => String(facility ?? '').trim().toLowerCase();

const countFacilities = (facilities) => {
  const seen = new Set();
  (Array.isArray(facilities) ? facilities : []).forEach(facility => {
    const key = facilityKey(facility);
    if (key) seen.add(key);
  });
  return seen.size;
};

const isQualityPark = (park) => Number(park.acreage) > 5 && Number(park.maintenanceScore) >= 75;

const byFacilityCountDesc = (a, b) => b.facilityCount - a.facilityCount;

const describePark = (park) => ({
  name: normalizeName(park.name),
  facilityCount: countFacilities(park.facilities)
});

const assess = (parks) => {
  const source = Array.isArray(parks) ? parks : [];
  return source
    .filter(park => park && isQualityPark(park))
    .map(describePark)
    .sort(byFacilityCountDesc)
    .map(park => [park.name, park.facilityCount]);
};

const formatRow = (row) => `${row[0].padEnd(24, '.')} ${row[1]} facilities`;

const buildReport = (parks) => {
  const ranked = assess(parks);
  if (ranked.length === 0) return 'No parks met the quality threshold.';
  const lines = ranked.map(formatRow);
  const total = ranked.reduce((sum, row) => sum + row[1], 0);
  lines.push(`Total facilities across ${ranked.length} parks: ${total}`);
  return lines.join('\n');
};

const inventory = [
  { name: 'Riverbend Commons', acreage: 12.5, facilities: ['playground', 'trail', 'Trail', 'picnic area', 'restroom'], maintenanceScore: 88 },
  { name: 'Oakhill Green', acreage: 6, facilities: ['tennis court', 'basketball court'], maintenanceScore: 79 },
