  { name: 'Foundry Yard', acreage: 8.2, facilities: ['skate bowl', 'skate bowl ', 'splash pad'], maintenanceScore: 77 }
];

const main = () => {
  console.log(buildReport(inventory));
  const busiest = assess(inventory).find(row => row[1] >= 5);
  if (busiest) console.log(`Flagship site: ${busiest[0]}`);
};

main();

module.exports = { assess, buildReport, countFacilities };

