const SAFE_PH_MIN = 6.5;
const SAFE_PH_MAX = 8.5;
const CONTAMINANT_LIMIT = 50;

const isValidSample = (sample) => {
  if (!sample || typeof sample !== 'object') return false;
  if (typeof sample.location !== 'string' || sample.location.length === 0) return false;
  if (typeof sample.ph !== 'number' || Number.isNaN(sample.ph)) return false;
  if (!Array.isArray(sample.contaminants)) return false;
  return typeof sample.collectedOn === 'string' && sample.collectedOn.length > 0;
};

const phOutOfRange = (ph) => ph < SAFE_PH_MIN || ph > SAFE_PH_MAX;

const hasExcessContaminant = (contaminants) =>
  contaminants.some(level => level > CONTAMINANT_LIMIT);

const isHazardous = (sample) =>
  phOutOfRange(sample.ph) || hasExcessContaminant(sample.contaminants);

const toTuple = (sample) => [sample.location, sample.collectedOn];

const byDate = (a, b) => {
  if (a[1] < b[1]) return -1;
  if (a[1] > b[1]) return 1;
  return 0;
};

function inspect(samples) {
  if (!Array.isArray(samples)) {
    throw new TypeError('inspect expects an array of samples');
  }
  const invalid = samples.findIndex(sample => !isValidSample(sample));
  if (invalid !== -1) {
    throw new TypeError(`sample at index ${invalid} is malformed`);
  }
  return samples
    .filter(isHazardous)
    .map(toTuple)
    .sort(byDate);
}

const describeReasons = (sample) => {
  const reasons = [];
  if (phOutOfRange(sample.ph)) {
    reasons.push(`pH ${sample.ph.toFixed(1)}`);
  }
  const peaks = sample.contaminants.filter(level => level > CONTAMINANT_LIMIT);
  if (peaks.length > 0) {
    reasons.push(`contaminants ${peaks.join(', ')}`);
  }
  return reasons.join(' / ');
};

const report = (samples) => {
  const reasonByLocation = new Map();
  samples.filter(isHazardous).forEach(sample => {
    reasonByLocation.set(sample.location, describeReasons(sample));
  });
  return inspect(samples)
    .map(([location, date]) => `${date}  ${location}: ${reasonByLocation.get(location)}`)
    .join('\n');
};

const readings = [
  { location: 'Mill Creek', ph: 7.2, contaminants: [12, 4, 30], collectedOn: '2024-03-11' },
  { location: 'Harbor Inlet', ph: 5.9, contaminants: [8, 19], collectedOn: '2024-05-02' },
  { location: 'North Basin', ph: 7.8, contaminants: [51, 3], collectedOn: '2024-01-27' },
  { location: 'Quarry Pond', ph: 9.1, contaminants: [70, 2, 64], collectedOn: '2024-04-18' },
  { location: 'Spring Gap', ph: 8.5, contaminants: [50, 50], collectedOn: '2024-02-09' }
];

console.log(inspect(readings));
console.log(report(readings));

module.exports = { inspect, report, isHazardous };

