const ACCEPTED_CONDITIONS = new Set(['excellent', 'new']);
const PRICE_LIMIT = 60;

const normalize = (value) => String(value ?? '').trim().toLowerCase();

const courseCode = (listing) => String(listing.course ?? '').trim().toUpperCase();

const askingPrice = (listing) => {
  const raw = String(listing.price ?? '').replace(/[$,\s]/g, '');
  return Number(raw);
};

const isQuality = (listing) => ACCEPTED_CONDITIONS.has(normalize(listing.condition));

const isAffordable = (listing) => askingPrice(listing) <= PRICE_LIMIT;

const cheapestByCourse = (listings) =>
  listings.reduce((best, listing) => {
    const code = courseCode(listing);
    const price = askingPrice(listing);
    if (!best.has(code) || price < best.get(code)) {
      best.set(code, price);
    }
    return best;
  }, new Map());

function exchange(listings) {
  const affordable = listings.filter(isQuality).filter(isAffordable);
  const best = cheapestByCourse(affordable);
  return [...best.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([code, price]) => [code, price]);
}

const formatRow = ([code, price]) => `${code.padEnd(10)} $${price.toFixed(2)}`;

const buildReport = (deals) => {
  if (deals.length === 0) {
    return 'No affordable, high quality listings found.';
