const isUnresolved = (report) => report.resolved !== true;

const impactOf = (report) => report.duration * report.users;

const isValidReport = (report) => {
  const fields = ['provider', 'region', 'duration', 'users'];
  const missing = fields.filter(name => report[name] === undefined);
  if (missing.length > 0) {
    throw new Error(`report missing fields: ${missing.join(', ')}`);
  }
  if (typeof report.duration !== 'number' || typeof report.users !== 'number') {
    throw new Error(`report for ${report.region} has non-numeric metrics`);
  }
  return report.duration >= 0 && report.users >= 0;
};

const SEVERITY_THRESHOLD = 10000;

const severeOutages = (reports) => {
  const ongoing = reports.filter(isValidReport).filter(isUnresolved);
  const scored = ongoing.map(report => ({ ...report, impact: impactOf(report) }));
  const severe = scored.filter(entry => entry.impact >= SEVERITY_THRESHOLD);
  return severe.sort((a, b) => b.impact - a.impact);
};

const outages = (reports) => {
  const ranked = severeOutages(reports);
  return ranked.map(entry => entry.region);
};

const formatDuration = (minutes) => {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return hours > 0 ? `${hours}h${String(rest).padStart(2, '0')}m` : `${rest}m`;
};

const formatImpact = (impact) => {
  const millions = impact / 1e6;
  return millions >= 1 ? `${millions.toFixed(2)}M user-minutes`
                       : `${impact.toLocaleString('en-US')} user-minutes`;
};

const describe = (entry, rank) => {
  const parts = [
    `${rank}. ${entry.region} (${entry.provider})`,
    formatDuration(entry.duration),
    `${entry.users} users`,
    formatImpact(entry.impact)
  ];
  return parts.join(' | ');
};

const repairPlan = (reports) => {
  const ranked = severeOutages(reports);
  if (ranked.length === 0) {
    return 'No severe outages: all reports resolved or below threshold.';
  }
  const lines = ranked.map((entry, index) => describe(entry, index + 1));
  const affected = ranked.reduce((sum, entry) => sum + entry.users, 0);
  lines.push(`Total users awaiting repair: ${affected}`);
  return lines.join('\n');
};

const main = () => {
  const reports = [
    { provider: 'Northlink', region: 'Oslo', duration: 45, users: 120, resolved: false },
    { provider: 'Northlink', region: 'Bergen', duration: 300, users: 8400, resolved: false },
    { provider: 'Fibretel', region: 'Lisbon', duration: 20, users: 90000, resolved: true },
    { provider: 'Fibretel', region: 'Porto', duration: 90, users: 1500, resolved: false },
    { provider: 'Meshnet', region: 'Kraków', duration: 600, users: 20, resolved: false }
  ];
  console.log(outages(reports).join(', '));
  console.log(repairPlan(reports));
};

main();

module.exports = { outages, severeOutages, repairPlan, impactOf };

