const mean = (values) => {
  const total = values.reduce((sum, v) => sum + v, 0);
  return total / values.length;
};

const isValidSurvey = (survey) => {
  if (!survey || typeof survey.reef !== 'string' || survey.reef.trim() === '') return false;
  if (typeof survey.depth !== 'number' || Number.isNaN(survey.depth)) return false;
  if (!Array.isArray(survey.transects) || survey.transects.length === 0) return false;
  return survey.transects.every(v => typeof v === 'number' && v >= 0 && v <= 100);
};

const overallBleaching = (survey) => mean(survey.transects);

const SEVERE_THRESHOLD = 40;

const bleaching = (surveys) => {
  const scored = surveys
    .filter(isValidSurvey)
    .map(survey => ({
      reef: survey.reef.trim(),
      depth: survey.depth,
      overall: overallBleaching(survey)
    }));

  const severe = scored.filter(entry => entry.overall > SEVERE_THRESHOLD);
  severe.sort((a, b) => a.depth - b.depth);
  return severe.map(entry => [entry.reef, entry.overall]);
};

const roundTo = (value, digits) => {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
};

