const MIN_DURATION = 120;

const normalizeType = (value) => String(value == null ? '' : value).trim().toLowerCase();

const isSubscriber = (trip) => normalizeType(trip.subscriberType) === 'subscriber';

const durationOf = (trip) => {
  const seconds = Number(trip.duration);
  return Number.isFinite(seconds) ? seconds : 0;
};

const isRealTrip = (trip) => durationOf(trip) >= MIN_DURATION;

const stationOf = (trip) => String(trip.startStation).trim();

const hasEndpoints = (trip) => stationOf(trip).length > 0 && String(trip.endStation).trim().length > 0;

const ridership = (trips) => {
  const counts = new Map();
  trips
    .filter(hasEndpoints)
    .filter(isRealTrip)
    .filter(isSubscriber)
    .forEach(trip => {
      const station = stationOf(trip);
      counts.set(station, (counts.get(station) || 0) + 1);
    });
  return [...counts.entries()].sort((a, b) => b[1] - a[1]);
};

const addCount = (sum, pair) => sum + pair[1];

const totalTrips = (ranking) => ranking.reduce(addCount, 0);

const busiestHub = (ranking) => (ranking.length > 0 ? ranking[0][0] : 'none');

const shareOf = (count, total) => (total === 0 ? 0 : (count / total) * 100);

