const isCrewedSuccess = (mission) => mission.success === true && mission.crew >= 1;

const validateMission = (mission, index) => {
  const required = ['designation', 'year', 'mass', 'crew', 'success'];
  const missing = required.filter(key => !(key in mission));
  if (missing.length > 0) {
    throw new Error(`Mission at index ${index} lacks fields: ${missing.join(', ')}`);
  }
  if (!Number.isInteger(mission.year)) {
    throw new Error(`Mission ${mission.designation} has a non-integer launch year`);
  }
  if (typeof mission.mass !== 'number' || mission.mass < 0) {
    throw new Error(`Mission ${mission.designation} has an invalid payload mass`);
  }
  if (!Number.isInteger(mission.crew) || mission.crew < 0) {
    throw new Error(`Mission ${mission.designation} has an invalid crew size`);
  }
  return mission;
};

const groupByYear = (missions) => {
  const totals = new Map();
  missions.forEach(mission => {
    const current = totals.get(mission.year) || 0;
    totals.set(mission.year, current + mission.mass);
  });
  return totals;
};

const launches = (missions) => {
  const checked = missions.map(validateMission);
  const crewed = checked.filter(isCrewedSuccess);
  const totals = groupByYear(crewed);
  return [...totals.entries()].sort((a, b) => a[0] - b[0]);
};

