const MIN_STOPS = 3;
const MAX_WALK_MILES = 1;

const stopCount = (neighborhood) => neighborhood.stops.length;

const isValidRecord = (record) => {
  if (!record || typeof record.name !== 'string' || record.name.trim() === '') return false;
  if (!Number.isFinite(record.population) || record.population < 0) return false;
  if (!Array.isArray(record.stops)) return false;
  return Number.isFinite(record.avgWalkDistance) && record.avgWalkDistance >= 0;
};

const cleanStops = (stops) => stops
  .map(stop => String(stop).trim())
  .filter(stop => stop !== '');

const normalize = (record) => ({
  name: record.name.trim(),
  population: record.population,
  stops: cleanStops(record.stops),
  avgWalkDistance: record.avgWalkDistance
});

const isWellConnected = (neighborhood) =>
  stopCount(neighborhood) >= MIN_STOPS && neighborhood.avgWalkDistance < MAX_WALK_MILES;

const byPopulationDesc = (a, b) => b.population - a.population;

const transit = (neighborhoods) => {
  if (!Array.isArray(neighborhoods)) {
    throw new TypeError('transit expects an array of neighborhood records');
  }
  return neighborhoods
    .filter(isValidRecord)
    .map(normalize)
    .filter(isWellConnected)
    .sort(byPopulationDesc)
    .map(neighborhood => neighborhood.name);
};

const summarize = (neighborhoods) => {
  const records = neighborhoods.filter(isValidRecord).map(normalize);
  const totalStops = records.reduce((sum, n) => sum + stopCount(n), 0);
  const connected = records.filter(isWellConnected);
  return {
    surveyed: records.length,
    skipped: neighborhoods.length - records.length,
    totalStops,
    connected: connected.length,
    coveredPopulation: connected.reduce((sum, n) => sum + n.population, 0)
  };
};

