const CATEGORIES = ['theme', 'mechanics', 'originality', 'rulesClarity'];

const MIN_CLARITY = 6;

const isValidScore = (value) => Number.isFinite(value) && value >= 0 && value <= 10;

const validate = (design) => {
  if (!design || typeof design.designer !== 'string' || design.designer.trim() === '') {
    throw new TypeError('Each design needs a designer name');
  }
  const bad = CATEGORIES.filter(key => !isValidScore(design[key]));
  if (bad.length > 0) {
    throw new RangeError(`${design.designer}: invalid scores for ${bad.join(', ')}`);
  }
  return design;
};

const addCategory = (sum, key) => sum + key;

const totalScore = (design) => {
  const values = CATEGORIES.map(key => design[key]);
  return values.reduce(addCategory, 0);
};

const qualifies = (design) => design.rulesClarity >= MIN_CLARITY;

const summarise = (design) => ({
  designer: design.designer.trim(),
  total: totalScore(design),
  clarity: design.rulesClarity,
  qualified: qualifies(design),
});

const score = (designs) => designs.map(validate).map(summarise);

const byTotalDescending = (a, b) => b.total - a.total;

const judge = (designs) => {
  if (!Array.isArray(designs)) {
    throw new TypeError('judge expects an array of designs');
  }
  return score(designs)
    .filter(entry => entry.qualified)
    .sort(byTotalDescending)
    .map(entry => entry.designer);
};

const rejectionReport = (designs) => {
  const rejected = score(designs).filter(entry => !entry.qualified);
  return rejected.map(entry => `${entry.designer} (clarity ${entry.clarity}/10)`);
};

