const IDLE = 'idle';
const MIN_BATTERY = 30;

const isIdle = (robot) => robot.status === IDLE;

const deliveryCount = (robot) => (robot.deliveries || []).length;

const hasCharge = (robot) => robot.battery > MIN_BATTERY;

const byLoad = (a, b) => a.load - b.load || a.id.localeCompare(b.id);

const summarize = (robot) => ({
  id: robot.id,
  battery: robot.battery,
  load: deliveryCount(robot)
});

const dispatch = (robots) => {
  const idle = robots.filter(isIdle);
  const ready = idle.map(summarize).filter(hasCharge);
  ready.sort(byLoad);
  return ready.map(entry => entry.id);
};

const totalDeliveries = (robots) =>
  robots.reduce((sum, robot) => sum + deliveryCount(robot), 0);

const formatRoster = (robots) => {
  const lines = robots.map(robot => {
    const load = String(deliveryCount(robot)).padStart(2, ' ');
    const battery = String(robot.battery).padStart(3, ' ');
    return `  ${robot.id.padEnd(8)} ${battery}%  ${load} deliveries  ${robot.status}`;
  });
  return lines.join('\n');
};

