  const randomIndex = Math.floor(Math.random() * choices.length);
  return choices[randomIndex];
};

const determineWinner = function(player, computer) {
  if (player === computer) return 'Tie';

  const winningCombinations = {
    'rock': 'scissors',
    'paper': 'rock',
    'scissors': 'paper',
  };

  return winningCombinations[player] === computer ? 'Win' : 'Loss';
};

const normalizeInput = function(choice) { return choice.toLowerCase(); };

const isValidChoice = function(choice) {
  return ['rock', 'paper', 'scissors'].includes(choice);
};

const playRockPaperScissors = function(playerChoice) {
  const normalizedPlayerChoice = normalizeInput(playerChoice);

  if (!isValidChoice(normalizedPlayerChoice)) {
    throw new Error("Invalid choice. Please choose 'rock', 'paper', or 'scissors'.");
  }

  const computerChoice = getRandomChoice();

  const result = determineWinner(normalizedPlayerChoice, computerChoice);

  return result;
};

