const createRectangle = ([x1, y1, x2, y2]) => ({ left: x1, top: y1, right: x2, bottom: y2 });

const areIntervalsOverlapping = (min1, max1, min2, max2) => Math.max(min1, min2) < Math.min(max1, max2);

const isXOverlap = (r1, r2) => areIntervalsOverlapping(r1.left, r1.right, r2.left, r2.right);

const isYOverlap = (r1, r2) => areIntervalsOverlapping(r1.top, r1.bottom, r2.top, r2.bottom);

const doRectanglesOverlap = (rect1Coords, rect2Coords) => {
  const rect1 = createRectangle(rect1Coords);
  const rect2 = createRectangle(rect2Coords);

  const xOverlap = isXOverlap(rect1, rect2);
  const yOverlap = isYOverlap(rect1, rect2);

  return xOverlap && yOverlap;
};

