const KM_TO_MILES = 0.621371;

const kmToMiles = (km) => km * KM_TO_MILES;

const isValidDistance = (value) => typeof value === 'number' && Number.isFinite(value) && value >= 0;

const parseDistance = (raw) => {
  if (typeof raw === 'number') return raw;
  const trimmed = String(raw).trim().replace(/\s*km$/i, '');
  return trimmed === '' ? NaN : Number(trimmed);
};

const roundTo = (value, digits) => {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
};

const formatRow = (km, miles) => `${roundTo(km, 3).toString().padStart(10)} km = ${roundTo(miles, 5).toString().padStart(12)} mi`;

const convertOne = (raw) => {
  const km = parseDistance(raw);
  if (!isValidDistance(km)) {
    return { input: raw, error: 'not a non-negative finite number' };
  }
  return { input: raw, km, miles: kmToMiles(km) };
};

const convertAll = (inputs) => inputs.map(convertOne);

const buildReport = (results) => {
  const ok = results.filter((r) => r.error === undefined);
  const bad = results.filter((r) => r.error !== undefined);
  const lines = ok.map((r) => formatRow(r.km, r.miles));
  bad.forEach((r) => {
    lines.push(`${String(r.input).padStart(10)}    -> skipped (${r.error})`);
  });
  return lines;
};

const summarize = (results) => {
  const converted = results.filter((r) => r.miles !== undefined);
  const miles = converted.map((r) => r.miles);
  const total = miles.reduce((sum, m) => sum + m, 0);
  const longest = miles.reduce((best, m) => (m > best ? m : best), 0);
  return {
    converted: miles.length,
    skipped: results.length - miles.length,
    totalMiles: roundTo(total, 5),
    longestMiles: roundTo(longest, 5),
    averageMiles: miles.length === 0 ? 0 : roundTo(total / miles.length, 5),
  };
};

const main = () => {
  const inputs = [10, 0, '42.195', '5 km', 1.609344, -3, 'abc', 100];
  const results = convertAll(inputs);

  buildReport(results).forEach((line) => console.log(line));

  const stats = summarize(results);
  console.log('---');
  console.log(`converted: ${stats.converted}, skipped: ${stats.skipped}`);
  console.log(`total: ${stats.totalMiles} mi, average: ${stats.averageMiles} mi, longest: ${stats.longestMiles} mi`);
};

main();

module.exports = { kmToMiles, parseDistance, convertOne, convertAll, buildReport, summarize };

