const findCommonPrefix = (arr) => {
  if (arr.length === 0) return '';
  if (arr.length === 1) return arr[0];

  const firstStr = arr[0];
  let commonPrefix = '';

  for (let i = 0; i < firstStr.length; i++) {
    const char = firstStr[i];
    const allMatch = arr.every(s =>
      i < s.length && s[i] === char
    );
    if (allMatch) {
      commonPrefix += char;
    } else {
      break;
    }
  }
  return commonPrefix;
};

const longestCommonSuffix = (strings) => {
  if (strings.length === 0) return '';

  const reversedStrings = strings.map(s =>
    reverseString(s)
  );

  const commonPrefixOfReversed = findCommonPrefix(reversedStrings);

  const result = reverseString(commonPrefixOfReversed);
  return result;
};

