const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

const validate = (numbers) => {
  if (!Array.isArray(numbers)) {
    throw new TypeError('findMax expects an array of numbers');
  }
  if (numbers.length === 0) {
    throw new RangeError('findMax expects a non-empty array');
  }
  const bad = numbers.findIndex(n => !isFiniteNumber(n));
  if (bad !== -1) {
    throw new TypeError(`element at index ${bad} is not a finite number: ${String(numbers[bad])}`);
  }
};

const findMax = (numbers) => {
  validate(numbers);
  return numbers.reduce((best, current) => (current > best ? current : best), numbers[0]);
};

const findMaxIndex = (numbers) => {
  const max = findMax(numbers);
  return numbers.indexOf(max);
};

const parseList = (text) => {
  const parts = text
    .split(',')
    .map(part => part.trim())
    .filter(part => part.length > 0);
  return parts.map(part => {
    const value = Number(part);
    if (!isFiniteNumber(value)) {
      throw new TypeError(`cannot parse "${part}" as a number`);
    }
    return value;
  });
};

const describe = (numbers) => {
  const max = findMax(numbers);
  const at = findMaxIndex(numbers);
  return `[${numbers.join(', ')}] -> max ${max} at index ${at}`;
};

const describeInput = (input) => {
  try {
    const numbers = typeof input === 'string' ? parseList(input) : input;
    return describe(numbers);
  } catch (err) {
    return `${JSON.stringify(input)} -> error: ${err.message}`;
  }
};

const report = (inputs) => inputs.map(describeInput);

const main = () => {
  const samples = [
    [1, 5, 2, 8, 3],
    [-10, -2, -5],
    [42],
    '3, 1.5, -7, 9.25',
    [],
    [1, 'two', 3],
  ];
  report(samples).forEach(line => console.log(line));
};

if (require.main === module) {
  main();
}

module.exports = { findMax, findMaxIndex, parseList, describe, describeInput, report };

